(window.GIM_TS=window.GIM_TS||{})["Shabbat.7"]={"from":168,"a":[["\u0003כטבלא מרובעת,\u0004 שבערוגה העשויה כריבוע נאמרו כל ההלכות לגבי זריעת מינים אחדים. ומכאן נלמד: \u0003כטבלא\u0004 מרובעת \u0003הוא דשרי\u0004 \u0005[שמותר],\u0006 \u0003הא לאו הכי\u0004 \u0005[הרי\u0006 אם \u0005לא כן]\u0006 — \u0003אסור,\u0004 וזריעת שתי וערב אין בה כדי להפריד בין מין למין, אפילו בעיגול! ענה על כך רב אשי: מה שאמרו טבלה מרובעת אין הכוונה שרק צורה זו בלבד היא המועילה להפריד בין מין למין, אלא \u0003התם לאקולי\u0004 \u0005[שם להקל]\u0006 \u0003בה קולא אחרינא\u0004 \u0005[הקלה אחרת]\u0006 \u0003להתיר ראש תור\u0004 (כצורת משולש) \u0003היוצא הימנה\u0004 (ממנה) ונכנס לשדה אחר. שאם היתה ערוגה עשויה כטבלה מרובעת ונכנס משולש ממנה לשדה אחר הרי זה היכר, ואין צריך בהרחקה נוספת בדבר.","ועוד הלכות שיש להן רמזים בכתוב: \u0003מנין ל\u0004אשה ה\u0003פולטת שכבת זרע\u0004 אף \u0003ביום השלישי\u0004 לאחר ההזדווגות \u0003שתהא טמאה\u0004 כדין הנוגעת בשכבת זרע (עיין ויקרא טו, יז)? שאנו סבורים כי שכבת זרע זו עדיין ראויה להפריה ולכן מוסיפה לטמא — רמז לדבר ממה \u0003שנאמר\u0004 לפני מתן תורה: \"ויאמר אל העם \u0003היו נכונים לשלשת ימים\u0004 אל תגשו אל אשה\" (שמות יט, טו) והרחקה זו של שלושה ימים נאמרה כדי שגם אשה הפולטת שכבת זרע תהיה טהורה. ועוד הלכה שיש לה רמז בכתוב: \u0003מנין שמרחיצין את המילה\u0004 (הילד הנימול) גם \u0003ביום השלישי\u0004 אחרי הברית, ואפילו \u0003חל להיות בשבת?\u0004 — ממה \u0003שנאמר: \"ויהי ביום השלישי בהיותם כואבים\"\u0004 (בראשית לד, כה), ומכן שכאב המילה נמשך לפחות שלושה ימים, וכל עוד קיים הכאב הנימול בחזקת סכנה. ועוד הלכה שיש לה רמז כעין זה במקרא: \u0003מנין שקושרין לשון של זהורית\u0004 (צמר אדום) \u0003בראש\u0004 ה\u0003שעיר המשתלח\u0004 לעזאזל? — ממה \u0003שנאמר: \"אם יהיו חטאיכם כשנים כשלג ילבינו\"\u0004 (ישעיה א, יח), וכיון שהשעיר בא לכפרת עוונות קושרים בו צמר אדום. וכן \u0003מנין לסיכה\u0004 בשמן \u0003שהיא כשתייה\u0004 ואסורה כמותה \u0003ביום הכפורים? אף על פי שאין ראיה לדבר\u0004 מכל מקום יש \u0003זכר לדבר, שנאמר: \"ותבא כמים בקרבו וכשמן בעצמותיו\"\u0004 (תהלים קט, יח), שנראה שהכתוב משווה שמן שסכים בו למי שתיה.","על ההלכות המובאות במשנה מעירים: האם \u0003רישא\u0004 \u0005[ראש\u0006 המשנה\u0005]\u0006 העוסק באשה הפולטת שכבת זרע הוא \u0003דלא\u0004 \u0005[אינו]\u0006 \u0003כ\u0004שיטת \u0003ר' אלעזר בן עזריה,\u0004 ואילו \u0003סיפא\u0004 \u0005[סופה]\u0006 העוסק בענין המילה הוא כן \u0003כ\u0004שיטת \u0003ר' אלעזר בן עזריה? דאי\u0004 \u0005[שאם]\u0006 אף ראשה הוא \u0003כ\u0004שיטת \u0003ר' אלעזר בן עזריה\u0004 הלא במקרה זה שהאשה \u0003טהורה שמענא ליה\u0004 \u0005[שמענו אותו\u0006 שאמר\u0005].\u0006 ומסבירים: \u0003מאן דלא מוקי כתנאי\u0004 \u0005[מי שאינו מעמיד,\u0006 מסביר, משנה \u0005כ\u0006דעת שני \u0005תנאים]\u0006 \u0003תנא רישא\u0004 \u0005[שונה\u0006 בראש\u0005]\u0006 בגירסה אחרת: \u0003\"טהורה\", ו\u0004ממילא \u0003מוקי לה\u0004 \u0005[ומעמיד את]\u0006 \u0003כולה כ\u0004שיטת \u0003ר' אלעזר בן עזריה, ומאן דמוקים כתנאי\u0004 \u0005[ומי שמעמיד\u0006 משנה \u0005כ\u0006דעת שני \u0005תנאים]\u0006 הרי \u0003רישא רבנן וסיפא\u0004 \u0005[ראשה\u0006 שיטת \u0005חכמים וסופה]\u0006 \u0003כ\u0004שיטת \u0003ר' אלעזר בן עזריה.\u0004","וכדי לבאר את הענין מביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003פולטת שכבת זרע ביום השלישי\u0004 בכל שעה ביום \u0003טהורה,\u0004 אלו \u0003דברי ר' אלעזר בן עזריה. ר' ישמעאל אומר:\u0004 אף ביום השלישי טמאה, ואין חושבים את השעות שעברו, ודנים לפי מנין הימים בלבד, \u0003פעמים שהן ארבע עונות\u0004 (ארבע תקופות זמן של שתים עשרה שעות), שאם הזדווגה בסוף הלילה ופלטה בתחילת הבוקר השלישי נחשב הדבר כאילו עברו שלושה ימים, שהם למעשה ארבע עונות. ו\u0003פעמים שהן חמש עונות,\u0004 כגון שפלטה בסוף היום, ו\u0003פעמים שהן שש עונות\u0004 אם הזדווגה בתחילת הלילה ופלטה בסוף היום השלישי. \u0003ר' עקיבא אומר: לעולם\u0004 להלכה \u0003חמש\u0004 עונות הן, \u0003ואם יצאתה\u0004 (יצאה) \u0003מקצת עונה ראשונה,\u0004 שפלטה לאחר תחילת העונה הראשונה, \u0003נותנין לה\u0004 תמורת אותו זמן \u0003מקצת עונה ששית\u0004 כדי להשלים לחמש עונות שלמות, ושומרים על הפרש של ששים שעות.","\u0003אמרוה רבנן קמיה\u0004 \u0005[חכמים לפני]\u0006 \u0003רב פפא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב פפא לרבא בשלמא\u0004 \u0005[נניח]\u0006 \u0003ר' אלעזר בן עזריה\u0004 הרי הוא סובר \u0003כרבנן דאמרי\u0004 \u0005[כ\u0006שיטת \u0005חכמים האומרים]\u0006 בענין יום מתן תורה, ש\u0003ב\u0004יום ה\u0003חמישי\u0004 בשבוע \u0003עביד\u0004 \u0005[עשה,\u0006 תיקן\u0005]\u0006 משה לישראל \u0003פרישה\u0004 מנשיהם. וכיון שלדעת הכל בשבת ניתנה התורה, ונמצא שפרשו יומיים מנשיהם, כדעת ר' אלעזר בן עזריה. ואילו \u0003ר' ישמעאל\u0004 דעתו \u0003כ\u0004שיטת \u0003ר' יוסי\u0004 ש\u0003אמר\u0004 ש\u0003ב\u0004יום ה\u0003רביעי\u0004 בשבוע \u0003עביד\u0004 \u0005[עשה]\u0006 משה \u0003פרישה\u0004 לישראל ונמצא שפרשו שלושה ימים. \u0003אלא ר' עקיבא כמאן\u0004 \u0005[כמי]\u0006 סבור הוא? הלא הוא אינו חושב לפי ימים אלא לפי העונות, ולפי איזו שיטה בקביעת מתן תורה נאמרו דבריו? ומשיבים: \u0003לעולם\u0004 תפרש שסבור ר' עקיבא \u0003כ\u0004שיטת \u0003ר' יוסי,\u0004 אלא שהבין כפי ש\u0003אמר רב אדא בר אהבה: משה בהשכמה עלה\u0004 להר סיני \u0003ובהשכמה ירד\u0004 והזהיר את העם לפרוש.","ומסבירים את המקור לשיטה זו: \u0003בהשכמה עלה\u0004 להר סיני, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"וישכם משה בבקר ויעל אל הר סיני\u0004 כאשר ציוה ה' אותו\" (שמות לד, ד) ו\u0003בהשכמה ירד\u0004 מן ההר, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"לך רד ועלית אתה ואהרן עמך\"\u0004 (שמות יט, כד), \u0003מקיש\u0004 \u0005[משווה]\u0006 הכתוב \u0003ירידה לעלייה; מה עלייה\u0004 של משה היתה תמיד \u0003בהשכמה, אף ירידה\u0004 שלו היתה \u0003בהשכמה,\u0004 והוצרך משה להפריש את העם בהשכמה כדי שבתוך שלושת הימים יהיו חמש עונות שלמות של פרישות.","ושואלים: \u0003למה ליה למימרא להו\u0004 \u0005[לו לומר להם]\u0006 בשעות הבוקר לפרוש: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב הונא: ישראל קדושים הן ואין משמשין מטותיהן ביום,\u0004 ולא הוצרך להזהיר אלא משעות הלילה! ומשיבים: בכל זאת היה צורך בהפרשה, שכן \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר רבא: אם היה\u0004 זה \u0003בית אפל\u0004 — \u0003מותר\u0004 לשמש אף ביום. \u0003ו\u0004כן \u0003אמר רבא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר את \u0003רב פפא: תלמיד חכם\u0004 אפילו ביום, \u0003מאפיל בטליתו, ומותר\u0004 לשמש. הרי שאף בשעות היום יש צורך בהפרשה."],["ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 אם כן לכל השיטות \u0003טבולי יום נינהו\u0004 \u0005[\u0006היו \u0005הם],\u0006 בני ישראל בשעת קבלת התורה, שהרי היו נשים שטבלו לאחר שנטמאו מפליטת הזרע עוד בליל שבת, ומי שלא העריבה השמש אחר טבילתו נקרא \"טבול יום\", ואינו טהור לכל דבר. \u0003אביי בר רבין ורב חנינא בר אבין דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם]\u0006 כתשובה לכך: \u0003ניתנה תורה לטבול יום,\u0004 ואין בכך גנות. מסופר: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003מרימר וקאמר לה להא שמעתא\u0004 \u0005[ואמר אותה, את ההלכה זו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא למרימר:\u0004 האם \u0003ניתנה\u0004 התורה לטבולי יום \u0003קאמרת\u0004 \u0005[אומר אתה],\u0006 \u0003או ראויה\u0004 היתה להינתן לטבולי יום לפני זמני הפרישה, אך למעשה היו כולם טהורים לגמרי בשעת מתן תורה \u0003קאמרת\u0004 \u0005[אומר אתה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 מרימר: \u0003ראויה קאמינא\u0004 \u0005[אמרתי],\u0006 אבל למעשה ניתנה התורה לטהורים ולא פלטו הנשים ביום השלישי.","ושואלים: \u0003וליטבלו ביני שימשי, וליקבלו\u0004 \u0005[ושיטבלו בין השמשות,\u0006 כלומר, בליל שבת \u0005ושיקבלו]\u0006 את ה\u0003תורה\u0004 מעט אחר כך \u0003ביני שימשי\u0004 \u0005[בין השמשות,\u0006 בליל שבת\u0005],\u0006 ומדוע חיכו עד הבוקר של יום השבת? \u0003אמר ר' יצחק:\u0004 על דבר זה אמר הכתוב \u0003\"לא מראש בסתר דברתי\"\u0004 (ישעיהו מח, טז), כלומר, כשנתן ה' את התורה בתחילה לא נתנה בהסתר ובחשכה, אלא באור יום. ושואלים: \u0003וליטבלו בצפרא דשבתא, וליקבלו\u0004 \u0005[ושיטבלו בבוקר\u0006 יום \u0005השבת, ויקבלו]\u0006 \u0003תורה בצפרא דשבתא\u0004 \u0005[בבוקר\u0006 יום \u0005השבת],\u0006 ועל ידי כך יוכלו לכל השיטות להתחיל את הפרישה באיחור עונה אחת! \u0003אמר ר' יצחק: שלא יהא הללו הולכין לקבל תורה והללו הולכין לטבילה,\u0004 אלא יהא כל העם מוכן לקבלת התורה.","\u0003אמר ר' חייא בר' אבא\u0004 שכך \u0003אמר ר' יוחנן:\u0004 כל \u0003זו\u0004 שאמרנו \u0003דברי ר' ישמעאל ור' עקיבא\u0004 היא, \u0003אבל חכמים אומרים: שש עונות שלמות בעינן\u0004 \u0005[צריכים אנו],\u0006 ואם פלטה בפחות מזה עדיין מטמאה שכבת הזרע. \u0003אמר רב חסדא:\u0004 ה\u0003מחלוקת\u0004 עד מתי טמאה שכבת הזרע הריהי רק כ\u0003שפירשה\u0004 שכבת הזרע \u0003מן האשה, אבל פירשה מן האיש,\u0004 וכגון שנמצאה על בגד — \u0003טמאה כל זמן שהיא לחה,\u0004 בלא לחלק כמה זמן עבר מזמן פליטתה. \u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב ששת\u0004 ממה ששנינו בברייתא: את הכתוב \u0003\"וכל בגד וכל עור אשר יהיה עליו שכבת זרע\u0004 וכובס במים וטמא עד הערב\u0003\"\u0004 (ויקרא טו, יז) דרשו חכמים: \u0003פרט לשכבת זרע שהיא סרוחה. מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כ\u0003שפירשה מן האיש,\u0004 ונמצא שאף שכבת זרע לחה, לאחר זמן מסויים הריהי מתקלקלת ומפסיקה לטמא. ודוחים: \u0003לא,\u0004 אף הלכה זו נאמרה בשכבת זרע \u0003שפירשה מן האשה.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא: שכבת זרע של ישראל במעי גויה מהו\u0004 הדין בכגון זה? האם נאמר שלענין זה \u0003ישראל דדאיגי\u0004 \u0005[שדואגים]\u0006 \u0003במצות\u0004 — \u0003חביל גופייהו\u0004 \u0005[חם גופם]\u0006 ושכבת זרע שלא נקלטה מתקלקלת מהר יותר, ואילו \u0003גוים דלא דאיגי\u0004 \u0005[שאינם דואגים]\u0006 \u0003במצות\u0004 — \u0003לא. או דילמא\u0004 \u0005[שמא]:\u0006 \u0003כיון דאכלין\u0004 \u0005[ש\u0006הם, הגוים \u0005אוכלים]\u0006 \u0003שקצים ורמשים\u0004 גם הם \u0003חביל גופייהו\u0004 \u0005[\u0006\u0005חם גופם].\u0006 \u0003ואם תמצי\u0004 \u0005[תרצה]\u0006 לקבל את ההנחה הזו ו\u0003לומר\u0004 כי \u0003כיון דאכלי\u0004 \u0005[ש\u0006הם \u0005אוכלים]\u0006 \u0003שקצים ורמשים חביל גופייהו\u0004 \u0005[חם גופם],\u0006 יש מקום לשאול: שכבת זרע של ישראל \u0003במעי בהמה מהו?\u0004 האם נאמר ש\u0003אשה היא דאית\u0004 \u0005[שיש]\u0006 \u0003לה פרוזדור\u0004 ארוך לרחם, ולכן \u0003מסרחת\u0004 שכבת הזרע, \u0003אבל בהמה דלית\u0004 \u0005[שאין]\u0006 \u0003לה פרוזדור\u0004 באורך יחסי כזה — \u0003לא. או דילמא\u0004 \u0005[שמא]\u0006 \u0003לא שנא\u0004 \u0005[אינו שונה],\u0006 וכל אלה שיעורם שווה. לשאלות אלה לא נמצאה תשובה, ועל כן \u0003תיקו\u0004 \u0005[תעמודנה]\u0006 במקומן.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בששי בחדש\u0004 סיון \u0003ניתנו עשרת הדברות לישראל. ר' יוסי אומר: בשבעה בו. אמר רבא: דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003בראש חדש\u0004 סיון \u0003אתו\u0004 \u0005[באו]\u0006 בני ישראל \u0003למדבר סיני,\u0004 שכן \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"\u0004בחודש השלישי לצאת בני ישראל מארץ מצרים \u0003ביום הזה באו מדבר סיני\"\u0004 (שמות יט, א), ולא נתפרש באיזה יום, \u0003וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"החדש הזה לכם ראש חדשים\u0004 ראשון הוא לכם לחדשי השנה\u0003\"\u0004 (שמות יב, ב) \u0003מה להלן\u0004 \"החודש הזה\" משמעו — \u0003ראש חדש, אף כאן\u0004 — \u0003ראש חדש. ו\u0004כן \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003בשבת ניתנה תורה לישראל,\u0004 שכן \u0003כתיב הכא\u0004 \u0005[נאמר כאן,\u0006 בעשרת הדברות\u0005]:\u0006 \u0003\"זכור את יום השבת לקדשו\"\u0004 (שמות כ, ח), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"ויאמר משה אל העם זכור את היום הזה\u0004 אשר יצאתם ממצרים מבית עבדים כי בחוזק יד הוציא ה' אתכם מזה ולא יאכל חמץ\u0003\"\u0004 (שמות יג, ג) \u0003מה להלן\u0004 ביציאת מצרים נאמרה מצוות הזכירה \u0003בעצומו\u0004 (בתוכו) \u0003של יום\u0004 אותו צריכים הם לזכור שהוא יום היציאה, \u0003אף כאן\u0004 נאמרה זכירת יום השבת \u0003בעצומו של יום\u0004 השבת. \u0003כי פליגי בקביעא דירחא\u0004 \u0005[כאשר נחלקו\u0006 ר' יוסי וחכמים היה זה \u0005בקביעת החודש],\u0006 כלומר, באיזה יום בשבוע חל אז ראש החודש. \u0003ר' יוסי סבר\u0004 \u0005[סבור]:\u0006 \u0003בחד בשבא איקבע ירחא\u0004 \u0005[באחד בשבת נקבע\u0006 ראש \u0005החודש],\u0006 \u0003ובחד בשבא\u0004 \u0005[ובאחד בשבת]\u0006 \u0003לא אמר להו\u0004 \u0005[להם]\u0006 \u0003ולא מידי\u0004 \u0005[דבר]\u0006 \u0003משום חולשא דאורחא\u0004 \u0005[חולשת הדרך],\u0006 \u0003בתרי בשבא\u0004 \u0005[בשני בשבת]\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003\"ואתם תהיו לי ממלכת כהנים\u0004 וגוי קדוש\u0003\"\u0004 (שמות יט, ו)."],["\u0003בתלתא\u0004 \u0005[בשלישי\u0006 בשבת\u0005]\u0006 \u0003אמר\u0004 וציוה \u0003להו\u0004 \u0005[להם,\u0006 אותם\u0005]\u0006 את \u0003מצות הגבלה בארבעה\u0004 בשבת \u0003עבוד\u0004 \u0005[עשו]\u0006 \u0003פרישה. ו\u0004אילו \u0003רבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003בתרי בשבא איקבע ירחא\u0004 \u0005[בשני בשבת נקבע\u0006 ראש \u0005החודש],\u0006 \u0003בתרי בשבא\u0004 \u0005[\u0006ו\u0005בשני בשבת]\u0006 \u0003לא אמר להו\u0004 \u0005[להם]\u0006 \u0003ולא מידי\u0004 \u0005[דבר],\u0006 \u0003משום חולשא דאורחא\u0004 \u0005[חולשת הדרך],\u0006 \u0003בתלתא\u0004 \u0005[בשלישי\u0006 בשבת\u0005]\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003\"ואתם תהיו לי\u0004 ממלכת כהנים וגוי קדוש אלה הדברים אשר תדבר אל בני ישראל\u0003\"\u0004 (שמות יט, ו). \u0003בארבעה אמר להו\u0004 \u0005[להם]\u0006 \u0003מצות הגבלה,\u0004 ו\u0003בחמישי\u0004 בשבת \u0003עבוד\u0004 \u0005[עשו]\u0006 \u0003פרישה. מיתיבי\u0004 \u0005[מקשים]\u0006 על כך: והרי בכתוב נאמר \"ויאמר ה' אל משה לך אל העם \u0003וקדשתם היום ומחר\u0004 וכיבסו שמלותם\" (שמות יט, י), והרי שהפרישה היתה ליומיים בלבד, ו\u0003קשיא\u0004 \u0005[קשה]\u0006 אם כן \u0003ל\u0004שיטת \u0003ר' יוסי\u0004 שאמר ששלושה ימים פרשו!","ומתרצים, \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך ר' יוסי: יום אחד הוסיף משה מדעתו\u0004 על הימים שקבע הקדוש ברוך הוא. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שלשה דברים עשה משה מדעתו, והסכים הקדוש ברוך הוא עמו.\u0004 והם: \u0003הוסיף יום אחד מדעתו\u0004 לפרישה לפני מתן תורה. \u0003ופירש מן האשה\u0004 לגמרי לאחר מתן תורה, \u0003ושבר את הלוחות\u0004 אחר מעשה העגל.","ומבארים את הדברים: זה ש\u0003הוסיף יום אחד מדעתו, מאי דריש\u0004 \u0005[מה,\u0006 על סמך מה, \u0005דרש]\u0006 שהחליט להוסיף יום אחד? שאמר: כיון שאמר לו הקדוש ברוך הוא \u0003\"היום ומחר\"\u0004 צריך שיהיה \u0003היום כמחר; מה למחר\u0004 יהא זה יום ו\u0003לילו עמו,\u0004 שאף בלילה הקודם לו ינהגו מצוות פרישה, כמו כן \u0003אף היום לילו עמו.\u0004 וכיון שנאמרה לו נבואה זו בשעות הבוקר \u0003ולילה דהאידנא נפקא ליה\u0004 \u0005[והלילה של עכשיו,\u0006 היום \u0005יצא,\u0006 עבר \u0005לו],\u0006 \u0003שמע מינה תרי יומי לבר מהאידנא\u0004 \u0005[למד ממנה\u0006 כי \u0005שני ימים\u0006 לפרוש הם \u0005חוץ מ\u0006היום \u0005של עכשיו]\u0006 ודחה את מצוות הפרישה ביום אחד. \u0003ומנלן\u0004 \u0005[ומנין לנו]\u0006 ש\u0003הסכים הקדוש ברוך הוא על ידו\u0004 — ש\u0003לא שריא\u0004 \u0005[שרתה]\u0006 ה\u0003שכינה עד צפרא דשבתא\u0004 \u0005[בוקר\u0006 יום \u0005השבת]\u0006 כפי שקבע משה.","\u0003ופירש מן האשה, מאי דריש\u0004 \u0005[מה,\u0006 על סמך מה, \u0005דרש]\u0006 שהחליט על פרישה מוחלטת זו — \u0003נשא קל וחומר בעצמו; אמר: ומה ישראל שלא דברה שכינה עמהן אלא שעה אחת, ו\u0004עוד ש\u0003קבע להן זמן\u0004 מתי יהא גילוי שכינה, עם זאת \u0003אמרה תורה \"היו נכנים\u0004 לשלשת ימים \u0003אל תגשו\u0004 אל אשה\u0003\"\u0004 (שמות יט, טו), \u0003אני, שכל שעה ושעה שכינה מדברת עמי, ואינו קובע לי זמן\u0004 — \u0003על אחת כמה וכמה\u0004 שחייב אני בפרישה. \u0003ומנלן\u0004 \u0005[ומנין לנו]\u0006 ש\u0003הסכים הקדוש ברוך הוא על ידו\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 לאחר מתן תורה: \u0003\"לך אמר להם שובו לכם לאהליכם\"\u0004 (דברים ה, כז) וכוונתו — לבתיכם ולנשיכם, \u0003וכתיב בתריה\u0004 \u0005[ונאמר אחריו]\u0006 שלמשה אמר: \u0003\"ואתה פה עמד עמדי\"\u0004 (שמות יט, כח), הרי שלא הותר למשה לשוב לביתו, ועליו להיות מוכן תמיד לקבלת דבר ה'. \u0003ואית דאמרי\u0004 \u0005[ויש שאומרים]\u0006 ראיה אחרת שהסכים ה' על ידו, שכאשר התרעמו אהרן ומרים על משה שפירש מאשתו, אמר הקדוש ברוך הוא: \u0003\"פה אל פה אדבר בו\u0004 ומראה ולא בחידות ותמונת ה' יביט ומדוע לא יראתם לדבר בעבדי במשה\u0003\"\u0004 (במדבר יב, ח), הרי שהסכים ה' שיפה עשה.","ומה ש\u0003שבר את הלוחות, מאי דריש\u0004 \u0005[מה,\u0006 על סמך מה, \u0005דרש]\u0006 שהחליט לשברן — \u0003אמר: ומה פסח שהוא אחד\u0004 בלבד \u0003מתרי\"ג מצות, אמרה תורה\u0004 ביחס אליו \u0003\"\u0004ויאמר ה' אל משה ואהרן זאת חוקת הפסח \u0003כל בן נכר לא יאכל בו\"\u0004 (שמות יב, מג), ומפרשים שהכוונה אינה רק לגוי (\"בן נכר\") ממש, אלא אף לישראלי מומר. וכאן הלא מדובר ביחס ל\u0003התורה כולה וישראל\u0004 הרי היו \u0003משומדים\u0004 באותה שעה, שהרי היו עובדים לעגל, ו\u0003על אחת כמה וכמה\u0004 שאינם ראויים לקבל את התורה. \u0003ומנלן\u0004 \u0005[ומנין לנו]\u0006 ש\u0003הסכים הקדוש ברוך הוא על ידו\u0004 — \u0003שנאמר:\u0004 \"הלוחות הראשונים \u0003אשר שברת\"\u0004 (שמות לד, א) \u0003ואמר ריש לקיש:\u0004 \"אשר\" כאן משמעו — \u0003יישר כחך ששיברת.\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 קושיה נוספת: והלא נאמר \u0003\"והיו נכנים ליום השלישי\u0004 כי ביום השלישי ירד ה' לעיני כל העם על הר סיני\" (שמות יט, יא), הרי שאמר הקדוש ברוך הוא שתינתן התורה רק אחר שני ימי פרישה, \u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003לר' יוסי\u0004, ומתרצים: \u0003הא אמרינן\u0004 \u0005[הרי אמרנו]\u0006 \u0003יום אחד הוסיף משה מדעתו. תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נגד זה ממה ששנינו בברייתא: האמור בתורה \u0003\"\u0004ליום ה\u0003שלישי\"\u0004 כוונתו — \u0003שלישי בחדש ושלישי בשבת,\u0004 הרי שראש החודש היה ביום הראשון, ו\u0003קשיא\u0004 \u0005[קשה]\u0006 אם כן \u0003לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]!\u0006 ומשיבים: \u0003אמרי\u0004 \u0005[\u0006יכולים \u0005לומר]\u0006 \u0003לך רבנן\u0004 \u0005[חכמים]:\u0006 \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 שיטת \u0005מי\u0006 היא] — שיטת \u0003ר' יוסי היא,\u0004 ואין להקשות אם כן ממנה לשיטת חכמים.","ולשיטתם \u0003שלישי למאי\u0004 \u0005[למה]?\u0006 \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005].\u0006 ששנינו: נאמר \u0003\"וישב משה את דברי העם אל ה'\"\u0004(שמות יט, ח), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 מיד אחר כך: \u0003\"\u0004ויאמר ה' אל משה הנה אנכי בא אליך בעב הענן בעבור ישמע העם בדברי עמך וגם בך יאמינו לעולם \u0003ויגד משה את דברי העם אל ה'\"\u0004 (שמות יט, ט).","ושואלים: \u0003מה אמר לו הקדוש ברוך הוא למשה, ומה אמר להם משה לישראל, ומה אמרו ישראל למשה ומה השיב משה לפני הגבורה?\u0004 שלא נתפרש בכתובים שום דבר מסויים של ציווי שאמר ה' והודיעו משה לפני ישראל וקיבלוהו עליהם! אלא יש לומר כי \u0003זו מצות הגבלה\u0004 שאמר לעם וקיבלו עליהם, וחזר והודיע לה' שקיבלו עליהם, אלו \u0003דברי ר' יוסי בר יהודה. רבי אומר: בתחילה פירש עונשה\u0004 של תורה וכל הקשיים שבה, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"וישב משה\",\u0004 ומדרשו: שאמר \u0003דברים שמשבבין\u0004 (משברים. רה\"ג) \u0003דעתו של אדם, ולבסוף פירש מתן שכרה, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויגד משה\",\u0004 ומשמעו — \u0003דברים שמושכין לבו של אדם כאגדה. ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 ש\u0003בתחילה פירש\u0004 להם \u0003מתן שכרה, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"וישב משה\"\u0004 ומדרשו — שהוא \u0003דברים שמשיבין\u0004 ומרגיעים \u0003דעתו של אדם, ולבסוף פירש עונשה, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויגד משה\"\u0004 — \u0003דברים שקשין לאדם כגידין\u0004 (לענה).","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הוכחה לדבר ממה ששנינו בברייתא: שיום ה\u0003ששי\u0004 היה אז \u0003ששי בחודש\u0004 ו\u0003ששי בשבת,\u0004 ואף זה \u0003קשיא לרבנן\u0004 \u0005[קשה\u0006 לשיטת \u0005חכמים]!\u0006 ומשיבים: \u0003הא נמי\u0004 \u0005[\u0006ברייתא \u0005זו גם כן]\u0006 כשיטת \u0003ר' יוסי היא.\u0004 ואם כן לדברי חכמים \u0003ששי\u0004 זה \u0003למאי\u0004 \u0005[למה],\u0006 לאיזה חשבון נמנה? \u0003רבא אמר:\u0004"],["\u0003לחנייתן. רב אחא בר יעקב אמר:\u0004 ששי \u0003למסען\u0004 מרפידים. שביום השבת שחנו בו גם נסעו מרפידים. \u0003וקמיפלגי\u0004 \u0005[וחלוקים]\u0006 רבא ורב אחא בר יעקב \u0003ב\u0004ענין \u0003שבת\u0004 שנצטוו עליה בני ישראל ב\u0003מרה. דכתיב\u0004 \u0005[ש\u0006כן נאמר]: שנאמר בעשרת הדברות \u0003\"\u0004שמור את יום השבת לקדשו \u0003כאשר צוך ה' אלהיך\"\u0004 (דברים ה, יב), \u0003ואמר רב יהודה\u0004 שכך \u0003אמר רב: \"כאשר צוך\"\u0004 — \u0003במרה,\u0004 שנאמר: \"שם שם לו חוק ומשפט ושם נסהו\" (שמות טו, כה). ובכך נחלקו; \u0003מר סבר\u0004 \u0005[חכם\u0006 אחד \u0005סבור]\u0006 שעל ה\u0003שבת איפקוד\u0004 \u0005[נצטוו],\u0006 ואילו על ה\u0003תחומין לא איפקוד\u0004 \u0005[נצטוו].\u0006 ולכן יכלו לנסוע מרפידים ביום השבת, שהרי עדיין לא נאסר להם לצאת מחוץ לתחום. \u0003ומר סבר\u0004 \u0005[וחכם\u0006 אחד \u0005סבור]\u0006 שעל ה\u0003תחומין נמי אפקוד\u0004 \u0005[גם כן נצטוו],\u0006 וכיון שכך לא יצאו בשבת ממקומם.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הוכחה נוספת ביחס ליום מתן תורה ממה ששנינו בברייתא: \u0003ניסן שבו יצאו ישראל ממצרים, בארבעה עשר\u0004 בו \u0003שחטו פסחיהם, ובחמישה עשר\u0004 בו \u0003יצאו\u0004 ממצרים, \u0003ולערב לקו\u0004 ה\u0003בכורות.\u0004 ותוהים: \u0003לערב סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר?! וכי לקו אחרי יציאת מצרים?! \u0003אלא\u0004 יש לגרוס: \u0003מבערב לקו\u0004 ה\u0003בכורות, ואותו היום חמישי בשבת היה.\u0004 ומכאן נסיק: \u0003מדחמיסר\u0004 \u0005[מכיון שחמישה עשר]\u0006 \u0003בניסן\u0004 ביום \u0003חמשה בשבת\u0004 היה, אם כן \u0003ריש ירחא\u0004 \u0005[ראש\u0006 \u0003חודש] אייר שבתא\u0004 \u0005[שבת]\u0006 היה, שחודש ניסן הריהו כרגיל בן שלושים יום. \u0003וריש ירחא\u0004 \u0005[וראש חודש]\u0006 \u0003סיון חד\u0004 \u0005[אחד]\u0006 \u0003בשבת\u0004 היה, שחודש אייר הוא בן עשרים ותשעה יום, ואם כן \u0003קשיא לרבנן\u0004 \u0005[קשה\u0006 הדבר \u0005ל\u0006שיטת \u0005חכמים]\u0006 הסבורים שבאותה שנה היה ראש חודש סיון ביום שני!","ואומרים כי לשיטת חכמים חודש \u0003אייר דההיא שתא עבורי עברוה\u0004 \u0005[של אותה שנה עיברוהו],\u0006 ואף הוא היה אם כן בן שלושים יום. כיון שאז נקבעו ראשי חדשים על פי עדות ראייה ולפי מולד הירח ויתכן שיהיה חודש אייר אף הוא בן שלושים יום ונמצא שחל ראש חודש סיון ביום שני. \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 להקשות על כך ממה שמשמע בברייתא אחרת ש\u0003לא עברוה\u0004 \u0005[עיברוהו],\u0006 שאמרו חכמים: חודש \u0003ניסן שבו יצאו ישראל ממצרים, בארבעה עשר\u0004 בו \u0003שחטו\u0004 את \u0003פסחיהם, בחמשה עשר\u0004 בו \u0003יצאו, ולערב לקו\u0004 ה\u0003בכורות.\u0004 ושואלים: \u0003לערב סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר?! וכי לקו לאחר יציאת מצרים? \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003מבערב לקו בכורות. ואותו היום חמישי בשבת היה. השלים ניסן\u0004 שהיה חודש מלא בן שלושים יום \u0003ואירע\u0004 ראש חודש \u0003אייר להיות בשבת.\u0004","\u0003חסר\u0004 היה חודש \u0003אייר,\u0004 שהיה רק בן עשרים ותשעה ימים, \u0003ואירע סיון להיות באחד בשבת,\u0004 ואם כן \u0003קשיא לרבנן\u0004 \u0005[קשה\u0006 הדבר \u0005ל\u0006שיטת \u0005חכמים]!\u0006 ומשיבים: \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו של מי היא]\u0006 — כדעת \u0003ר' יוסי היא\u0004 ואין להקשות ממנה לחכמים.","\u0003אמר רב פפא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת ממה שנאמר בכתוב אחר, שנאמר: \u0003\"ויסעו מאלים ויבאו כל עדת בני ישראל\u0004 אל מדבר סין אשר בין אילים ובין סיני \u0003בחמשה עשר יום לחדש השני\u0004 לצאתם מארץ מצרים\u0003\"\u0004 (שמות טז, א), \u0003ואותו היום שבת היה, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ובקר וראיתם את כבוד ה'\u0004 בשמעו את תלונותיכם על ה' ונחנו מה כי תלינו עלינו\u0003\"\u0004 (שמות טז, ז), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 שלמחרת נגלה כבוד ה', ואמר להם שבין הערביים יתחילו לרדת המן והשלו, \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ששת ימים תלקטהו\u0004 וביום השביעי שבת לא יהיה בו\u0003\"\u0004 (שמות טז, כו), הרי שבששת הימים הראשונים אחר התגלות זו היו ימי החול שבהם ירד מן. ומכאן שיום החמישה עשר עצמו שבת היה. \u0003ומדחמיסר\u0004 \u0005[ומזה שחמישה עשר]\u0006 \u0003באייר שבתא\u0004 \u0005[שבת]\u0006 היה, אם כן \u0003ריש ירחא\u0004 \u0005[ראש חודש]\u0006 \u0003סיון חד\u0004 \u0005[אחד]\u0006 \u0003בשבת\u0004 היה, ואם כן \u0003קשיא לרבנן\u0004 \u0005[קשה ל\u0006שיטת \u0005חכמים]!\u0006 ומשיבים: לשיטת חכמים \u0003אייר דההיא שתא עבורי עברוה\u0004 \u0005[של אותה שנה עברותו],\u0006 והיו בו שלושים יום, ולכן חל ראש חודש סיון ביום השני בשבת.","ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חביבי מחוזנאה לרב אשי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראייה אחרת לדבר ממה שנאמר: \u0003\"ויהי בחדש הראשון בשנה השנית באחד לחדש הוקם המשכן\"\u0004 (שמות מ, יז), ועל כך \u0003תנא\u0004 \u0005[שנינו]:\u0006 \u0003אותו יום נטל עשר עטרות;\u0004 שהיה זה יום \u0003ראשון למעשה בראשית,\u0004 כלומר, יום ראשון בשבת, \u0003ראשון\u0004 להקריב בו קרבן ה\u0003נשיאים, ראשון לכהונה, ראשון לעבודה\u0004 במקדש, \u0003ראשון לירידת האש\u0004 על המזבח, \u0003ראשון לאכילת קדשים, ראשון לשכון שכינה\u0004 בישראל, \u0003ראשון לברך\u0004 ברכת כהנים \u0003את ישראל, ראשון לאיסור הבמות,\u0004 שמהקמת המשכן ואילך נאסר להקריב לה' בכל במה אחרת, \u0003ראשון לחדשים. ומדריש ירחא\u0004 \u0005[ומכיון שראש חודש]\u0006 \u0003ניסן דהאי שתא חד\u0004 \u0005[של שנה זו\u0006 ביום \u0005אחד]\u0006 \u0003בשבת,\u0004 אם כן לפי חשבון זה \u0003דאשתקד\u0004 (של השנה שעברה) \u0003ברביעי בשבת\u0004 היה.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אחרים אומרים: אין בין עצרת לעצרת\u0004 (חג השבועות בשנה אחת וחג השבועות בשנה שאחריה), \u0003ו\u0004כן \u0003אין בין ראש השנה לראש השנה\u0004 של שתי שנים \u0003אלא\u0004 הבדל \u0003ארבעה ימים בלבד\u0004 בימי השבוע, \u0003ואם היתה\u0004 ביניהם \u0003שנה מעוברת\u0004 — \u0003חמשה\u0004 ימים. שבכל שנה יש תמיד שלש מאות חמישים וארבעה יום, ובין החדשים תמיד ששה חדשים מלאים (בני שלושים יום) וששה חדשים חסרים (בני עשרים ותשעה יום). ולפי חשבון זה \u0003הוה ליה ריש ירחא\u0004 \u0005[\u0006נמצא שהרי \u0005הוא לו ראש חודש]\u0006 \u0003אייר מעלי שבתא\u0004 \u0005[בערב שבת],\u0006 \u0003וריש ירחא\u0004 \u0005[וראש חודש]\u0006 \u0003סיון\u0004 ב\u0003שבתא\u0004 \u0005[שבת]\u0006 היה, ואם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003בין ל\u0004שיטת \u0003ר' יוסי\u0004 הסבור שראש חודש סיון חל ביום הראשון, ו\u0003בין לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 שלדעתם חל ביום השני! ומשיבים: יש לומר שלא נהגו כשיטת אחרים אלא לדעת \u0003ר' יוסי\u0004 באותה שנה \u0003שבעה\u0004 חודשים \u0003חסרין עבוד\u0004 \u0005[עשו],\u0006"],["\u0003לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 \u0003שמונה\u0004 חדשים \u0003חסרים עבוד\u0004 \u0005[עשו].\u0006","ומקשים ממה \u0003דתניא\u0004 \u0005[ששנויה\u0006 בברייתא\u0005]\u0006 הנקראת \u0003\"סדר עולם\": ניסן שבו יצאו ישראל ממצרים בארבעה עשר\u0004 בו \u0003שחטו פסחיהן, בחמשה עשר\u0004 בו \u0003יצאו, ואותו היום ערב שבת היה. ומדריש ירחא\u0004 \u0005[ומזה שראש חודש]\u0006 \u0003ניסן ערב שבת\u0004 היה — אם כן \u0003ריש ירחא\u0004 \u0005[ראש חודש]\u0006 \u0003אייר חד בשבא\u0004 \u0005[\u0006ב\u0005אחד בשבת]\u0006 היה, \u0003ו\u0004ראש חודש \u0003סיון בתרי בשבא\u0004 \u0005[בשני בשבת],\u0006 ואם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003ל\u0004שיטת \u0003ר' יוסי\u0004 הסבור שראש חודש סיון חל ביום הראשון! ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך ר' יוסי: הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 שיטת \u0005מי היא]\u0006 — שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא.\u0004","ועוד \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו, \u0003ר' יוסי אומר: בשני\u0004 בחודש \u0003עלה משה\u0004 להר סיני \u0003וירד, בשלישי עלה וירד, ברביעי ירד ושוב לא עלה\u0004 להר סיני עד שנצטווה עם כל ישראל. ומקשים: איך אפשר לומר שברביעי ירד ולא עלה? שהרי \u0003מאחר שלא עלה, מהיכן ירד? אלא\u0004 יש לתקן: \u0003ברביעי עלה וירד, בחמישי בנה מזבח והקריב עליו קרבן, בששי לא היה לו פנאי.\u0004 ושואלים: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 ה\u0003תורה\u0004 שקיבל בשישי בחודש? והרי זה כשיטת חכמים!","ודוחים: \u0003לא,\u0004 לא היה לו פנאי \u0003משום טורח שבת,\u0004 שהכינו עצמם לקבלת השבת ביום השישי בשבוע. ומוסיפים: \u0003דרש ההוא גלילאה עליה\u0004 \u0005[גלילי אחד עליו]\u0006 על \u0003רב חסדא: בריך רחמנא דיהב אוריאן תליתאי לעם תליתאי\u0004 \u0005[ברוך ה' שנתן תורה משולשת,\u0006 תורה נביאים כתובים, \u0005לעם משולש],\u0006 כהנים לויים וישראל, \u0003על ידי תליתאי\u0004 \u0005[שלישי],\u0006 משה שהוא שלישי לארן ומרים, \u0003ביום תליתאי בירחא תליתאי\u0004 \u0005[שלישי\u0006 לפרישה \u0005בחודש השלישי,\u0006 סיון\u0005].\u0006 \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 בנויה דרשה זו — \u0003כרבנן\u0004 \u0005[כ\u0006שיטת \u0005חכמים],\u0006 שניתנה התורה ביום השלישי ולא ביום הרביעי לפרישה.","כיון שדובר במתן תורה מביאים דרשות אחרות באותו ענין. על מה שנאמר \u0003\"\u0004ויוצא משה את העם לקראת האלהים מן המחנה \u0003ויתיצבו בתחתית ההר\"\u0004 (שמות יט, יז), \u0003אמר ר' אבדימי בר חמא בר חסא:\u0004 עמדו ישראל ממש תחת ההר, ו\u0003מלמד\u0004 פסוק זה \u0003שכפה\u0004 (הפך) \u0003הקדוש ברוך הוא עליהם\u0004 על ישראל \u0003את ההר כ\u0004דרך שכופים \u0003גיגית, ואמר להם: אם אתם מקבלים\u0004 את \u0003התורה\u0004 — \u0003מוטב, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003שם תהא קבורתכם. אמר רב אחא בר יעקב: מכאן מודעא\u0004 (הודעה) \u0003רבה לאורייתא\u0004 \u0005[\u0006כלפי \u0005התורה],\u0006 שיכולים ישראל להתנצל ולומר שבתחילה קבלו את התורה מאונס, ואינם חייבים לקיימה. \u0003אמר רבא: אף על פי כן הדור\u0004 \u0005[חזרו]\u0006 ו\u0003קבלוה\u0004 מרצונם \u0003בימי אחשורוש, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"קימו וקבלו\u0004 היהודים עליהם ועל זרעם ועל כל הנלווים עליהם\u0003\"\u0004 (אסתר ט, כז), ודרש: \u0003קימו\u0004 היהודים על עצמם \u0003מה שקיבלו כבר\u0004 עליהם כמאונס בשעת מתן תורה.","\u0003אמר חזקיה: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"משמים השמעת דין ארץ יראה ושקטה\"\u0004 (תהילים עו, ט) ותמוה הדבר: \u0003אם יראה\u0004 — \u0003למה שקטה? ואם שקטה\u0004 — \u0003למה יראה? אלא\u0004 הכוונה היא ש\u0003בתחילה יראה ולבסוף שקטה.\u0004 ויש להבין בדרך זו: \"משמים השמעת דין\" — הוא מתן תורה (הדין). \u0003ולמה\u0004 יראה הארץ? \u0003כ\u0004דברי \u0003ריש לקיש.\u0004 ש\u0003אמר ריש לקיש: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"ויהי ערב ויהי בקר יום הששי\"\u0004 (בראשית א, לא) \u0003ה\"א יתירה\u0004 (ב\"הששי\") שאינה נזכרת בשאר הימים \u0003למה לי?\u0004 — \u0003מלמד שהתנה הקדוש ברוך הוא עם מעשה בראשית ואמר להם: אם ישראל מקבלים\u0004 את \u0003התורה\u0004 ביום הששי בסיון — \u0003אתם מתקיימין, ואם\u0004 הם \u0003לאו\u0004 \u0005[לא]\u0006 מקבלים אותה — \u0003אני מחזיר אתכם לתוהו ובוהו.\u0004 ולכן יראה ארץ עד שניתנה התורה לישראל שמא תחזור לתוהו, ושקטה כשקיבלו ישראל עליהם.","\u0003דרש ר' סימאי: בשעה שהקדימו ישראל\u0004 במתן תורה \u0003\"נעשה \" ל\"נשמע\" באו ששים ריבוא של מלאכי השרת, לכל אחד ואחד מישראל קשרו לו שני כתרים, אחד כנגד \"נעשה \" ואחד כנגד \"נשמע\". וכיון שחטאו ישראל\u0004 בעגל \u0003ירדו מאה ועשרים ריבוא מלאכי חבלה ופירקום\u0004 מישראל, כמו \u0003שנאמר\u0004 לאחר מעשה העגל: \u0003\"ויתנצלו בני ישראל את עדים מהר חורב\"\u0004 (שמות לג, ו). \u0003אמר ר' חמא בר' חנינא: בחורב טענו\u0004 את עדיים \u0003ובחורב פרקו.\u0004 ומקור לדבר: \u0003בחורב טענו\u0004 — \u0003כדאמרן\u0004 \u0005[כפי שאמרנו],\u0006 \u0003בחורב פרקו\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויתנצלו בני ישראל\u0004 את עדיים (שהיה להם) מהר חורב \u0003\". אמר ר' יוחנן: ו\u0004כל הכתרים הללו \u0003כולן זכה משה ונטלן.\u0004 ומנין לנו דבר זה? — \u0003דסמיך ליה\u0004 \u0005[ש\u0006ב\u0005סמוך לו]\u0006 נאמר: \u0003\"ומשה יקח את האהל\"\u0004 (שמות לג, ז), ונדרש \"אהל\" מלשון הילה והארה. \u0003אמר ריש לקיש: עתיד הקדוש ברוך הוא להחזירן לנו,\u0004 וכפי \u0003שנאמר: \"ופדויי ה' ישבון ובאו ציון ברנה ושמחת עולם על ראשם\"\u0004 (ישעיהו לה, י), והכוונה היא: \u0003שמחה שמעולם\u0004 (שהיתה כבר פעם) תהיה שוב \u0003על ראשם.\u0004","\u0003אמר ר' אלעזר: בשעה שהקדימו ישראל \"נעשה \" ל\"נשמע\" יצתה\u0004 (יצאה) \u0003בת קול ואמרה להן: מי גילה לבני רז\u0004 \u0005[סוד]\u0006 \u0003זה שמלאכי השרת משתמשין בו? דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ברכו ה' מלאכיו גברי כח עשי דברו לשמע בקול דברו\"\u0004 (תהילים קג, כ) שהמלאכים \u0003ברישא\u0004 \u0005[בראש,\u0006 מתחילה\u0005]\u0006 הם \u0003\"עושי\u0004 דברו \u0003\"והדר\u0004 \u0005[ואחר\u0006 כך\u0005]\u0006 \u0003\"לשמוע\". אמר ר' חמא בר' חנינא: מאי דכתיב\u0004 \u0005[מה\u0006 משמעות כתוב זה \u0005שנאמר]\u0006 \u0003\"כתפוח בעצי היער\u0004 כן דודי בין הבנים בצילו חמדתי וישבתי ופריו מתוק לחיכי\u0003\"\u0004 (שיר השירים ב, ג), \u0003למה נמשלו ישראל לתפוח\u0004 — \u0003לומר לך מה תפוח זה פריו קודם\u0004 בצמיחתו \u0003לעליו, אף ישראל הקדימו \"נעשה \" ל\"נשמע\".\u0004","מסופר: \u0003ההוא מינא דחזייה\u0004 \u0005[מין אחד\u0006 \u0003שראה]\u0004 את \u0003רבא דקא\u0004 \u0005[שהוא]\u0006 \u0003מעיין בשמעתא\u0004 \u0005[בהלכה],\u0006 \u0003ויתבה אצבעתא דידיה תותי כרעא וקא מייץ בהו\u0004 \u0005[וישבו,\u0006 היו \u0005אצבעותיו\u0006 מונחות \u0005תחת רגלו והיה לוחץ אותן],\u0006 \u0003וקא מבען אצבעתיה דמא\u0004 \u0005[והיו מזילות אצבעותיו דם],\u0006 ורבא לא הבחין בכך מתוך התעמקותו. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עמא פזיזא, דקדמיתו פומייכו לאודנייכו, אכתי בפחזותייכו קיימיתו\u0004 \u0005[עם פזיז\u0006 אתם, \u0005שהקדמתם פיכם לאזניכם, עדיין בפחזותכם אתם עומדים],\u0006 שאתם עושים דברים בלא לחשוב עליהם. \u0003ברישא איבעיא לכו למשמע\u0004 \u0005[בתחילה הייתם צריכים לשמוע],\u0006 \u0003אי מציתו\u0004 \u0005[אם יכולים אתם]\u0006 — \u0003קבליתו\u0004 \u0005[קבלו\u0006 אותם\u0005],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003לא קבליתו\u0004 \u0005[תקבלו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנן\u0004"],["\u0003דסגינן בשלימותא כתיב בן\u0004 \u0005[אנחנו ההולכים בשלימות,\u0006 בתמימות, \u0005נאמר בנו]:\u0006 \u0003\"תמת ישרים תנחם\"\u0004 (משלי יא, ג), ואילו \u0003הנך אינשי דסגן בעלילותא כתיב בהו\u0004 \u0005[אותם אנשים,\u0006 אתם, \u0005ההולכים בעלילה נאמר בהם]\u0006 סופו של אותו פסוק: \u0003\"וסלף בוגדים ישדם\".\u0004","\u0003אמר ר' שמואל בר נחמני\u0004 שכך \u0003אמר ר' יונתן: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"לבבתני אחותי כלה לבבתני באחת מעיניך\u0004 באחד ענק מצורוניך\u0003\"\u0004 (שיר השירים ד, ט) — \u0003בתחילה\u0004 שרק קבלו ישראל על עצמם היה זה \u0003באחת מעיניך,\u0004 ואולם \u0003לכשתעשי\u0004 ותקיימי את המצוות בפועל יהא זה \u0003בשתי עיניך. אמר עולא\u0004 בענין חטא העגל: \u0003עלובה\u0004 (חצופה) \u0003כלה מזנה בתוך חופתה. אמר ר' מרי ברה\u0004 \u0005בנה]\u0006 של \u0003בת שמואל: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 המרמז על כך? — \u0003\"עד שהמלך במסבו נרדי\u0004 נתן ריחו\u0003\"\u0004 (שיר השירים א, יב), והפיג את ריחו הטוב ועתה נשאר רק הריח הרע. \u0003אמר רב: ו\u0004אף על פי כן נראה מן הכתוב \u0003כי עדיין חביבותא\u0004 \u0005[חביבות]\u0006 של הקדוש ברוך הוא \u0003היא גבן\u0004 \u0005[עלינו],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בלשון נקייה \"נתן ריחו\" \u0003ולא כתב\u0004 \u0005[אמר]\u0006 לשון \u0003\"הסריח\".\u0004 ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אותם שהם \u0003עלובין ואינן עולבין, שומעין חרפתן ואינן משיבין, עושין מאהבה ושמחין ביסורין\u0004 — \u0003עליהן הכתוב אומר: \"ואוהביו כצאת השמש בגבורתו\"\u0004 (שופטים ה, לא).","ועוד בענין מתן תורה \u0003אמר ר' יוחנן: מאי דכתיב\u0004 \u0005[מה\u0006 משמעות כתוב זה \u0005שנאמר]\u0006 \u0003\"ה' יתן אומר המבשרות צבא רב\"\u0004 (תהילים סח, יב) — משמעו: \u0003כל דיבור ודיבור\u0004 (\"אומר\") \u0003שיצא מפי הגבורה\u0004 (הקדוש ברוך הוא) \u0003נחלק לשבעים לשונות\u0004 (\"צבא רב\"). וכן \u0003תני דבי\u0004 \u0005[שנו בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל\u0004 על מה שנאמר: \"הלוא כה דברי כאש נאום ה' \u0003וכפטיש יפצץ סלע\"\u0004 (ירמיהו כג, כט), \u0003מה פטיש זה נחלק\u0004 (נשבר) \u0003לכמה ניצוצות\u0004 (חלקים) כאשר הוא נתקל בסלע קשה ביותר — \u0003אף כל דיבור ודיבור שיצא מפי הקדוש ברוך הוא נחלק לשבעים לשונות.\u0004 ועוד בשבח התורה, \u0003אמר רב חננאל בר פפא: מאי דכתיב\u0004 \u0005[מה\u0006 משמעות כתוב זה \u0005שנאמר]:\u0006 \u0003\"שמעו כי נגידים אדבר\u0004 ומפתח שפתי מישרים\u0003\"\u0004 (משלי ח, ו) — \u0003למה נמשלו דברי תורה כנגיד\u0004 (מלך) — \u0003לומר לך: מה נגיד זה יש בו\u0004 כוח \u0003להמית ולהחיות, אף דברי תורה יש בם להמית ולהחיות.\u0004","ו\u0003היינו\u0004 \u0005[וזהו]\u0006 מה ש\u0003אמר רבא: למיימינים בה\u0004 בתורה ועוסקים מתוך רצון טוב וקדושה הריהי \u0003סמא דחיי\u0004 \u0005[סם חיים]\u0006 ו\u0003למשמאילים בה\u0004 הריהי \u0003סמא דמותא\u0004 \u0005[סם מוות].\u0006 \u0003דבר אחר:\u0004 מדוע נקראו דברי התורה \u0003\"נגידים\"\u0004 — מפני ש\u0003כל דיבור ודיבור שיצא מפי הקדוש ברוך הוא קושרים לו\u0004 לדיבור \u0003שני כתרים. אמר ר' יהושע בן לוי: מאי דכתיב\u0004 \u0005[מה\u0006 משמעות כתוב זה \u0005שנאמר]:\u0006 \u0003\"צרור המור דודי לי בין שדי ילין\"\u0004 (שיר השירים א, יג) — \u0003אמרה כנסת ישראל לפני הקדוש ברוך הוא: רבונו של עולם אף על פי שמיצר ומימר\u0004 (עושה צרות ומרורות) \u0003לי דודי\u0004 (הוא ה') — אף על פי כן \u0003בין שדי ילין.\u0004 ועוד פירש: \u0003\"אשכל הכפר דודי לי בכרמי עין גדי\"\u0004 (שיר השירים א, יד) — \u0003מי שהכל שלו\u0004 (\"אשכול\") \u0003מכפר לי\u0004 (\"הכופר\") \u0003על עון גדי\u0004 (כלומר, העגל) \u0003שכרמתי\u0004 (אספתי) \u0003לי.\u0004 ומסבירים: \u0003מאי משמע דהאי\u0004 \u0005[מה המשמעות ש\u0006מלה \u0005זו]\u0006 \u0003\"כרמי\" לישנא דמכניש\u0004 \u0005[לשון\u0006 \u0003של כינוס] הוא\u0004 — \u0003אמר מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כסא\u0004 של \u0003כובס שכורמים\u0004 (אוספים) \u0003עליו את הכלים\u0004 (בגדים), ומכן שלשון \"כרם\" משמעו — אסיפה.","\u0003ואמר ר' יהושע בן לוי: מאי דכתיב\u0004 \u0005[מה\u0006 משמעות כתוב זה \u0005שנאמר]\u0006 \u0003\"לחייו כערוגת הבשם\u0004 מגדלות מרקחים שפתותיו שושנים נוטפות מור עובר\u0003\"\u0004 (שיר השירים ה, יג)? — מדרשו: מ\u0003כל דבור ודבור שיצא מפי הקדוש ברוך הוא\u0004 (\"לחייו\") \u0003נתמלא כל העולם כולו בשמים. וכיון שמדיבור ראשון\u0004 כבר \u0003נתמלא,\u0004 אם כן \u0003דיבור שני להיכן הלך?\u0004 אלא \u0003הוציא הקדוש ברוך הוא\u0004 את \u0003הרוח מאוצרותיו והיה מעביר ראשון ראשון,\u0004 ומותיר מקום להשפעה של הדיבור שלאחריו. \u0003ש\u0004כן \u0003נאמר: \"שפתותיו שושנים נוטפות מור עבר\"\u0004 שהמור עובר על כל דיבור ודיבור. ו\u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"שושנים\" אלא \"ששונים\"\u0004 (חוזרים שנית), כלומר, דיבור שני יש לו בושם משלו.","\u0003ואמר ר' יהושע בן לוי:\u0004 מ\u0003כל דיבור ודיבור שיצא מפי הקדוש ברוך הוא יצתה נשמתן של ישראל,\u0004 וכפי \u0003שנאמר: \"נפשי יצאה בדברו\"\u0004 (שיר השירים ה, ו) \u0003ומאחר שמדיבור ראשון\u0004 כבר \u0003יצתה נשמתן,\u0004 אם כן \u0003דיבור שני היאך קיבלו?\u0004 — אלא \u0003הוריד\u0004 הקדוש ברוך הוא \u0003טל שעתיד להחיות בו מתים והחיה אותם,\u0004 וכפי \u0003שנאמר: \"גשם נדבות תניף אלהים נחלתך ונלאה אתה כוננתה\"\u0004 (תהלים סח, י), שב\"גשם נדבות\" (טל תחיה) העמיד ה' את נחלתו — עמו. \u0003ואמר ר' יהושע בן לוי:\u0004 מ\u0003כל דיבור ודיבור שיצא מפי הקדוש ברוך הוא חזרו ישראל לאחוריהן\u0004 מאימה \u0003שנים עשר מיל והיו מלאכי השרת מדדין אותן\u0004 (עוזרים להם ללכת) לקראת ההר וכפי \u0003שנאמר: \"מלאכי צבאות ידדון ידדון\"\u0004 (תהלים סח, יג), \u0003אל תיקרי\u0004 \u0005[תקרא]\u0006 \u0003\"ידדון\" אלא \"ידדון\".\u0004","\u0003ואמר ר' יהושע בן לוי : בשעה שעלה משה למרום\u0004 לקבל תורה \u0003אמרו מלאכי השרת לפני הקדוש ברוך הוא: רבונו של עולם, מה לילוד אשה בינינו? אמר להן\u0004 הקדוש ברוך הוא: \u0003לקבל תורה בא. אמרו לפניו\u0004 המלאכים: אותה תורה \u0003חמודה גנוזה שגנוזה לך תשע מאות ושבעים וארבעה דורות קודם שנברא העולם,\u0004 שנאמר \"דבר ציוה לאלף דור\" (תהלים קה, ח) וכיון שניתנה התורה בדור העשרים וששה לאדם הראשון, הרי שאר הדורות היו לפני בריאת העולם, והם תשע מאות שבעים וארבעה, ו\u0003אתה מבקש ליתנה לבשר ודם? \"מה אנוש כי תזכרנו ובן אדם כי תפקדנו\"\u0004 (תהילים ח, ה)? אלא \u0003\"ה' אדנינו מה אדיר שמך בכל הארץ אשר תנה הודך על השמים\"\u0004 (תהלים ח, ב), שראוי שתהא התורה בשמים!","\u0003אמר לו הקדוש ברוך הוא למשה: החזיר להן תשובה\u0004 מדוע צריכה התורה להינתן לבני אדם. \u0003אמר לפניו\u0004 משה: \u0003רבונו של עולם, מתיירא אני\u0004 מהם \u0003שמא ישרפוני בהבל שבפיהם. אמר לו\u0004 הקדוש ברוך הוא: \u0003אחוז בכסא כבודי\u0004 לחיזוק והגנה \u0003וחזור\u0004 (והחזר) \u0003להן תשובה.\u0004 ומנין שכך \u0003היה? ש\u0004כן \u0003נאמר \"מאחז פני כסא פרשז עליו עננו\"\u0004 (איוב כו, ט), \u0003ואמר ר' נחום:\u0004 כתוב זה \u0003מלמד שפירש\u0004 (פרס) \u0003שדי מזיו\u0004 (\"פרשז\" — בנוטריקון) \u0003שכינתו ועננו עליו. אמר לפניו: רבונו של עולם, תורה שאתה נותן לי מה כתיב בה?\u0004 אמר לו הקדוש ברוך הוא: \u0003\"אנכי ה' אלהיך אשר הוצאתיך מארץ מצרים\u0004 מבית עבדים\u0003\"\u0004 (שמות כ, ב). \u0003אמר להן\u0004 משה למלאכים: \u0003וכי למצרים ירדתם?\u0004 וכי \u0003לפרעה השתעבדתם? תורה למה תהא לכם? שוב\u0004 שאל משה: \u0003מה\u0004 עוד \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה?\u0004 אמר לו הקדוש ברוך הוא: \u0003\"לא יהיה לך אלהים אחרים\u0004 על פני\u0003\"\u0004 (שמות כ, ג). אמר משה למלאכים: וכי \u0003בין הגוים אתם שרויין שעובדין\u0004"],["\u0003עבודה זרה\u0004 וצריכים אתם לפיכך אזהרה מיוחדת? \u0003שוב\u0004 שאל משה: \u0003מה\u0004 עוד \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה?\u0004 אמר לו הקדוש ברוך הוא: \u0003\"זכור את יום השבת לקדשו\"\u0004 (שמות כ, ח). שאל משה את המלאכים: \u0003כלום אתם עושים מלאכה שאתם צריכין שבות\u0004 (שביתה) ממנה? \u0003שוב\u0004 שאל משה: \u0003מה\u0004 עוד \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה?\u0004 אמר לו הקדוש ברוך הוא: \u0003\"לא תשא\u0004 את שם ה' אלהיך לשוא\u0003\"\u0004 (שמות כ, ז), והכוונה שלא ישבעו לשקר. שאל משה את המלאכים: וכי \u0003משא ומתן יש ביניכם\u0004 שיש מקום לבוא לשבועת שקר? \u0003שוב\u0004 שאל משה: \u0003מה\u0004 עוד \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה?\u0004 אמר לו הקדוש ברוך הוא: \u0003\"כבד את אביך ואת אמך\"\u0004 (שמות כ, יב). ושאל משה את המלאכים: וכי \u0003אב ואם יש לכם\u0004 שצריכים אתם ציווי מיוחד על כיבודם? \u0003שוב\u0004 שאל משה: \u0003מה\u0004 עוד \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה?\u0004 אמר לו הקדוש ברוך הוא: \u0003\"לא תרצח\", \"לא תנאף\", \"לא תגנב\".\u0004 ושאל משה את המלאכים: וכי \u0003קנאה יש ביניכם?\u0004 וכי \u0003יצר הרע יש ביניכם\u0004 שצריכים \u0003אתם לציוויים הללו? מיד הודו לו להקדוש ברוך הוא\u0004 שיפה עושה שנותן את התורה לבני אדם, וכפי \u0003שנאמר: \"ה' אדננו מה אדיר שמך\u0004 בכל \u0003הארץ\"\u0004 (תהילים ח, י), \u0003ואילו \"תנה הודך על השמים\" לא כתיב\u0004 \u0005[נאמר],\u0006 והרי שקיבלו המלאכים את דעתו של הקדוש ברוך הוא שראוי שיהא הוד ה' על הארץ.","\u0003מיד כל אחד ואחד\u0004 מן המלאכים \u0003נעשה לו אוהב\u0004 למשה \u0003ומסר לו דבר,\u0004 וכפי \u0003שנאמר: \"עלית למרום שבית שבי לקחת מתנות באדם\u0004 ואף סוררים לשכון יה אלהים\u0003\"\u0004 (תהילים סח, יט), ומשמעות הכתוב — \u0003בשכר שקראוך \"אדם\",\u0004 ומפני שאתה אדם ולך ראויה התורה, \u0003לקחת מתנות\u0004 מן המלאכים. ו\u0003אף מלאך המות מסר לו דבר,\u0004 שבשעת המגפה אמר משה לאהרן סגולה לעצור את המגיפה, \u0003שנאמר: \"ויתן את הקטרת ויכפר על העם\"\u0004 (במדבר יז, יב). \u0003ואומר\u0004 הכתוב עוד: \u0003\"ויעמוד בין המתים ובין החיים\u0004 ותעצר המגיפה\u0003\"\u0004 (במדבר יז, יג), \u0003אי לאו\u0004 \u0005[אם לא]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 מלאך המות סגולה זו \u0003מי הוה ידע\u0004 \u0005[האם היה יודע]?\u0006","\u0003ואמר ר' יהושע בן לוי: בשעה שירד משה מלפני הקדוש ברוך הוא\u0004 עם התורה, \u0003בא שטן ואמר לפניו,\u0004 לפני הקדוש ברוך הוא: \u0003רבונו של עולם, תורה היכן היא? אמר לו: נתתיה לארץ. הלך אצל ארץ, אמר לה: תורה היכן היא? אמרה לו:\u0004 איני יודעת, כי רק \u0003\"אלהים הבין דרכה\u0004 והוא ידע את מקומה\u0003\"\u0004 (איוב כח, כג). \u0003הלך אצל ים\u0004 ושאל אותו היכן התורה, \u0003ואמר לו\u0004 הים: \u0003\"אין עמדי\". הלך אצל תהום\u0004 ושאלו אולי הוא יודע היכן התורה, ו\u0003אמר לו\u0004 התהום: \u0003\"אין בי \".\u0004 ומנין שכך השיבוהו הים והתהום — \u0003שנאמר: \"תהום אמר לא בי היא וים אמר אין עמדי\"\u0004 (איוב כח, יד). וכן \u0003\"אבדון ומות אמרו באזנינו שמענו שמעה\"\u0004 (איוב כח, כב). \u0003חזר ואמר\u0004 השטן \u0003לפני הקדוש ברוך הוא: רבונו של עולם, חיפשתי\u0004 את התורה \u0003בכל הארץ ולא מצאתיה. אמר לו: לך אצל בן עמרם\u0004 (משה).","\u0003הלך אצל משה\u0004 ו\u0003אמר לו: תורה שנתן לך הקדוש ברוך הוא היכן היא?\u0004 השתמט משה ו\u0003אמר: וכי מה אני שנתן לי הקדוש ברוך הוא תורה? אמר לו הקדוש ברוך הוא למשה: משה, בדאי אתה?! אמר לפניו: רבונו של עולם, חמודה גנוזה יש לך שאתה משתעשע בה בכל יום,\u0004 כאמור: \"ואהיה שעשועים יום יום משחקת לפניו בכל עת\" (משלי ח, ל), וכי \u0003אני אחזיק טובה לעצמי\u0004 ואומר שלי ניתנה? \u0003אמר לו הקדוש ברוך הוא למשה: הואיל ומיעטת\u0004 את \u0003עצמך תקרא\u0004 התורה \u0003על שמך\u0004 \"תורת משה\", \u0003שנאמר: \"זכרו תורת משה עבדי\u0004 אשר ציויתי אותו בחורב על כל ישראל חוקים ומשפטים\u0003\"\u0004 (מלאכי ג, כב).","\u0003ואמר ר' יהושע בן לוי: בשעה שעלה משה למרום מצאו להקדוש ברוך הוא שהיה קושר כתרים לאותיות,\u0004 שבראש אותיות מסויימות יש תגים מיוחדים, והיה הקדוש ברוך הוא מתייג אותן, ולא אמר משה דבר. \u0003אמר לו\u0004 הקדוש ברוך הוא: \u0003משה,\u0004 וכי \u0003אין שלום בעירך?\u0004 כלומר, וכי במקומכם אין אומרים \"שלום\"? \u0003אמר לפניו: כלום יש עבד שנותן שלום לרבו?\u0004 אין זה מנהג דרך ארץ. \u0003אמר לו\u0004 הקדוש ברוך הוא: לפחות \u0003היה לך לעזרני\u0004 ולומר שתצליח מלאכתי, \u0003מיד אמר לו: \"ועתה יגדל נא כח ה' כאשר דברת\u0004 לאמר\u0003\"\u0004 (במדבר יד, יז).","ו\u0003אמר ר' יהושע בן לוי: מאי דכתיב\u0004 \u0005[מה\u0006 משמעות כתוב זה \u0005שנאמר]:\u0006 \u0003\"וירא העם כי בשש משה\u0004 לרדת מן ההר\u0003\"\u0004 (שמות לב, א), כדי להבין כתוב זה \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"בשש\" אלא \"באו שש \".\u0004 ש\u0003בשעה שעלה משה למרום אמר להן לישראל: לסוף ארבעים יום בתחלת שש\u0004 שעות, כלומר בחצות היום \u0003אני בא. לסוף ארבעים יום בא שטן ועירבב\u0004 בסערה \u0003את העולם,\u0004 ולא יכלו להבחין מה היא השעה. \u0003אמר להן\u0004 השטן לישראל: \u0003משה רבכם היכן הוא? אמרו לו: עלה למרום. אמר להן? באו שש\u0004 שעות ועדיין לא בא ובודאי שוב לא יבוא. \u0003ולא השגיחו עליו.\u0004 אמר להם השטן: \u0003מת\u0004 משה. \u0003ולא השגיחו עליו.\u0004 לסוף \u0003הראה להם דמות מטתו\u0004 שנראתה בענן דמותו המתה. \u0003והיינו דקאמרי ליה\u0004 \u0005[וזהו שאמרו לו]\u0006 ישראל \u0003לאהרן: \"כי זה משה האיש\u0004 אשר העלנו מארץ מצרים לא ידענו מה היה לו\u0003\"\u0004 (שמות לב, א).","\u0003אמר ליה ההוא מרבנן\u0004 \u0005[לו אחדש החכמים]\u0006 \u0003לרב כהנא: מי שמיע לך מאי\u0004 \u0005[האם שמעת\u0006 על \u0005מה]\u0006 נקרא ההר \u0003\"הר סיני\"? אמר ליה\u0004 \u0005[לו]\u0006 רב כהנא: משום שהוא \u0003הר שנעשו בו נסים לישראל.\u0004 אמר לו אותו חכם: אם כן \u0003\"הר ניסאי\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 להיקרא! \u0003אלא\u0004 אמר רב כהנא: משום שהוא \u0003הר שנעשה סימן טוב לישראל.\u0004 ושוב דחהו אותו חכם: אם כן \u0003\"הר סימנאי\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 להיקרא! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב כהנא: \u0003מאי טעמא לא שכיחת קמיה\u0004 \u0005[מדוע אינך מצוי לפני]\u0006 \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע דמעייני באגדתא\u0004 \u0005[שמעיינים\u0006 כרגיל גם \u0005באגדה]?\u0006 ש\u0003רב חסדא ורבה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב הונא דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 הסיבה\u0005]\u0006 שנקרא שמו \u0003\"הר סיני\"\u0004 — משום שהוא \u0003הר שירדה שנאה לאמות העולם עליו\u0004 על שלא קיבלו את התורה. \u0003והיינו\u0004 \u0005[וזהו]\u0006 מעין מה ש\u0003אמר ר' יוסי בר' חנינא,\u0004 שאמר, \u0003חמשה שמות יש לו\u0004 למדבר שהיו בו ישראל ארבעים שנה בצאתם ממצרים, ולכל שם מקור וסיבה: \u0003\"מדבר צין\"\u0004 — משום \u0003שנצטוו ישראל עליו,\u0004 ודורש משחק מילים \"נצטוו\" — \"צין\". \u0003\"מדבר קדש\"\u0004 — משום \u0003שנתקדשו ישראל עליו. \"מדבר קדמות\"\u0004 — משום \u0003שנתנה\u0004 התורה שהיא \u0003קדומה,\u0004 לעולם, \u0003עליו. \"מדבר פארן\"\u0004 — משום"],["\u0003שפרו ורבו עליה ישראל. \"מדבר סיני\"\u0004 — משום \u0003שירדה שנאה לאמות העולם עליו,\u0004 בהר שעליו קבלו את התורה. \u0003ומה שמו\u0004 האמיתי של ההר? \u0003\"חורב\" שמו. ופליגא\u0004 \u0005[וחלוקה\u0006 דעה זו\u0005]\u0006 על דברי \u0003ר' אבהו,\u0004 שאמר: \u0003\"הר סיני\" שמו, ולמה נקרא \"הר חורב\"\u0004 — \u0003שירדה חורבה לאמות העולם עליו.\u0004","שנינו במשנה: \u0003מנין שקושרין לשון של זהורית\u0004 לשעיר המשתלח — שנאמר: \"אם יהיו חטאיכם כשנים כשלג ילבינו\" (ישעיה א, יח) ותוהים: מדוע נאמר \u0003\"כשנים\"? \"כשני\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר! \u0003אמר ר' יצחק, אמר להם הקדוש ברוך הוא לישראל:\u0004 אף \u0003אם יהיו חטאיכם\u0004 מרובים \u0003כשנים הללו שסדורות ובאות מששת ימי בראשית ועד עכשיו\u0004 — \u0003כשלג ילבינו. דרש רבא: מאי דכתיב\u0004 \u0005[מה\u0006 משמעות כתוב זה \u0005שנאמר]\u0006 באותו פסוק: \u0003\"לכו נא ונוכחה יאמר ה'\"\u0004מדוע נאמר \u0003\"לכו נא\"? \"בואו נא\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר! וכן מדוע נאמר \u0003\"יאמר ה'\"?\u0004 הלא דברי נבואה הם ממה שכבר אמר, ו\u0003\"אמר ה'\"מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר! אלא פירוש הדברים הוא, \u0003שלעתיד יאמר להם הקדוש ברוך הוא לישראל: לכו נא אצל אבותיכם ויוכיחו אתכם.\u0004","\u0003ויאמרו\u0004 ישראל \u0003לפניו: רבונו של עולם, אצל מי נלך?\u0004 האם נלך \u0003אצל אברהם שאמרת לו \"ידע תדע\u0004 כי גר יהיה זרעך בארץ לא להם ועבדום וענו אותם ארבע מאות שנה\u0003\"\u0004 (בראשית טו, יג) \u0003ולא בקש רחמים עלינו?!\u0004 או שמא נלך \u0003אצל יצחק שבירך את עשו\u0004 ואמר לו: \u0003\"והיה כאשר תריד\u0004 ופרקת עולו מעל צוארך\u0003\"\u0004 (בראשית כז, מ), \u0003ולא בקש רחמים עלינו?!\u0004 או נלך \u0003אצל יעקב שאמרת לו: \"אנכי ארד עמך מצרימה\"\u0004 (בראשית מו, ד), \u0003ולא בקש רחמים עלינו?!\u0004 ואם כן \u0003אצל מי נלך?\u0004 שהרי האבות אינם חסים עלינו. אלא \u0003עכשיו יאמר ה'\u0004 בעצמו מה העונש הראוי לנו. \u0003אמר להן הקדוש ברוך הוא: הואיל ותליתם עצמכם בי\u0004 — \u0003\"אם יהיו חטאיכם כשנים, כשלג ילבינו\".\u0004","כיון שדובר בישראל הבאים ומעריכים את אבותיהם מביאים דרשה דומה: \u0003אמר ר' שמואל בר נחמני\u0004 שכך \u0003אמר ר' יונתן: מאי דכתיב\u0004 \u0005[מה\u0006 משמעות כתוב זה \u0005שנאמר]:\u0006 \u0003\"כי אתה אבינו כי אברהם לא ידענו וישראל לא יכירנו אתה ה' אבינו גואלנו מעולם שמך\"\u0004 (ישעיהו סג, טז) — ש\u0003לעתיד לבא יאמר לו הקדוש ברוך הוא לאברהם: בניך חטאו לי. אמר לפניו: רבונו של עולם,\u0004 אם כן \u0003ימחו על קדושת שמך. אמר\u0004 ה': \u0003אימר ליה\u0004 \u0005[אומר לו]\u0006 \u0003ליעקב\u0004 שכיון \u0003דהוה ליה\u0004 \u0005[שהיה לו]\u0006 \u0003צער גידול בנים, אפשר דבעי רחמי עלייהו\u0004 \u0005[ש\u0006אולי \u0005יבקש רחמים עליהם].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ליעקב: \u0003בניך חטאו. אמר לפניו\u0004 יעקב: \u0003רבונו של עולם,\u0004 אם כן \u0003ימחו על קדושת שמך. אמר\u0004 הקדוש ברוך הוא \u0003לא בסבי טעמא\u0004 \u0005[בזקנים טעם]\u0006 \u0003ולא בדרדקי\u0004 \u0005[בעצה]\u0006 \u0003עצה,\u0004 שגם אברהם וגם יעקב אינם יודעים לענות כראוי. \u0003אמר לו ליצחק: בניך חטאו לי. אמר לפניו\u0004 יצחק: \u0003רבונו של עולם,\u0004 וכי \u0003בני\u0004 הם \u0003ולא בניך?!\u0004 הלא \u0003בשעה שהקדימו לפניך\u0004 במעמד הר סיני \u0003\"נעשה\" ל\"נשמע\" קראת להם \"בני בכורי\u0004 ישראל\u0003\"\u0004 (שמות ד, כב) ו\u0003עכשיו\u0004 משחטאו \u0003בני\u0004 הם \u0003ולא בניך?!\u0004","\u0003ועוד, כמה\u0004 בעצם \u0003חטאו? כמה שנותיו של אדם\u0004 — \u0003שבעים שנה. דל עשרין דלא ענשת עלייהו\u0004 \u0005[הסר עשרים\u0006 ראשונות \u0005שאינך מעניש עליהן],\u0006 שבדיני שמים אין עונשים אלא מגיל עשרים ומעלה. \u0003פשו להו חמשין\u0004 \u0005[נשארו להן\u0006 איפוא \u0005חמישים\u0006 שנה\u0005].\u0006 \u0003דל עשרין וחמשה דלילותא, פשו להו עשרין וחמשה\u0004 \u0005[הסר עשרים וחמש\u0006 שנה \u0005של לילות נשארו להם עשרים וחמש].\u0006 \u0003דל תרתי סרי ופלגא דצלויי ומיכל\u0004 \u0005[הסר שתים עשרה וחצי\u0006 שנים \u0005של תפילה ואכילה]\u0006 \u0003ו\u0004של \u0003בית הכסא\u0004 — \u0003פשו להו תרתי סרי ופלגא\u0004 \u0005[נשארו שתים עשרה וחצי\u0006 שנים\u0005],\u0006 \u0003אם אתה סובל את כולם\u0004 ויכול לסלוח עוון של שנים אלה — \u0003מוטב, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003פלגא\u0004 \u0005[חצי]\u0006 \u0003עלי ופלגא\u0004 \u0005[וחצי]\u0006 \u0003עליך. ואם תמצא לומר\u0004 כי \u0003כולם,\u0004 כל שתים עשרה השנים ומחצה שנותרו, \u0003עלי\u0004 יהיו — \u0003הא קריבית נפשי קמך\u0004 \u0005[הרי הקרבתי את עצמי לפניך]\u0006 וראוי שתמחול בזכותי להם. \u0003פתחו\u0004 ישראל \u0003ואמרו: אתה אבינו,\u0004 כלומר, רק יצחק הוא המסנגר על ישראל כרחם אב על בנים. \u0003אמר להם יצחק: עד שאתם מקלסין\u0004 (משבחים) \u0003לי, קלסו להקדוש ברוך הוא, ומחוי להו\u0004 \u0005[ומראה להם]\u0006 \u0003יצחק\u0004 את \u0003הקדוש ברוך הוא בעינייהו\u0004 \u0005[בעיניהם]\u0006 \u0003מיד נשאו עיניהם למרום ואומרים: \"אתה ה' אבינו גאלנו מעולם שמך\".\u0004","וכיון שהוזכרה ירידת יעקב למצרים מביאים את מה ש\u0003אמר ר' חייא בר אבא\u0004 שכך \u0003אמר ר' יוחנן: ראוי היה יעקב אבינו לירד למצרים בשלשלאות של ברזל,\u0004 כגולה ובעל כורחו, שהרי גזירה היתה זו מאת ה' וכבר נאמרה לאברהם, \u0003אלא שזכותו גרמה לו\u0004 שיבא בדרך שלא יהיו בה יסורים, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"בחבלי אדם אמשכם בעבתות אהבה ואהיה להם כמרימי על על לחיהם ואט אליו אוכיל\"\u0004 (הושע יא, ד).","לאחר ההפסקה הגדולה בדברים שאינם מענין המסכת, בדרך הקשרי מחשבה, שבים אל עיקר הנושא: פרטי דיני ההוצאה בשבת. \u0003המוציא עצים\u0004 בשבת, שיעורם — \u0003כדי לבשל\u0004 בהם \u0003ביצה קלה. תבלין,\u0004 שיעורם — \u0003כדי לתבל\u0004 בו \u0003ביצה קלה. ומצטרפין\u0004 כל מיני התבלינים \u0003זה עם זה\u0004 לשיעור המחייב. \u0003קליפי אגוזין, קליפי רמונים\u0004 שמשתמשים בהם לצביעה וכן צמחי הצבע \u0003איסטיס ופואה,\u0004 שיעורם — \u0003כדי לצבוע בהן בגד קטן\u0004 הנתון ב\u0003פי\u0004 (ראש) \u0003סבכה,\u0004 ראש הסבכה שאשה שמה על שערותיה. \u0003מי רגלים נתר ובורית קמוליא ואשלג\u0004 שכולם חומרי כביסה, שיעורם להוצאת שבת — \u0003כדי לכבס בגד קטן\u0004 שב\u0003פי\u0004 ה\u0003סבכה, ור' יהודה אומר:\u0004 חומרים אלה שיעורם \u0003כדי להעביר\u0004 (להסיר) בהם \u0003את הכתם.\u0004","על השיעור שניתן לעצים שואלים: הלא \u0003תנינא חדא זימנא\u0004 \u0005[שנינו\u0006 כבר פעם \u0005אחת]\u0006 הלכה זו! ששנינו: \u0003קנה,\u0004 שיעורו לענין הוצאת שבת — שיהיה בו \u0003כדי לעשות\u0004 ממנו \u0003קולמוס, אם היה עב או מרוסס\u0004 (שביר) ואינו ראוי לכתוב בו, שיעורו — \u0003כדי לבשל\u0004 בו \u0003ביצה קלה שבביצים,\u0004 כשהיא \u0003טרופה ונתונה\u0004 כבר \u0003באילפס.\u0004 ויודעים אנו, איפוא, שיעור עצי הסקה! ומשיבים: בכל זאת יש צורך במשנה זו, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בקנה שבור \u0003הוא\u0004 שאמרו בו שיעור זה משום \u0003דלא חזי למידי\u0004 \u0005[שאינו ראוי לדבר]\u0006 חוץ מהסקה, \u0003אבל עצים דחזו לככא דאקלידא\u0004 \u0005[שראויים\u0006 הם \u0005ל\u0006שמש כ\u0005שן של מפתח]\u0006 יהא שיעורם \u0003אפילו כל שהוא,\u0004 לכן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שסתם עצים נועדו להסקה, ולפי שיעור זה חייבים על הוצאתם.","שנינו במשנה שתבלינים מסוגים שונים מצטרפים זה עם זה לשיעור \u0003תבלין כדי לתבל\u0004 בו \u0003ביצה קלה,\u0004 שהוא השיעור הקובע בתבלין לענין הוצאת שבת. \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 לדברים אלה ממה ששנינו במקום אחר: \u0003תבלין,\u0004 אף אם היו \u0003שנים ושלשה שמות,\u0004 שיש בהם איסורים שונים, כגון שהאחד אסור משום ערלה והאחר משום טבל, והיו כולם \u0003ממין אחד\u0004 (תוספות), \u0003או\u0004 שהיו \u0003משלשה מינין\u0004 — \u0003אסורין, ומצטרפין זה עם זה\u0004 לשיעור אחד. \u0003ואמר חזקיה:\u0004"],["\u0003במיני מתיקה שנו, הואיל וראויין\u0004 להצטרף יחד \u0003למתק קדירה.\u0004 ומכאן נדייק: \u0003טעמא דחזו\u0004 \u0005[הטעם\u0006 דווקא \u0005כשהיו ראויים]\u0006 \u0003למתק את הקדירה\u0004 בכולם כאחד, \u0003הא לאו הכי\u0004 \u0005[הרי\u0006 אם \u0005לא כך]\u0006 — \u0003לא\u0004 מצטרפים, והרי שתבלינים כרגיל אינם מצטרפים לשיעור אחד! ומשיבים: \u0003הכא נמי חזו למתק\u0004 \u0005[כאן גם כן,\u0006 במשנתנו מדובר \u0005ב\u0006אופן ש\u0005ראויים למתק].\u0006","שנינו במשנה ש\u0003קליפי אגוזין וקליפי רמונים סטיס ופואה,\u0004 שיעורם להוצאת שבת — \u0003כדי לצבוע\u0004 בהם \u0003בגד קטן. ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 לדברים אלה ממה ששנינו במקום אחר: \u0003המוציא\u0004 בשבת \u0003סמנים שרויין,\u0004 שיעורם לענין הוצאה — \u0003כדי לצבוע בהן דוגמא לאירא\u0004 (כמות קטנה של צמר שהאורג נותן בקנה האריגה שלו לדוגמא בלבד), והרי שאין צורך שיהא בהם כדי צביעת בגד קטן! ומשיבים: \u0003הא איתמר עלה\u0004 \u0005[הרי נאמר עליה],\u0006 ש\u0003אמר רב נחמן\u0004 שכך \u0003אמר רבה בר אבוה:\u0004 בסימנים שרויים די בשיעור קטן יותר, \u0003לפי שאין אדם טורח לשרות\u0004 מלכתחילה \u0003סממנים לצבוע בהן דוגמא לאירא,\u0004 אלא לצורך בגד חשוב יותר. ואולם סממנים שהם כבר שרויים ומוכנים שיעורם קטן בהרבה, ודי שיהא בו כדי צביעת דוגמה לאירא.","במשנה הוזכרו חמרי כביסה שונים, וביניהם \u0003מי רגלים,\u0004 ובגמרא מבארים את מהותם של החומרים המוזכרים. \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בברייתא: כשהוזכרו \u0003מי רגלים\u0004 במשנה, לא הזכירו אלא את \u0003מי רגלים עד\u0004 שהם בני \u0003ארבעים יום,\u0004 שלאחר מכן פגה חמיצותם ואינם ראויים עוד לשימוש. על \u0003נתר\u0004 שהוזכר במשנה \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בברייתא: המדובר ב\u0003נתר אלכסנדרית\u0004 (הבא מאלכסנדריה) \u0003ולא נתר\u0004 של המקום הנקרא \u0003אנפנטרין,\u0004 שטיבו שונה. ועל \u0003בורית\u0004 שהוזכרה במשנה \u0003אמר רב יהודה: זה חול.\u0004 ומקשים, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הבורית והחול,\u0004 וכיון שנזכרים הם בנפרד, הרי שהם שונים זה מזה! \u0003אלא\u0004 יש לומר: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003בורית\u0004 — \u0003כבריתא\u0004 \u0005[גופרית].\u0006","\u0003מיתיבי\u0004 \u0005[מ\u0006\u0005קשים]\u0006 על כך ממה ששנינו בענין הצמחים שנאסרו לשימוש בשביעית, ש\u0003הוסיפו עליהן\u0004 את \u0003החלביצין, ו\u0004את \u0003הלעינון, והבורית, והאהל. ואי סלקא דעתך\u0004 \u0005[ואם יעלה על דעתך]\u0006 לומר שבורית היא \u0003כבריתא\u0004 \u0005[גפרית],\u0006 \u0003כבריתא מי איכא\u0004 \u0005[גפרית האם ישנה]\u0006 \u0003ב\u0004דיני \u0003שביעית?! והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003זה הכלל, כל שיש לו עיקר\u0004 (שורש) וצומח — \u0003יש לו שביעית, ושאין לו עיקר\u0004 — \u0003אין לו שביעית! אלא מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003בורית\u0004 — היא \u0003אהלא\u0004 \u0005[אהל].\u0006 ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003והבורית ואהלא,\u0004 וכיון שנזכרים הם בנפרד, הרי שהם שונים זה מזה! \u0003אלא\u0004 יש לומר כי \u0003תרי גווני אהלא\u0004 \u0005[שני סוגים\u0006 של \u0005אהל]\u0006 יש, ואחד מהם הוא הקרוי \"בורית\".","ועל \u0003קימוליא\u0004 המוזכרת במשנה \u0003אמר רב יהודה:\u0004 זהו החומר הנקרא \u0003שלוף דוץ.\u0004 על \u0003אשלג\u0004 שהוזכר במשנה \u0003אמר שמואל: שאילתינהו\u0004 \u0005[שאלתי אותם]\u0006 את \u0003כל נחותי ימא\u0004 \u0005[יורדי הים]\u0006 מהו אשלג, \u0003ואמרו לי\u0004 ש\u0003\"שונאנה\" שמיה\u0004 \u0005[שמו],\u0006 \u0003ומשתכח בנוקבא דמרגניתא ומפקי ליה ברמצא דפרזלא\u0004 \u0005[ונמצא בצידפי המרגליות ומוציאים אותו בשיפוד של ברזל].\u0006","שיעור \u0003פלפלת\u0004 לאיסור הוצאת שבת — \u0003כל שהוא, ו\u0004כן \u0003עטרן כל שהוא. מיני בשמים ומיני מתכות\u0004 — \u0003כל שהן. מאבני המזבח ומעפר המזבח,\u0004 וכן רקבובית הספרים הבאה כתוצאה מחרק ה\u0003מקק\u0004 הפוגע ב\u0003ספרים\u0004 של קודש, \u0003ומקק מטפחותיהם\u0004 של הספרים שיעורם ב\u0003כל שהוא.\u0004 וטעמו של דבר, \u0003ש\u0004מפני הקדושה שבהם \u0003מצניעין אותן לגונזן\u0004 ולכן חשיבותם אף בשיעור קטן ביותר. \u0003ר' יהודה אומר: אף המוציא\u0004 בשבת \u0003משמשי עבודה זרה,\u0004 שיעורם \u0003כל שהוא, שנאמר: \"ולא ידבק בידך מאומה מן החרם\"\u0004 (דברים יג, יח) וכיון שאף חלק קטן ביותר מהם אסור בשימוש, וחובה לבערו, חשיבותו בכל שהוא.","שואלים: \u0003פלפלת\u0004 בשיעור \u0003כל שהוא למאי חזיא\u0004 \u0005[למה\u0006 היא \u0005ראוייה]?\u0006 ומשיבים: \u0003לריח הפה,\u0004 שהיא מפיגה אותו. \u0003עיטרן\u0004 בשיעור \u0003כל שהוא למאי חזיא\u0004 \u0005[למה\u0006 הוא \u0005ראוי]?\u0006 — לרפואה \u0003לצילחתא\u0004 \u0005[כאב ראש].\u0006 שנינו במשנה ששיעור \u0003מיני בשמים\u0004 להוצאת שבת — \u0003כל שהן.\u0004 תנו \u0003רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: אף \u0003המוציא\u0004 בשבת דבר שיש בו \u0003ריח רע\u0004 שמשתמשים בו לצורך רפואה וכיוצא בה, שיעורו — \u0003כל שהוא. שמן טוב\u0004 של בושם שיעורו — \u0003כל שהוא. ארגמן\u0004 — \u0003כל שהוא. ובתולת הוורד\u0004 (ניצן של פרח הורד), שיעורה להוצאת שבת — \u0003אחת.\u0004","שנינו במשנה ששיעור \u0003מיני מתכות\u0004 להוצאת שבת — \u0003כל שהן.\u0004 ושואלים: כל שהן \u0003למאי חזו\u0004 \u0005[למה\u0006 הם \u0005ראויים],\u0006 ומדוע תיחשב זו להוצאה? \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר: שכן\u0004 כמות ברזל קטנה ביותר \u0003ראוי לעשות ממנה דרבן\u0004 (מסמר) \u0003קטן.\u0004 וכיון שנידון כאן שיעור מתכות לענין הוצאת שבת, מזכירים דיון כיוצא בזה לדיני הקדשות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003האומר \"הרי עלי ברזל \"\u0004שאתן כתרומה למקדש, ולא פירש שיעור מסויים, \u0003אחרים אומרים: לא יפחות\u0004 מלתת להקדש כשיעור \u0003מאמה על אמה.\u0004 ושואלים: \u0003למאי חזיא\u0004 \u0005[למה ראויה]\u0006 פיסת ברזל זו? \u0003אמר רב יוסף: לכלייא עורב,\u0004 שהיה גג ההיכל מצופה טבלאות ברזל ובהן מסמרים, כדי שלא ישבו העורבים על הגג. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 אותם דברים בסגנון שונה במקצת, \u0003אחרים אומרים: לא יפחות מ\u0004שיעור הראוי ל\u0003כלייא עורב. וכמה\u0004 הוא שיעור זה? \u0003אמר רב יוסף: אמה על אמה.\u0004 המנדב \u0003נחשת, לא יפחות מ\u0004שיעור השווה \u0003מעה כסף. תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' אליעזר אומר: לא יפחות מצינורא\u0004 (כעין מחט ארוכה) \u0003קטנה של נחשת.\u0004 ושואלים: \u0003למאי חזיא\u0004 \u0005[למה\u0006 היא \u0005ראויה]\u0006 במקדש? \u0003אמר אביי: שמחטטין בה\u0004 ומנקים \u0003את הפתילות\u0004 שבמנורה \u0003ומקנחין\u0004 בה את \u0003הנרות.\u0004","שנינו במשנה את שיעור הוצאתם של רקבובית הספרים שנעשתה כתוצאה מ\u0003מקק ספרים ומקק מטפחת. אמר ר' יהודה:\u0004 מיני החרקים הללו, \u0003מקק דסיפרי\u0004 \u0005[של ספרים],\u0006 וכן החרק הקרוי \u0003תכך דשיראי\u0004 \u0005[של משי],\u0006 \u0003ואילא דעינבי\u0004 \u0005[של ענבים],\u0006 \u0003ופה דתאני\u0004 \u0005[של תאנים],\u0006 \u0003והה דרימוני\u0004 \u0005[של רימונים]\u0006 — \u0003כולהו סכנתא\u0004 \u0005[כולם סכנה]\u0006 לבולע אותם. וכעין זה מסופר: \u0003ההוא תלמידא דהוה יתיב קמיה\u0004 \u0005[תלמיד אחד שהיה יושב לפני]\u0006 \u0003ר' יוחנן, הוה קאכיל תאיני\u0004 \u0005[\u0006ו\u0005היה אוכל תאנים].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו תלמיד לר' יוחנן: \u0003רבי,\u0004 וכי \u0003קוצין\u0004 (קוצים) \u0003יש בתאנים? אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003קטליה\u0004 \u0005[הרגו]\u0006 \u0003פה לדין\u0004 \u0005[את זה],\u0006 שהתולעת שהיתה בתאנה מנקבת עתה את גרונו של אותו תלמיד.","\u0003המוציא\u0004 בשבת \u0003קופת הרוכלין, אף על פי שיש בה מינין הרבה,\u0004 שהרוכל נושא בסלו מינים רבים של בשמים ותכשיטים — \u0003אינו חייב אלא חטאת אחת,\u0004 כיון שהכל הוא הוצאה אחת בלבד. המוציא \u0003זרעוני גינה,\u0004 שיעורן להוצאת שבת — \u0003פחות מכגרוגרת. ר' יהודה בן בתירה אומר:\u0004 די ב\u0003חמישה\u0004 זרעונים."],["\u0003זרע קישואין,\u0004 כיון שהצמחים גדולים וניכרים די ב\u0003שנים. זרע דילועין\u0004 — \u0003שנים. זרע פול המצרי\u0004 — \u0003שנים. חגב חי טהור\u0004 — \u0003כל שהוא.\u0004 וחגב \u0003מת\u0004 טהור, כיון שהוא ראוי לאכילה שיעורו ככל המאכלים — \u0003כגרוגרת. צפורת כרמים\u0004 שהיא מין חגב, \u0003בין חיה בין מתה,\u0004 שיעורה להוצאת שבת — \u0003כל שהוא,\u0004 כיון \u0003שמצניעין אותה לרפואה\u0004 ולסגולה, ומכאן שהיא חשובה. \u0003ר' יהודה אומר: אף המוציא חגב חי טמא\u0004 שיעורו ב\u0003כל שהוא,\u0004 לפי \u0003שמצניעין אותו לקטן לשחוק בו.\u0004 שנינו במשנה שיעורם של זרעוני גינה להוצאת שבת. \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 על כך ממה ששנינו: \u0003זבל וחול הדק,\u0004 שיעורו להוצאת שבת — שיהיה בהם \u0003כדי לזבל\u0004 בהם \u0003קלח של כרוב,\u0004 אלו \u0003דברי ר' עקיבא. וחכמים אומרים: כדי לזבל כרישא\u0004 אחת. הרי שאף צמח אחד הוא שיעור חשוב! \u0003אמר רב פפא: הא\u0004 \u0005[זה]\u0006 ששנינו ששיעורו קטן הרי זה באופן \u0003דזריע\u0004 \u0005[ש\u0006הוא \u0005זרוע]\u0006 וכבר גדל, שבכגון זה מביאים זבל אף לאחד. ואילו \u0003הא\u0004 \u0005[זה]\u0006 ששנינו ששיעורו גדול יותר הרי זה באופן \u0003דלא זריע\u0004 \u0005[שאינו זרוע],\u0006 שבכגון זה אין האדם נוהג להוציא כל כך מעט, \u0003לפי שאין אדם טורח להוציא נימא\u0004 (גרגר) \u0003אחת לזריעה.\u0004 על האמור במשנה בשיעור \u0003זרע קישואין\u0004 ודלועין \u0003תנו רבנן\u0004 \u0005[שנו\u0006 חכמים]: \u0003המוציא גרעינין, אם ל\u0004צורך \u0003נטיעה\u0004 הוציא, שיעורם להוצאת שבת — \u0003שתים, אם לאכילה\u0004 לבעלי חיים הוציא, שיעורם — \u0003כמלא פי חזיר, וכמה מלא פי חזיר\u0004 — \u0003אחת.\u0004 ו\u0003אם להסיק\u0004 בהם הוציא — \u0003כדי\u0004 הראוי \u0003לבשל ביצה קלה. אם לחשבון\u0004 הוציא, לשמש כעזר לזכור דברים — \u0003שתים. אחרים אומרים: חמש,\u0004 שעד חמש זוכרים בעל פה, ואין צורך בסימנים. ועוד \u0003תנו רבנן\u0004 \u0005[שנו\u0006 חכמים]: \u0003המוציא שני נימין\u0004 (שערות) \u0003מזנב הסוס\u0004 או \u0003מזנב הפרה\u0004 — \u0003חייב, שמצניעין אותן לנישבין\u0004 \u0005[למלכודות].\u0006 \u0003מקשה\u0004 (שערה נוקשה) \u0003של חזיר,\u0004 שיעורה להוצאת שבת — \u0003אחת,\u0004 שמשתמשים בה בתפירת נעליים ויש בה חשיבות. \u0003צורי דקל\u0004 (נצרים קלופים של דקל) — \u0003שתים. תורי דקל,\u0004 חוטים שמסירים מקליפת החריות והם דקים יותר — \u0003אחת.\u0004","","","שנינו במשנה ש\u0003ציפורת כרמים, בין חיה\u0004 ו\u0003בין מתה,\u0004 שיעורה — כל שהוא, \u0003כיון\u0004 שמצניעים אותה לרפואה וסגולה. ושואלים: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003ציפורת כרמים\u0004 זו? \u0003אמר רב:\u0004 החגב הנקרא \u0003פליא ביארי. אמר אביי: ומשתכח בדיקלא דחד נבארא ועבדי לה לחוכמא\u0004 \u0005[ונמצאת\u0006 ציפורת הכרמים \u0005בדקל ש\u0006יש בו \u0005סיב אחד\u0006 בלבד \u0005ומשתמשים בה\u0006 כסגולה \u0005לחכמה].\u0006 \u0003אכיל ליה לפלגא דימיניה, ופלגא דשמאליה רמי לה בגובתא דנחשא וחתים לה בשיתין גושפנקי, ותלי לה באיברא דשמאלא\u0004 \u0005[אוכל\u0006 הוא \u0005את חצייה הימני, ו\u0006את \u0005חציה השמאלי משליך,\u0006 מניח, \u0005בשפופרת של נחושת וחותם אותה בשישים חותמות ותולה אותה בזרועו השמאלית].\u0006 \u0003וסימניך\u0004 \u0005[וסימן\u0006 יש \u0005לך]\u0006 בדבר איזה חלק יש לאכול ואיזה לתלות, מן הכתוב \u0003\"לב חכם לימינו ולב כסיל לשמאלו\"\u0004 (קהלת י, ב), \u0003וחכים\u0004 \u0005[ומחכים]\u0006 \u0003כמה דבעי\u0004 \u0005[ש\u0006הוא \u0005רוצה],\u0006 \u0003וגמר\u0004 \u0005[ולומד]\u0006 \u0003כמה דבעי\u0004 \u0005[ש\u0006הוא \u0005רוצה],\u0006 \u0003ואכיל ליה לאידך פלגא\u0004 \u0005[ו\u0006אחר כך \u0005אוכל את החצי האחר],\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא\u0004 יעשה כן — \u0003מיעקר\u0004 \u0005[ייעקר,\u0006 ישתכח\u0005]\u0006 \u0003תלמודו.\u0004","שנינו במשנה ש\u0003ר' יהודה אומר\u0004 ש\u0003אף המוציא\u0004 חגב חי טמא חייב בכל שהוא שכן מצניעים אותו לתינוק לשחק בו. ומסבירים: \u0003ו\u0004ה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]\u0006 ש\u0003לא\u0004 נותנים לתינוק חגב טמא קטן לשחק בו. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — משום החשש \u0003דילמא אכיל ליה\u0004 \u0005[שמא יאכל אותו]\u0006 הילד. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שחוששים לדבר, אם כן חגב \u0003טהור נמי\u0004 \u0005[גם כן]\u0006 יאסרו לתת לתינוק שמא יאכלנו. \u0003דהא\u0004 \u0005[שהרי]\u0006 מסופר ש\u0003רב כהנא הוה קאים קמיה\u0004 \u0005[היה עומד לפני]\u0006 \u0003רב והוה קמעבר שושיבא אפומיה\u0004 \u0005[והיה מעביר חגב\u0006 חי \u0005טהור ליד פיו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב לרב כהנא: \u0003שקליה\u0004 \u0005[הנח אותו]\u0006 כדי ש\u0003לא לימרו מיכל קאכיל ליה וקעבר\u0004 \u0005[יאמרו\u0006 ש\u0005אוכל הוא אותו ועובר]\u0006 \u0003משום \"בל תשקצו את נפשותיכם\"\u0004 (ויקרא יא, מג), נמצא שאף אכילת חגב טהור בעודו חי יש בה משום עבירה! \u0003אלא\u0004 יש לומר שאף לדעת סתם משנה אין חשש שהילד הקטן יאכל את החגב שהוא משחק בו, אלא טעם האיסור בחגב טמא הריהו \u0003דילמא מיית ואכיל ליה\u0004 \u0005[ושמא ימות\u0006 החגב \u0005ויאכל אותו],\u0006 ולכן אין מניחים לילד לשחק בחגב טמא. \u0003ור' יהודה\u0004 סבר שאין לחשוש לכך, כי \u0003אי מיית\u0004 \u0005אם ימות\u0006 החגב — ה\u0003קטן מיספד ספיד ליה\u0004 \u0005[\u0006\u0005יספוד לו]\u0006 ויתאבל עליו, ובודאי לא יאכלנו. \u0003המצניע לזרע ו\u0004כן \u0003לדוגמא ו\u0004כן \u0003לרפואה והוציאו בשבת\u0004 — \u0003חייב\u0004 עליו \u0003בכל שהוא,\u0004 שכיון שהצניע כמות זו, אף שהיא פחותה מן השיעורים שנקבעו בהלכה, ודאי חשובה היא לו, לאדם זה, וחייב אם כן גם על הוצאתה. \u0003וכל אדם\u0004 אחר — \u0003אין חייב עליו\u0004 בהוצאתו בשבת \u0003אלא כשיעורו.\u0004 ואם \u0003חזר והכניסו\u0004 המצניע ושוב אינו מתכוון להשתמש בו לאותו צורך מיוחד — \u0003אינו חייב אלא כשיעורו,\u0004 אם יוציאנו (רש\"ש).","","","ושואלים: \u0003למה ליה למיתני\u0004 \u0005[לו לשנות]\u0006 \u0003\"המצניע\"\u0004 ואחר כך לומר \"המוציא\"? \u0003ליתני\u0004 \u0005[שישנה]\u0006 רק: \u0003המוציא לזרע ולדוגמא ולרפואה\u0004 — \u0003חייב בכל שהוא!\u0004 שהרי על ההוצאה הוא מתחייב, ואם מוציא לצורך כמות קטנה מן השיעור הראה בכך שהוא מחשיבה — ויתחייב עליה! \u0003אמר אביי: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003— כגון שהצניעו\u0004 לצורך מסויים \u0003ושכח למה הצניעו, והשתא קא מפיק ליה סתמא\u0004 \u0005[ועכשיו מוציא אותו סתם]\u0006."],["\u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי בכך \u0003בטולי\u0004 \u0005[ביטול]\u0006 מוחלט \u0003בטלה מחשבתו\u0004 הראשונה, כיון שאינו יודע לשם מה הצניע, על כן \u0003קא משמע לן\u0004 \u0005[הוא\u0006 התנא במשנתנו \u0005משמיע לנו]\u0006 כי \u0003כל העושה\u0004 פעולה בדבר מסויים שעסק בו כבר בעבר \u0003— על דעת ראשונה הוא עושה.\u0004","\u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: מחייב היה ר' מאיר אף במוציא\u0004 בשבת \u0003חטה אחת ל\u0004צורך \u0003זריעה.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שהרי כאשר שנינו במשנה שיעור הוצאה האסורה בזרעים לשון \u0003\"כל שהוא\" תנן\u0004 \u0005[שנינו],\u0006 וכיון שכלל הוא שכל סתם משנה שלא נזכר שם אומרה, כשיטת ר' מאיר היא, אם כן הרי שדבר זה מפורש כבר! וזה כולל בודאי גם שיעור של פחות מחיטה. ומתרצים שהיה בכל זאת צורך בכך, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שלשון \u0003\"כל שהוא\"\u0004 ששנינו — הכוונה היא \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004ן ההכרח שיהא שיעור \u0003גרוגרת, ו\u0004אולם \u0003לעולם\u0004 אינו חייב \u0003עד דאיכא\u0004 \u0005[שיש]\u0006 במה שהוא מוציא שיעור של לפחות \u0003כזית,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 ש\"כל שהוא\" הריהו אף גרעין אחד. \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על השיטה הראשונה \u0003רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה: אלא מעתה\u0004 שאנו תולים כל דבר רק בכוונתו של המוציא ולא בשיעורים המקובלים, אם \u0003חישב להוציא\u0004 את \u0003כל ביתו\u0004 בבת אחת, \u0003הכי נמי דלא מיחייב\u0004 \u0005[כך גם כן\u0006 תאמר \u0005שאינו מתחייב]\u0006 \u0003עד דמפיק לכוליה\u0004 \u0005[עד שמוציא את כולו]\u0006 בבת אחת?! ומשיבים: אין להשוות, שכן \u0003התם\u0004 \u0005[שם]\u0006 במחשב להוציא את כל ביתו — \u0003בטלה דעתו אצל כל אדם,\u0004 שכן רוב האנשים אינם עושים כך, ולכן אין כוונתו נחשבת.","\u0003ו\u0004עוד שנינו במשנה ש\u0003כל אדם,\u0004 שאינו רגיל להצניע דברים אלו \u0003אין חייבין עליו\u0004 (אינו חייב על הוצאה) בשיעור קטן, אפילו על דבר שהוצנע \u0003אלא כשיעורו\u0004 המקובל. ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו\u0006 זו\u0005]\u0006 היא \u0003לא כ\u0004שיטת \u0003ר' שמעון בן אלעזר. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003כלל אמר ר' שמעון בן אלעזר: כל שאינו כשר להצניע\u0004 (שאינו ראוי בעיני אנשים ולכן אף אין מצניעים כמוהו), \u0003ואין מצניעין\u0004 (רגילים להצניע) \u0003כמוהו, והוכשר\u0004 משום מה \u0003ל\u0004אדם \u0003זה והצניעו, ובא\u0004 אדם \u0003אחר והוציא\u0004 אותו — \u0003נתחייב זה\u0004 המוציא \u0003במחשבתו\u0004 של \u0003זה\u0004 המצניע.","\u0003אמר רבא\u0004 שכך \u0003אמר רב נחמן: הוציא\u0004 בשבת \u0003כ\u0004שיעור \u0003גרוגרת\u0004 זרעים \u0003לאכילה, ונמלך עליה\u0004 בתוך כדי דרכו להשתמש בה \u0003לזריעה, אי נמי\u0004 \u0005[או גם כן]\u0006 התכוון להוציאה \u0003לזריעה, ונמלך עליה לאכילה\u0004 — \u0003חייב,\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שכן \u0003זיל הכא\u0004 — \u0003איכא שיעורא, וזיל הכא\u0004 — \u0003איכא שיעורא\u0004 \u0005[\u0006אם \u0005תלך לכאן,\u0006 על פי המחשבה הראשונה — \u0005יש שיעור\u0006 הראוי לחייבו, \u0005ו\u0006אם \u0005תלך לכאן,\u0006 אחרי המחשבה השנייה — \u0005יש שיעור\u0006 הראוי לחייבו\u0005]!\u0006 ומשיבים: בכל זאת יש בדבר חידוש, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי כדי שיתחייב בהוצאה \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שתהא ה\u0003עקירה והנחה בחדא מחשבה\u0004 \u0005[במחשבה אחת],\u0006 \u0003והא ליכא\u0004 \u0005[והרי אינה],\u0006 ושמא משום שינוי הכוונה, הריהו כאילו עשה שני חצאי מלאכה נפרדים, על כן \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 שהרי זו מלאכה אחת האסורה ולכן חייב.","על סמך הלכה זו \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: הוציא\u0004 זרעים בשיעור של כ\u0003חצי גרוגרת,\u0004 שהוא פחות מכדי שיעור הוצאה, \u0003ל\u0004צורך \u0003זריעה,\u0004 ובינתיים נרטבו הזרעים \u0003ותפחה\u0004 עד כגרוגרת, \u0003ונמלך עליה\u0004 שתהא \u0003לאכילה, מהו\u0004 הדין בכגון זה? וצדדי השאלה: \u0003אם תמצי\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 כי \u0003התם\u0004 \u0005[שם]\u0006 במקרה הראשון \u0003הוא דמיחייב\u0004 \u0005[שמתחייב],\u0006 משום \u0003דזיל הכא\u0004 — \u0003איכא שיעורא וזיל הכא\u0004 — \u0003איכא שיעורא\u0004 \u0005[ש\u0006אם \u0005תלך לכאן,\u0006 אחר מחשבתו הראשונה — \u0005יהא שיעור, ו\u0006אם \u0005תלך לכאן\u0006 אחר מחשבתו השניה — \u0005יהא שיעור],\u0006 ואולם הלא \u0003הכא\u0004 \u0005[כאן],\u0006 \u0003כיון דבעידנא דאפקה\u0004 \u0005[שבזמן שהוציאה]\u0006 \u0003לא הוה ביה\u0004 \u0005[היה בה]\u0006 \u0003שיעור אכילה\u0004 ולכן \u0003לא מיחייב\u0004 \u0005[מתחייב],\u0006 \u0003או דילמא\u0004 \u0005[שמא]:\u0006 \u0003כיון\u0004 ש\u0003אילו אישתיק\u0004 \u0005[היה שותק]\u0006 \u0003ולא חשיב\u0004 \u0005[היה חושב]\u0006 \u0003עליה\u0004 כלל היה \u0003מיחייב\u0004 \u0005[מתחייב]\u0006 על ה\u0003מחשבה\u0004 של הוצאה לצורך \u0003זריעה,\u0004 ואם כן \u0003השתא נמי מיחייב\u0004 \u0005[עכשיו גם כן יתחייב],\u0006 שהרי אפילו לפי המחשבה השנייה היתה זו הוצאה עכשיו.","\u0003ואם תמצי\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 כי \u0003כיון\u0004 ש\u0003אילו אישתיק ולא חשיב\u0004 \u0005[חשב]\u0006 \u0003עליה\u0004 — הריהו \u0003מיחייב\u0004 \u0005[מתחייב]\u0006 על ה\u0003מחשבה\u0004 של ה\u0003זריעה, השתא נמי מיחייב\u0004 \u0005[עכשיו גם כן מתחייב],\u0006 אם \u0003הוציא\u0004 זרעים בשיעור \u0003כגרוגרת ל\u0004צורך \u0003אכילה, וצמקה\u0004 ונפחתה משיעורה \u0003ונמלך עליה לזריעה, מהו\u0004 הדין בכגון זה? \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ודאי כי אישתיק\u0004 \u0005[כאשר\u0006 הוא \u0005שותק]\u0006 ולא היה משנה את מחשבתו — על ה\u0003מחשבה קמייתא\u0004 \u0005[הראשונה]\u0006 \u0003לא מיחייב\u0004 \u0005[היה מתחייב],\u0006 שהרי אין בה כשיעור הראוי לה, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003בתר השתא אזלינן, ומיחייב\u0004 \u0005[אחרי\u0006 מחשבה של \u0005עכשיו אנחנו הולכים, ומתחייב],\u0006 \u0003ואם תמצי\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 כי \u0003בתר השתא אזלינן\u0004 (\u0005אחרי\u0006 מחשבה \u0005של עכשיו אנו הולכים],\u0006 \u0003ומיחייב\u0004 \u0005[ומתחייב],\u0006 ואם כן, נשאל, אם \u0003הוציא כגרוגרת ל\u0004צורך \u0003אכילה וצמקה\u0004 בדרך ונהייתה פחות מכגרוגרת, \u0003וחזרה ותפחה\u0004 לכדי שיעור גרוגרת, \u0003מהו\u0004 הדין בכגון זה, האם \u0003יש דיחוי לענין שבת,\u0004 ונאמר כי כיון שברגע מסויים לא היתה הגרוגרת ראוייה לאכילה שוב אין כאן מקום לחיוב, \u0003או\u0004 שמא \u0003אין דיחוי לענין שבת,\u0004 והרגע הקובע הוא רק זה של העקירה וההנחה? לכל אחת מן השאלות הללו לא נמצא פתרון, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רבא מרב נחמן: זרק כזית תרומה לבית טמא מהו?\u0004 ומתחילה מבררים את השאלה: \u0003למאי\u0004 \u0005[למה,\u0006 לאיזה ענין\u0005]\u0006 נשאלה שאלה זו? \u0003אי\u0004 \u0005[אם]\u0006 \u0003לענין שבת\u0004 — הרי כדי לחייבו בהוצאה \u0003כ\u0004שיעור \u0003גרוגרת בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיה ואין די בכזית, ו\u0003אי\u0004 \u0005[אם]\u0006 \u0003לענין טומאה\u0004 — \u0003כביצה אוכלין בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיה לכל הפחות, ובפחות משיעור זה אין טומאה חלה עליו! ומשיבים: \u0003לעולם לענין שבת\u0004 היתה השאלה, \u0003וכגון דאיכא\u0004 \u0005[שיש]\u0006 כבר באותו בית \u0003פחות מכביצה אוכלין, והאי\u0004 \u0005[וזה]\u0006 שיעור הכזית שנזרק \u0003משלימו ל\u0004כדי שיעור \u0003כביצה.\u0004 והשאלה היא \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין בכגון זה, האם נאמר \u0003כי מ\u0004אחר שכזית זה \u0003מצטרף\u0004 למצוי בבית ומתחייב \u0003לענין טומאה\u0004 — \u0003מיחייב נמי\u0004 \u0005[יתחייב גם כן]\u0006 \u0003לענין שבת, או דילמא\u0004 \u0005[שמא]:\u0006 \u0003כל\u0004 שהוא \u0003לענין שבת\u0004 שיעור של \u0003כגרוגרת בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיה כדי לחייבו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: כבר \u0003תניתוה\u0004 \u0005[שניתם אותה]\u0006 את הברייתא שיש בה תשובה לשאלה זו. ששנינו, \u0003אבא שאול אומר: שתי הלחם ולחם הפנים\u0004 שבמקדש, \u0003שיעורן\u0004 — \u0003כגרוגרת\u0004 להוצאת שבת, \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 יהא שיעורן כך? \u0003לימא\u0004 \u0005[נאמר]:\u0006 \u0003מ\u0004כיון ש\u0003לענין\u0004"],["\u0003יוצא\u0004 (שאסור להוציא מן הלחם המקודש לחוץ לחומת העזרה) שיעורו — כדי להתחייב \u0003בכזית,\u0004 אף \u0003לענין שבת נמי\u0004 \u0005[גם כן]\u0006 יהא שיעורו — \u0003בכזית!\u0004 ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003התם,\u0004 \u0005[שם]\u0006 — \u0003מדאפקיה\u0004 \u0005[מ\u0006רגע \u0005שהוציאו]\u0006 מ\u0003חוץ לחומת העזרה איפסיל ליה\u0004 \u0005[נפסל לו]\u0006 \u0003ב\u0004איסור \u0003יוצא,\u0004 אבל לענין \u0003שבת לא מיחייב\u0004 \u0005[אינו מתחייב]\u0006 \u0003עד דמפיק ליה\u0004 \u0005[שמוציא אותו]\u0006 \u0003לרשות הרבים\u0004 הרחוקה מחומת העזרה, \u0003הכא\u0004 \u0005[כאן]\u0006 — \u0003שבת וטומאה בהדי הדדי קאתיין\u0004 \u0005[ביחד הן באות]\u0006 ומאחר שכזית זה נחשב לענין טומאה — ייחשב אף לענין שבת.","שנינו במשנה שאם \u0003חזר והכניסו\u0004 המצניע לאותו חפץ ושוב אינו מתכוון להשתמש בו לאותו צורך מיוחד שהחשיב אותו, שוב \u0003אינו חייב\u0004 על הוצאתו \u0003אלא\u0004 כאשר הוציאו \u0003כשיעורו\u0004 הרגיל והקבוע. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שהרי כיון שהחזירו, נראה שאינו מחשיבו באופן מיוחד, ונעשה החפץ כשל כל אדם! \u0003אמר אביי: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שזרקו לאוצר\u0004 (מחסן) \u0003ומקומו ניכר\u0004 עדיין לזורק, שיודע היכן מונח. \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003כיון\u0004 ש\u0003מקומו ניכר\u0004 הרי עדיין \u0003במילתיה קמייתא קאי\u0004 \u0005[בענינו,\u0006 בדינו, \u0005הראשון עומד],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 ש\u0003מדזרקיה\u0004 \u0005[מתוך\u0006 זה \u0005שזרקו]\u0006 \u0003לאוצר\u0004 בכך הראה כי \u0003בטולי בטליה\u0004 \u0005[ביטלו]\u0006 מחשיבותו הראשונה.","\u0003המוציא אוכלין\u0004 מביתו בשבת \u0003ונתנן על האסקופה\u0004 (מפתן) הדלת, \u0003בין שחזר\u0004 הוא \u0003והוציאן\u0004 מן האיסקופה לרשות הרבים, \u0003בין שהוציאן אחר\u0004 — \u0003פטור, מפני שלא עשה מלאכתו\u0004 (מלאכת ההוצאה) \u0003בבת אחת,\u0004 ובדומה לזה, \u0003קופה\u0004 (סל) \u0003שהיא מלאה פירות ונתנה על אסקופה החיצונה\u0004 שהיא ברשות הרבים, ועדיין חלק מן הקופה מונחת בפנים, \u0003אף על פי שרוב\u0004 ה\u0003פירות\u0004 מצויים כבר \u0003מבחוץ\u0004 — \u0003פטור, עד שיוציא את כל הקופה,\u0004 ואינו מתחייב על אותם הפירות שבקופה שהוציא לרשות הרבים.","מתחילה שואלים: \u0003האי אסקופה מאי\u0004 \u0005[איסקופה זו\u0006 שעוסקים בה \u0005מה]\u0006 הגדרתה לענין שבת? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שעוסקים ב\u0003אסקופה\u0004 שהיא בגדר \u0003רשות הרבים,\u0004 שאינה גבוהה יותר מתשעה טפחים ורחבה ארבעה על ארבעה וראויה לשימוש הרבים, מדוע יהא \u0003פטור? הא קא מפיק\u0004 \u0005[הרי הוא מוציא]\u0006 את הפירות \u0003מרשות היחיד לרשות הרבים! אלא\u0004 תאמר שמדובר ב\u0003אסקופה\u0004 המוגדרת כ\u0003רשות היחיד,\u0004 שגבוהה עשרה טפחים ורחבה ארבעה על ארבעה, מדוע נאמר במשנה \u0003\"בין שחזר והוציאן ובין שהוציאן אחר\u0004 — \u0003פטור\",\u0004 מדוע יהא פטור? \u0003הא קא מפיק\u0004 \u0005[הרי\u0006 בהוצאה השניה \u0005הוא מוציא]\u0006 \u0003מרשות היחיד לרשות הרבים!\u0004","\u0003אלא\u0004 יש לומר ש\u0003אסקופה זו כרמלית\u0004 היא, \u0003והא קא משמע לן\u0004 \u0005[ו\u0006דבר \u0005זה משמיע לנו]:\u0006 \u0003טעמא\u0004 \u0005[טעם]\u0006 הדבר שאמרו שפטור הוא משום שמדובר דווקא כש\u0003נח\u0004 החפץ \u0003בכרמלית, הא\u0004 \u0005[הרי]\u0006 אם \u0003לא נח בכרמלית\u0004 — \u0003מיחייב\u0004 \u0005[חייב].\u0006 אף שעבר על גבי כרמלית, וללמדנו כי \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 היא \u0003לא\u0004 כשיטת \u0003בן עזאי. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003המוציא מחנות\u0004 שהיא רשות היחיד \u0003לפלטיא\u0004 (רחבה) שהיא רשות הרבים \u0003דרך סטיו\u0004 (שדרת עמודים) שהוא כרמלית — \u0003חייב,\u0004 כיון שעקר ברשות היחיד והניח ברשות הרבים, \u0003ובן עזאי פוטר,\u0004 שלשיטתו כיון שיש בין הרשויות מקום שאין חייבים עליו — פטור.","שנינו במשנה ש\u0003קופה\u0004 (סל) \u0003שהיא מליאה\u0004 פירות — אין חייבים עליה אלא אם כן הוציאוה כולה. ועל כך \u0003אמר חזקיה: לא שנו\u0004 דין זה \u0003אלא בקופה מליאה קישואין ודלועין\u0004 שהם ארוכים, שאף כשמוציא את רוב הקופה עדיין נשאר חלק מכל הפרי בפנים, \u0003אבל\u0004 אם היתה הקופה \u0003מליאה\u0004 זרעוני \u0003חרדל\u0004 — \u0003חייב,\u0004 משום שהוציא כמות של גרגירי חרדל אל רשות הרבים. ומסיקים: \u0003אלמא קסבר\u0004 \u0005[מכאן שהוא סבור]\u0006 ש\u0003אגד\u0004 (חיבור) של כמה פריטים באמצעות \u0003כלי\u0004 אחד — \u0003לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו נחשב\u0005]\u0006 ל\u0003אגד,\u0004 כלומר, אף שהכל נמצא בסל אחד, אין אנו רואים את הנמצא בסל כיחידה אחת. \u0003ור' יוחנן אמר: אפילו מליאה\u0004 אותה קופה בזרעוני \u0003חרדל\u0004 — \u0003פטור. אלמא קסבר\u0004 \u0005[מכאן שהוא סבור]\u0006 ש\u0003אגד כלי\u0004 — \u0003שמיה\u0004 \u0005[שמו,\u0006 נחשב\u0005]\u0006 \u0003אגד.\u0004","\u0003אמר ר' זירא: מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003חזקיה דיקא\u0004 \u0005[מדוייקת],\u0006 \u0003ו\u0004ש\u0003לא כ\u0004שיטת \u0003ר' יוחנן דיקא\u0004 \u0005[מדוייקת].\u0006 ומסבירים: \u0003כ\u0004שיטת \u0003חזקיה לא דיקא\u0004 \u0005[אינה מדוייקת]\u0006 — \u0003דקתני\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 בה: \u0003\"עד שיוציא את כל הקופה\",\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 שיוציא את \u0003כל הקופה, הא\u0004 \u0005[הרי]\u0006 אף אם הוציא את \u0003כל הפירות\u0004 אם חלק מן הקופה נשאר בפנים — \u0003פטור, אלמא קסבר\u0004 \u0005[מכאן\u0006 ש\u0005היא,\u0006 המשנה \u0005סבורה]\u0006 כי \u0003אגד כלי\u0004 — \u0003שמיה\u0004 \u0005[שמו,\u0006 נחשב\u0005]\u0006 \u0003אגד,\u0004 שכן מאחר והכלי הוא המאגד אותן והוא עצמו עדיין חלקו בפנים ונחשב כאילו לא יצא — ממילא גם הפירות נחשבים עדיין כנמצאים בפנים. ו\u0003כ\u0004שיטת \u0003ר' יוחנן\u0004 גם כן \u0003לא דיקא\u0004 \u0005[אינה מדוייקת]\u0006 — \u0003דקתני\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 בה: \u0003\"אף על פי שרוב\u0004 ה\u0003פירות\u0004 מ\u0003בחוץ\",\u0004 ומכאן נדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003רוב פירות\u0004 מבחוץ, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003כל\u0004 ה\u0003פירות\u0004 היו כבר בחוץ, \u0003אף על גב דאגידא\u0004 \u0005[אף על פי שאגודה]\u0006 ה\u0003קופה מגואי\u0004 \u0005[מבפנים]\u0006 — \u0003חייב, אלמא קסבר\u0004 \u0005[מכאן\u0006 ש\u0005היא,\u0006 המשנה \u0005סבורה]\u0006 כי \u0003אגד כלי\u0004 — \u0003לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו נחשב\u0005]\u0006 ל\u0003אגד.\u0004","ושואלים: \u0003ואלא\u0004 אם כן הוא, הרי \u0003קשיא\u0004 \u0005[קשה]\u0006 המשנה עצמה מן הסתירה הפנימית שבה! ומסבירים: \u0003חזקיה מתרץ לטעמיה\u0004 \u0005[מיישב\u0006 את הסתירה \u0005לטעמו,\u0006 לשיטתו\u0005],\u0006 \u0003ור' יוחנן מתרץ לטעמיה\u0004 \u0005[מיישב\u0006 את הסתירה \u0005לטעמו,\u0006 לשיטתו\u0005].\u0006 ומפרטים: לדעת שניהם מדברת המשנה בשני מקרים שונים, \u0003וחזקיה מתרץ לטעמיה\u0004 \u0005[מיישב\u0006 את הסתירה \u0005לטעמו,\u0006 לשיטתו\u0005]:\u0006 מה ששנינו \u0003\"עד שיוציא את כל הקופה\", במה דברים אמורים\u0004 — \u0003בקופה\u0004 שהיא \u0003מליאה קישואין ודלועין, אבל\u0004 שהיא \u0003מליאה\u0004 זרעוני \u0003חרדל\u0004 — \u0003נעשה כמי שהוציא את כל הקופה, וחייב\u0004 על הוצאת החרדל. ו\u0003ר' יוחנן מתרץ לטעמיה\u0004 \u0005[מיישב\u0006 את הסתירה \u0005לטעמו,\u0006 לשיטתו\u0005],\u0006 מה ששנינו \u0003\"אף על פי שרוב\u0004 ה\u0003פירות\u0004 כבר \u0003בחוץ\",\u0004 יש לומר כי הכוונה היא: \u0003ולא\u0004 אם הוציא את \u0003רוב\u0004 ה\u0003פירות בלבד, אלא אפילו\u0004 אם הוציא את \u0003כל פירות\u0004 — גם כן \u0003פטור, עד שיוציא את כל הקופה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003המוציא\u0004 בשבת \u0003קופת הרוכלין\u0004 שיש בה מינים שונים, בעיקר מיני בשמים, \u0003ונתנה על אסקופה החיצונה\u0004 של הבית, \u0003אף על פי שרוב\u0004 ה\u0003מינין\u0004 שבתוכה כבר \u0003בחוץ\u0004 — \u0003פטור, עד שיוציא את כל הקופה. קא סלקא דעתך\u0004 \u0005[עלה על דעתנו]\u0006 לומר שהמדובר בקופה המלאה \u0003בצררי\u0004 \u0005[בצרורות]\u0006 של מיני בשמים, ואם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003ל\u0004שיטת \u0003חזקיה,\u0004 שהרי יצאו כבר רוב הצרורות לרשות הרבים, ועם זאת פטור! ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול \u0003היה\u0004 \u0005לומר]\u0006 \u0003לך חזקיה : הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003באורנסי\u0004 \u0005[בקנים],\u0006 שהבשמים ושאר מינים עשויים כקנים מאורכים, וכל עוד לא הוצאה כל הקופה נשאר חלקם בפנים.","ועוד \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב ביבי בר אביי\u0004 ממה ששנינו: \u0003הגונב כיס\u0004 (ארנק) \u0003בשבת\u0004 — \u0003חייב\u0004 על גניבת הכיס. ואף שהעובר שתי עבירות בבת אחת אין דנים אותו בשני עונשים. וכאן, כיון שחייב סקילה על חילול שבת לא היה לו להתחייב על הגניבה, ואולם מקרה זה שונה, \u0003שכבר נתחייב בגניבה\u0004 שהתחיל לקחת את החפץ מרשות בעליו וזכה בו \u0003קודם שיבא לידי איסור שבת\u0004 כשהוציאו לרשות הרבים. אולם אם לא הגביה את הכיס ממקומו אלא ש\u0003היה מגרר\u0004 (גורר) אותו על הארץ \u0003ויוצא,\u0004 שבמקרה זה אין גרירת הכיס נחשבת לגניבה עד שיצא מרשות הבעלים, \u0003פטור\u0004 מעונש על הגניבה, \u0003שהרי איסור גניבה ואיסור שבת באין כאחד,\u0004 ברגע שיצא הכיס לרשות הרבים. ולעניננו: \u0003ואי סלקא דעתך\u0004 \u0005[ואם יעלה על דעתך]\u0006 לומר ש\u0003אגד כלי\u0004 — \u0003שמיה\u0004 \u0005[שנו,\u0006 נחשב\u0005]\u0006 \u0003אגד,\u0004 הרי כאן \u0003קדים ליה\u0004 \u0005[הקדים]\u0006 \u0003איסור גניבה לאיסור שבת!\u0004 שכן עם יציאת פי הכיס לרשות הרבים נתחייב בגניבה, כי בכך נחשב הדבר כאילו הוציא כבר את הכסף שבתוכו, ואילו לענין שבת לא יתחייב עד שיוציא את הכיס כולו!","ומסבירים: \u0003אי\u0004 \u0005[אם]\u0006 מדובר באופן \u0003דאפקיה\u0004 \u0005[שהוציאו]\u0006 \u0003דרך פיו\u0004 תחילה — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 ומתחייב בגניבה. אלא \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 — \u0003דאפקיה\u0004 \u0005[שהוציאו]\u0006 \u0003דרך שוליו\u0004 (אחוריו) ועד שלא יצא הכיס כולו אינו יכול להשתמש בכסף שבו. ומקשים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003מקום חלמה\u0004 \u0005[תפירה],\u0006 שהרי יכול להוציא את הכסף מן הכיס אף מצידו הסגור על ידי קריעת התפרים שמאחוריו,"],["\u0003דאי בעי מפקע ליה ושקיל\u0004 \u0005[שאם ירצה מפקיע,\u0006 קורע, \u0005אותו ולוקח]!\u0006 ומשיבים: כאן מדובר \u0003בנסכא\u0004 \u0005[בפיסות מתכת]\u0006 ארוכות, וממילא כל עוד שלא יצאו כולן, לא קנה את החפץ ולא נתחייב בגניבה. ושואלים: \u0003וכיון דאיכא\u0004 \u0005[שיש]\u0006 לכיס \u0003שנצין\u0004 (שרוכים) שהוא קשור בהם, הלא די לו במה ש\u0003מפיק ליה\u0004 \u0005[שמוציא אותו]\u0006 \u0003עד\u0004 ש\u0003פומיה\u0004 \u0005[פיו]\u0006 יהיה בחוץ \u0003ושרי ושקיל\u0004 \u0005[ויתיר\u0006 את השרוכים \u0005ויטול]\u0006 את הכסף שבתוכו בעוד ה\u0003שנצין\u0004 עדיין \u0003אגידי מגואי\u0004 \u0005[אגודים,\u0006 מצויים \u0005בפנים,\u0006 ברשות היחיד\u0005]!\u0006 ומשיבים: יש לומר שמדובר כאן באופן \u0003דליכא\u0004 \u0005[שאין]\u0006 לכיס זה \u0003שנצין. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שמדובר באופן \u0003דאית ליה, ומכרכי עילויה\u0004 \u0005[שיש לו\u0006 שנצים, \u0005ו\u0006אולם הם \u0005כרוכים עליו].\u0006 במחלוקת של חזקיה ור' יוחנן נחלקו גם אביי ורבא.","ומפרטים, \u0003וכן אמר רבא: לא שנו\u0004 במשנה שפטור בהוצאה כזו \u0003אלא בקופה מלאה קישואין ודלועין, אבל מלאה חרדל\u0004 — \u0003חייב. אלמא קסבר\u0004 \u0005[מכאן שהוא\u0006 רבא, \u0005סבור]\u0006 ש\u0003אגד\u0004 (חיבור) של כמה פריטים באמצעות \u0003כלי\u0004 אחד \u0003— לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו נחשב\u0005]\u0006 ל\u0003אגד.\u0004 ו\u0003אביי אמר: אפילו\u0004 כשהקופה \u0003מלאה חרדל\u0004 — \u0003פטור, אלמא קסבר\u0004 \u0005[מכאן שהוא,\u0006 אביי \u0005סבור]\u0006 ש\u0003אגד כלי\u0004 — \u0003שמיה\u0004 \u0005[שמו,\u0006 נחשב\u0005]\u0006 \u0003אגד.\u0004 ומעירים: \u0003קם\u0004 \u0005[עמד]\u0006 \u0003אביי בשיטתיה\u0004 \u0005[בשיטתו]\u0006 של \u0003רבא,\u0004 ו\u0003קם\u0004 \u0005[עמד]\u0006 \u0003רבא בשיטתיה\u0004 \u0005[בשיטתו]\u0006 של \u0003אביי, ורמי\u0004 \u0005[ו\u0006יש \u0005להשליך,\u0006 להקשות\u0005]\u0006 מדברי \u0003אביי\u0004 על דברי \u0003אביי\u0004 עצמו, \u0003ורמי\u0004 \u0005[ו\u0006יש \u0005להשליך,\u0006 להקשות\u0005]\u0006 מדברי \u0003רבא\u0004 על דברי \u0003רבא\u0004 עצמו.","\u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 כבר שנחלקו בענין זה: \u0003המוציא פירות לרשות הרבים, אביי אמר:\u0004 אם היו \u0003ביד\u0004 שלו וכך הוציאם, אף על פי ששאר גופו עדיין ברשות היחיד — \u0003חייב,\u0004 לפי שאין אגד הגוף נחשב לאגד, ואולם אם הוציאם \u0003בכלי\u0004 ומקצת הכלי עדיין בתוך רשות היחיד — \u0003פטור. ורבא אמר:\u0004 אם הוציא \u0003ביד\u0004 — \u0003פטור,\u0004 כיון שידו נגררת ונחשבת להלכה כגופו, אבל \u0003בכלי\u0004 — \u0003חייב,\u0004 והרי זה היפך הדברים הקודמים!","ומשיבים: \u0003איפוך\u0004 \u0005[הפוך\u0006 את הגירסה\u0005]\u0006 ואמור שרבא הוא שאמר שאם הוציא \u0003ביד\u0004 — \u0003חייב.\u0004 ומקשים לשיטה זו: \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003פשט בעל הבית את ידו\u0004 מרשות היחיד \u0003לחוץ\u0004 לרשות הרבים, \u0003ונטל העני מתוכה\u0004 חפץ \u0003או שנתן לתוכה\u0004 דבר \u0003והכניס\u0004 אותו בעל הבית — \u0003שניהן פטורין.\u0004 נמצא שבהוצאת ידו בלבד לרשות הרבים אינו חייב! ומשיבים: \u0003התם\u0004 \u0005[שם,\u0006 במשנה\u0005]\u0006 — היה זה \u0003למעלה משלשה\u0004 טפחים מן הארץ ואינו נחשב כצמוד לארץ, ולכך אין זה נחשב כהנחה, ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 — היה זה \u0003למטה משלשה\u0004 טפחים, וכל שהוא בתוך שלושה טפחים לארץ הריהו כצמוד לה, ונחשב כהנחה.","\u0003המוציא\u0004 בשבת הוצאה אסורה, \u0003בין\u0004 שהוציא \u0003ב\u0004יד \u0003ימינו בין בשמאלו,\u0004 בין \u0003בתוך חיקו או על כתיפיו\u0004 — \u0003חייב.\u0004 שכל אלה הן דרכים מקובלות בהוצאת חפץ, \u0003שכן\u0004 בדרך זו היה \u0003משא בני קהת\u0004 שהיו נושאים את כלי הקודש של המשכן במדבר, וכיון שכל מלאכות שבת נלמדות מן המשכן, לומדים אנו מהם לענין מלאכת הוצאה. אבל המוציא \u0003כלאחר ידו\u0004 (כשהחפץ מצד גב ידו) או \u0003ברגלו\u0004 או \u0003בפיו, ו\u0004כן \u0003במרפקו, באזנו\u0004 וכן \u0003בשערו ו\u0004כן \u0003בפונדתו\u0004 (חגורה חלולה) שהיה \u0003פיה למטה,\u0004 או \u0003בין פונדתו לחלוקו, ו\u0004כן \u0003בשפת חלוקו\u0004 או \u0003במנעלו\u0004 או \u0003בסנדלו\u0004 — \u0003פטור\u0004 על כל אלה, כיון \u0003שלא הוציא כדרך המוציאין.\u0004","\u0003אמר ר' אלעזר: המוציא משאוי\u0004 (משא) מרשות היחיד לרשות הרבים אפילו \u0003למעלה מעשרה טפחים\u0004 שהוא מעל תחומה של רשות הרבים — \u0003חייב, שכן\u0004 היה \u0003משא בני קהת.\u0004 ושואלים: \u0003ומשא בני קהת מנלן\u0004 \u0005[מנין לנו]\u0006 שהיה גבוה מעשרה טפחים? ומשיבים: \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 במשא הלויים: \"וקלעי החצר ואת מסך פתח החצר אשר \u0003על המשכן ועל המזבח סביב\u0004 ואת מיתריו לכל עבודתו\" (במדבר ג, כו), ובפסוק זה \u0003מקיש\u0004 \u0005[משווה]\u0006 את ה\u0003מזבח למשכן,\u0004 ולפיכך יש ללמוד מזה: \u0003מה משכן\u0004 היה גובהו \u0003עשר אמות, אף\u0004 ה\u0003מזבח\u0004 היה גובהו \u0003עשר אמות,\u0004 ויש להבין בדרך מיוחדת את המדה האחרת האמורה בגובהו של המזבח (\"ועשית את המזבח... ושלש אמות קומתו\". שמות כז, א).","ושואלים: \u0003ומשכן גופיה מנלן\u0004 \u0005[עצמו מנין לנו]\u0006 שכך היה גובהו? ומשיבים: \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"\u0004ועשית את הקרשים למשכן עצי שיטים עומדים \u0003עשר אמות ארך הקרש\"\u0004 (שמות כו, טו–טז), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בהקמת המשכן: \u0003\"ויפרש את האהל על המשכן\u0004 וישם את מכסה האוהל עליו מלמעלה כאשר ציוה ה' את משה\u0003\"\u0004 (שמות מ, יט). \u0003ואמר רב: משה רבינו\u0004 עצמו \u0003פרשו. מכאן אתה למד גובהן של לויים עשר אמות,\u0004 שאם יכול היה משה בעצמו לעמוד ולפרוש את מכסה האוהל ודאי לא היה גובהו של משה עצמו פחות מעשר אמות, ומן הסתם היו כן גם שאר הלויים. \u0003וגמירי\u0004 \u0005[ולמודים\u0006 אנו\u0005]\u0006 ש\u0003כל טונא דמידלי\u0004 \u0005[משא שמרימים]\u0006 \u0003במוטות\u0004 הריהו \u0003תילתא מלעיל, ותרי תילתי מלתחת\u0004 \u0005[שליש מלמעלה\u0006 בגובה קומת הנושא \u0005ושני שלישים מלמטה],\u0006 ולפי זה \u0003אישתכח דהוה מידלי טובא\u0004 \u0005[נמצא שהיה גבוה הרבה],\u0006 שאם נשאו את המזבח במוטות היה מורם מן הקרקע לפחות שליש מעשר אמות, ושליש מעשר אמות הריהו עשרים טפחים.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שאפשר ללמוד \u0003זאת מארון\u0004 הברית, בלא להניח שהיו הלויים גבוהים משאר בני אדם. ששנינו ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 ה\u0003ארון\u0004 עצמו היה גובהו \u0003תשעה\u0004 טפחים כמפורש בתורה \u0003וכפורת\u0004 שעליו — \u0003טפח,\u0004 הרי כאן עשרה. \u0003וגמירי\u0004 \u0005[ולמודים\u0006 אנו\u0005]\u0006 ש\u0003כל טונא דמידלי\u0004 \u0005[משא שמרימים]\u0006 \u0003במוטות\u0004 הריהו \u0003תילתא מלעיל ותרי תילתי מלרע\u0004 \u0005[שליש מלמעלה ושני שלישים מלמטה],\u0006 ואם כן \u0003אישתכח\u0004 \u0005[נמצא]\u0006 שקצהו התחתון של הארון \u0003למעלה מעשרה\u0004 טפחים \u0003הוה קאי\u0004 \u0005[היה עומד,\u0006 מצוי\u0005].\u0006 ושואלים: \u0003וליגמר\u0004 \u0005[ושילמד]\u0006 \u0003ממשה,\u0004 ומדוע לא הספיקה לנו ההוכחה הראשונה?! ומשיבים: \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003משה שאני\u0004 \u0005[שונה]\u0006 היה משאר הלויים, שהוא היה גבוה בקומתו מהם, ששנינו ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003אין השכינה שורה אלא על\u0004 מי שהוא \u0003חכם גבור ועשיר ובעל קומה,\u0004 והוא שהשכינה שרתה עליו היה צריך להיות גבה \u0003קומה.\u0004","\u0003אמר רב משום\u0004 (בשם) \u0003ר' חייא: המוציא משאוי\u0004 (משא) \u0003בשבת על ראשו\u0004 — \u0003חייב חטאת, שכן אנשי\u0004 המקום \u0003הוצל\u0004 היו \u0003עושין כן,\u0004 שדרכם היתה לשאת משאות על ראשיהם. ושואלים: \u0003ואנשי הוצל רובא דעלמא\u0004 \u0005[רוב העולם\u0006 הם\u0005]?!\u0006 ואף אם נוהגים כן במקום אחד, עדיין נחשבת הוצאה כזו לגבי כל העולם כהוצאה שלא כדרכה! \u0003אלא, אי איתמר, הכי איתמר\u0004 \u0005[אם נאמר\u0006 הדבר, \u0005כך נאמר],\u0006 ש\u0003אמר רב משום ר' חייא: אחד מבני הוצל שהוציא משוי על ראשו בשבת\u0004 — \u0003חייב, שכן בני עירו עושין כן.\u0004 ושוב שואלים: ואף אם בני עירו עושים כן, \u0003ותיבטל דעתו אצל כל אדם\u0004 אחר! שיחיד או קבוצה קטנה הנוהגים בדרך יוצאת מגדר הרגיל אין מחשיבים את נוהגיהם, אלא דנים לפי רוב בני אדם! \u0003אלא, אי איתמר, הכי איתמר\u0004 \u0005[אם נאמר\u0006 הדבר, \u0005כך נאמר]:\u0006 \u0003המוציא משוי על ראשו\u0004 — \u0003פטור\u0004"],["\u0003ואם תימצא\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 כי \u0003אנשי הוצל עושין כן\u0004 — \u0003בטלה דעתן אצל כל\u0004 שאר \u0003אדם.\u0004","\u0003המתכוין להוציא\u0004 חפץ ושיהא החפץ מצוי \u0003לפניו, ובא לו\u0004 אותו חפץ בתוך כדי הילוך \u0003לאחריו\u0004 — \u0003פטור.\u0004 אבל אם התכוון להוציאו \u0003לאחריו ובא לו לפניו\u0004 — \u0003חייב. באמת אמרו: האשה החוגרת בסינר\u0004 (מעין מכנסים) ושמה חפץ \u0003בין מלפניה ובין מלאחריה\u0004 — \u0003חייבת, שכן ראוי\u0004 (דרכו) \u0003להיות חוזר\u0004 (מסתובב). \u0003ר' יהודה אומר: אף מקבלי פתקין,\u0004 שהם שליחי המלכות המעבירים ידיעות ושמים את הפתקין בחגורותיהם שאין מקפידים בהם באיזה צד היה הפתק (רה\"ג) חייבים על הוצאת הפתקים בין מלפניהם בין לאחריהם.","שואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 מי שרצה שיהא החפץ \u0003לפניו ובא לו לאחריו\u0004 ש\u0003פטור,\u0004 שטעמו ש\u0003לא אתעביד\u0004 \u0005[נעשתה]\u0006 \u0003מחשבתו,\u0004 ופטור, שלא לזה התכוון. אם כן, גם אם רצה שיהא \u0003לאחריו ובא לו לפניו נמי, הא\u0004 \u0005[גם כן, הרי]\u0006 \u0003לא אתעביד\u0004 \u0005[נעשתה]\u0006 \u0003מחשבתו! אמר ר' אלעזר: תברא\u0004 \u0005[שבורה],\u0006 כלומר, משנה זו מבטאת דעות שני חכמים, ו\u0003מי ששנה\u0004 הלכה \u0003זו לא שנה\u0004 הלכה \u0003זו. אמר רבא: ומאי קושיא\u0004 \u0005[ומהי הקושיה]\u0006 שיש בדבר זה? \u0003דילמא\u0004 \u0005[שמא]\u0006 אפשר להסביר זאת היטב בדרך זו: רצה שיהא החפץ \u0003לפניו ובא לו לאחריו היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 ש\u0003פטור\u0004 — משום ש\u0003נתכוון לשמירה מעולה\u0004 שיוכל לראות את החפץ תמיד, \u0003ועלתה בידו\u0004 לבסוף \u0003שמירה פחותה,\u0004 ומכיון שאין רצונו בכך אין בכך כדי להחשיבה כמלאכה, ולכן פטור, ואילו דבר ששם \u0003לאחריו ובא לו לפניו היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 ש\u0003חייב\u0004 — משום ש\u0003נתכוון\u0004 מתחילה \u0003לשמירה פחותה ועלתה בידו\u0004 לבסוף \u0003שמירה מעולה.\u0004","\u0003אלא מאי קושיא\u0004 \u0005[מהי הקושיה]\u0006 — \u0003דיוקא דמתניתין קשיא\u0004 \u0005[הדיוק\u0006 שאפשר לדייק \u0005מן המשנה\u0006 הוא ש\u0005קשה],\u0006 וכך נדייק: \u0003המתכוין להוציא לפניו ובא לו לאחריו\u0004 — \u0003פטור,\u0004 ומכאן נבין: \u0003הא\u0004 \u0005[הרי]\u0006 אם נתכוין מתחילה שיהיה \u0003לאחריו ובא לו\u0004 אכן כרצונו ונשאר \u0003לאחריו\u0004 — \u0003חייב. אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של המשנה\u0005]:\u0006 \u0003לאחריו ובא לו לפניו הוא\u0004 ש\u0003חייב,\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא\u0004 נתכוין מתחילה שיהיה \u0003לאחריו ובא לו\u0004 (נשאר) \u0003לאחריו\u0004 — \u0003פטור.\u0004 ויש איפוא סתירה בין הדיוק מן המשפט הראשון ובין הדיוק במשפט השני, ועל כך \u0003אמר ר' אלעזר: תברא\u0004 \u0005[שבורה]\u0006 משנה זו, מי \u0003ששנה\u0004 הלכה \u0003זו לא\u0004 הלכה \u0003שנה זו.\u0004","\u0003אמר רב אשי: מאי קושיא\u0004 \u0005[מה הקושיה]?\u0006 \u0003דילמא\u0004 \u0005[שמא]\u0006 בסגנון \u0003לא מיבעיא קאמר\u0004 \u0005[נצרכה אמר],\u0006 וכך נבין: \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר בנתכוין שיהא החפץ \u0003לאחריו ובא לו לאחריו\u0004 שהוא \u0003חייב, דאיתעבידא\u0004 \u0005[ש\u0006כן \u0005נעשתה]\u0006 \u0003מחשבתו, אלא אפילו\u0004 כשנתכוין שיהא החפץ \u0003לאחריו ובא לו\u0004 לבסוף \u0003לפניו איצטריכא ליה\u0004 \u0005[נצרכה לו]\u0006 לומר שהוא חייב, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003הואיל ולא איתעביד\u0004 \u0005[נעשתה]\u0006 \u0003מחשבתו\u0004 ש\u0003לא ליחייב\u0004 \u0005[יתחייב],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שמאחר ש\u0003נתכוון לשמירה פחותה ועלתה בידו שמירה מעולה\u0004 — שהוא \u0003חייב.\u0004","\u0003ו\u0004לגופו של דבר, בענין חפץ שנתכוין שיהא \u0003לאחריו ובא לו לאחריו תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המוציא מעות בפונדתו\u0004 (חגורה חלולה), \u0003ופיה למעלה\u0004 — \u0003חייב,\u0004 שכן זוהי דרך הוצאה רגילה. ואם הוציאה כש\u0003פיה למטה\u0004 — \u0003ר' יהודה מחייב, וחכמים פוטרין. אמר להן ר' יהודה\u0004 לחכמים: האם \u0003אי\u0004 (אין) \u0003אתם מודים בלאחריו ובא לו לאחריו שהוא חייב?\u0004 נמצא שאם רוצה אדם לשמור את חפציו מתחילה שמירה פחותה והוציא בדרך זו הריהו חייב. \u0003ואמרו לו: ואי אתה מודה\u0004 במוציא \u0003כלאחר ידו ורגלו שהוא פטור?\u0004 הרי שהמוציא שלא כדרך הכל אין זו נחשבת כהוצאה!","\u0003אמר ר' יהודה: אני אמרתי\u0004 להם \u0003דבר אחד\u0004 כחיזוק לדברי \u0003והן אמרו\u0004 לי \u0003דבר אחד. אני לא מצאתי תשובה לדבריהם והן לא מצאו תשובה לדברי.\u0004 ומכאן נדייק: \u0003מדקאמר להו\u0004 \u0005[ממה שאמר להם]\u0006 \u0003\"אי אתם מודין \"\u0004שיש לחייבו בשהוציא מעות בפונדתו ופיה למטה — \u0003לאו\u0004 \u0005[האם לא]\u0006 נלמד \u0003מכלל\u0004 הדברים \u0003דפטרי רבנן\u0004 \u0005[שפוטרים חכמים]\u0006 בכגון זה? ואם כן מחלוקת היא בין ר' יהודה וחכמים בענין זה. ושואלים: \u0003וליטעמיך, דקאמרי ליה\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 בפירוש הדברים, מה \u0003דקאמרי ליה\u0004 \u0005[שאמרו לו]\u0006 חכמים \u0003\"אי אתה מודה\",\u0004 האם נלמד \u0003מכלל\u0004 הדברים ש\u0003מחייב ר' יהודה\u0004 אפילו כלאחר יד? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 במפורש: המוציא \u0003לאחר ידו ורגלו\u0004 — ל\u0003דברי הכל פטור!\u0004","\u0003אלא\u0004 יש להבין את הדברים כך: \u0003לאחריו ובא לו לאחריו\u0004 — ל\u0003דברי הכל חייב. לאחר ידו ורגלו\u0004 — ל\u0003דברי הכל פטור. כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה במוציא מעות \u0003בפונדתו ופיה למטה. מר מדמי ליה\u0004 \u0005[חכם זה,\u0006 ר' יהודה \u0005מדמה אותה]\u0006 \u0003לאחריו ובא לו לאחריו,\u0004 ומחייב, \u0003ומר מדמי ליה\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005מדמה אותה]\u0006 למקרה ש\u0003לאחר ידו ורגלו,\u0004 ופוטרים.","שנינו במשנה: \u0003באמת אמרו\u0004 ש\u0003האשה\u0004 החוגרת בסינר והוציאה חפץ בשבת בין מלפניה ובין מלאחריה — חייבת. והוסיפו מן התוספתא: \u0003כל\u0004 מקום ששנו בלשון \u0003\"באמת\"\u0004 — \u0003הלכה היא\u0004 ובה לא נחלקו. עוד שנינו במשנה ש\u0003ר' יהודה אומר\u0004 ש\u0003אף מקבלי פתקין\u0004 שהם שליחי המלכות המעבירים ידיעות ושמים את הפתקים בחגורותיהם שאין מקפידים בהם באיזה צד היה הפתק (רה\"ג) חייבים על הוצאת הפתקים בין מלפניהם בין לאחריהם. \u0003תנא\u0004 \u0005[שנינו]\u0006 בהסבר הדבר: \u0003שכן לבלרי מלכות עושין כן,\u0004 והפתקים שלהם נמצאים בכל צד של חגורתם.","\u0003המוציא\u0004 בשבת \u0003ככר\u0004 (גוש גדול) \u0003לרשות הרבים\u0004 — \u0003חייב.\u0004 אבל אם \u0003הוציאוהו שנים\u0004 ביחד — \u0003פטורין,\u0004 כיון שאף אחד מהם לא עשה מלאכה שלמה. ואולם אם \u0003לא יכול אחד להוציאו\u0004 בעצמו \u0003ו\u0004לכן \u0003הוציאוהו שנים\u0004 — \u0003חייבין. ור' שמעון פוטר\u0004 אפילו במקרה זה.","\u0003אמר רב יהודה אמר רב, ואמרי ליה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003אביי, ואמרי ליה\u0004 \u0005[ויש אומרים]\u0006 כי \u0003במתניתא תנא\u0004 \u0005[בברייתא שנינו]\u0006 שכך נחלקו הדעות: חפץ או מעשה שעשו אותו שניים כאשר \u0003זה יכול\u0004 לעשות בעצמו \u0003וזה יכול\u0004 לעשותו בעצמו — \u0003ר' מאיר מחייב, ור' יהודה ור' שמעון פוטרים.\u0004 וכאשר \u0003זה אינו יכול וזה אינו יכול,\u0004 שכל אחד מהם אינו יכול לעשות מלאכה זו לבדו ולכן עשו אותה שניים — \u0003ר' יהודה ור' מאיר מחייבים ור' שמעון פוטר.\u0004 וכאשר \u0003זה יכול וזה אינו יכול\u0004 ועשו שניהם — ל\u0003דברי הכל חייב.\u0004","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003המוציא ככר לרשות הרבים\u0004 — \u0003חייב. הוציאו שנים\u0004 — \u0003ר' מאיר מחייב, ור' יהודה אומר: אם לא יכול אחד להוציאו והוציאו שנים\u0004 — \u0003חייבין, ואם לאו\u0004 \u0005[לא],\u0006 שכל אחר יכול להוציאו לבדו והוציאוהו יחד — \u0003פטורים. ור' שמעון פוטר\u0004 אפילו כששניהם אינם יכולים. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 מה מקורם במקרא? ומשיבים, \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים]\u0006 בתורת כהנים: נאמר \"ואם נפש אחת תחטא בשגגה מעם הארץ \u0003בעשתה\u0004 אחת ממצוות ה' אשר לא תעשינה ואשם\" (ויקרא ד, כז). ודקדקו: \u0003\"בעשתה\"\u0004 משמעו — בעשותו אותה, כלומר את כולה, ולכן מתחייב \u0003העושה את\u0004 העבירה \u0003כולה ולא העושה את מקצתה, כיצד? שנים שהיו אוחזין במלגז\u0004 (קלשון) \u0003ולוגזין\u0004 (אוספים) את השבלים, או \u0003בכרכר\u0004 (מכלי האריגה) \u0003ושובטין\u0004 (אורגים את חוטי הערב), או \u0003בקולמוס וכותבין,\u0004 או מחזיקים \u0003בקנה והוציאו\u0004 אותו \u0003לרשות הרבים, יכול יהו חייבין\u0004 — \u0003תלמוד לומר: \"בעשתה\"\u0004 — לומר שדווקא \u0003העושה את כולה\u0004 חייב \u0003ולא העושה\u0004 רק את \u0003מקצתה.\u0004"],["\u0003בעיגול של דבילה\u0004 שהוא כבד מכדי משא אדם אחד \u0003והוציאו\u0004 אותו \u0003לרשות הרבים,\u0004 או שהיו מחזיקים \u0003בקורה והוציאו\u0004 אותה \u0003לרשות הרבים, ר' יהודה אומר: אם לא יכול אחד להוציאו\u0004 לבדו \u0003והוציאוהו שנים\u0004 — \u0003חייבין, ואם לאו\u0004 \u0005[לא],\u0006 שיכול להוציאו לבדו — \u0003פטורין. ר' שמעון אומר: אף על פי שלא יכול אחד להוציאו, והוציאוהו שנים\u0004 — \u0003פטורים, לכך\u0004 (לכן) \u0003נאמר \"בעשתה\"\u0004 (ויקרא ד, כז) — לקבוע כלל: \u0003יחיד שעשאה\u0004 — \u0003חייב, שנים שעשאוה\u0004 — \u0003פטורין.\u0004","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה\u0006\u0005,\u0006 באיזה עקרון, \u0005הם נחלקו]?\u0006 ומשיבים: נחלקו \u0003ב\u0004פירושו של \u0003האי קרא\u0004 \u0005[פסוק זה]\u0006 שנאמר \u0003\"ואם נפש אחת תחטא בשגגה מעם הארץ בעשתה\u0004 אחת ממצוות ה' אשר לא תעשינה ואשם\". \u0003ר' שמעון סבר\u0004 \u0005[סבור]:\u0006 \u0003תלתא מיעוטי כתיבי\u0004 \u0005[שלושה מיעוטים נאמרו\u0006 בפסוק\u0005],\u0006 שכאילו נאמר \u0003\"נפש תחטא\", \"אחת תחטא\", \"בעשתה תחטא\",\u0004 ולכאורה די היה בכתוב \"ואם יחטא מעם הארץ\" כדי להביע אותה משמעות, ועל כן ודאי יש לומר שהמילים היתירות באו למעט, וכך יש להבין: \"נפש\" — ולא נפשות, \"אחת\" — ולא שתיים, \"בעשותה\" — ולא בעשיית שניים. \u0003חד למעוטי\u0004 \u0005[\u0006כתוב \u0005אחד\u0006 בא \u0005למעט]\u0006 כאשר שני אנשים עושים שני חלקיה של עבירה, וכגון ש\u0003זה,\u0004 אדם אחד \u0003עוקר\u0004 מרשות אחת \u0003וזה,\u0004 אחר, \u0003מניח\u0004 ברשות אחרת. \u0003וחד למעוטי\u0004 \u0005[ו\u0006כתוב \u0005אחד\u0006 בא \u0005למעט]\u0006 כאשר \u0003זה יכול וזה יכול\u0004 לעשות את הדבר בעצמו, ועשו שניהם יחד. \u0003וחד למעוטי\u0004 \u0005[ו\u0006כתוב \u0005אחד\u0006 בא \u0005למעט]\u0006 אפילו כאשר \u0003זה אינו יכול וזה אינו יכול,\u0004 אבל כיון שעשו שניהם יחד אותה עבירה — שניהם פטורים.","\u0003ור' יהודה\u0004 סבור כי \u0003חד למעוטי\u0004 \u0005[\u0006כתוב \u0005אחד\u0006 בא \u0005למעט]\u0006 כאשר \u0003זה עוקר וזה מניח,\u0004 שאף ר' יהודה מודה שפטור, \u0003וחד למעוטי\u0004 \u0005[ו\u0006כתוב \u0005אחד\u0006 בא \u0005למעט]\u0006 \u0003זה יכול וזה יכול, וחד למעוטי\u0004 \u0005[ו\u0006כתוב \u0005אחד\u0006 בא \u0005למעט]\u0006 \u0003יחיד שעשאה\u0004 לעבירה \u0003בהוראת בית דין.\u0004 שאם הורה בית דין בטעות והתיר את האסור, והלך יחיד ועשה על פי הוראת בית הדין, הרי הוא פטור אף מקרבן חטאת, כאנוס. \u0003ו\u0004אילו \u0003ר' שמעון\u0004 סבור כי \u0003יחיד שעשאה\u0004 לעבירה \u0003בהוראת בית דין\u0004 — \u0003חייב\u0004 להביא קרבן חטאת על שגגתו, שאמנם אין דינו כמזיד בדבר, אבל עבירה זו נכללת בתחום השגגות.","ושואלים: \u0003ור' מאיר\u0004 המחייב גם כאשר זה יכול וזה יכול, כיצד מבין הוא את המיעוט השלישי? ומשיבים לשיטתו: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"נפש תחטא \" \"אחת תחטא \" \"בעשתה תחטא \"?\u0004 והרי לא שלושה מיעוטים כתובים בפסוק במפורש אלא רק \u0003תרי מעוטי כתיבי\u0004 \u0005[שני מיעוטים נאמרו],\u0006 שכן מה שנאמר \"נפש אחת תחטא\" ביטוי אחד הוא, שזו היא דרך לשון הכתוב, ואם כן \u0003חד למעוטי\u0004 \u0005[\u0006כתוב \u0005אחד\u0006 בא \u0005למעט]\u0006 כאשר \u0003זה עוקר וזה מניח, וחד למעוטי\u0004 \u0005[ו\u0006כתוב \u0005אחד\u0006 בא \u0005למעט]\u0006 את \u0003היחיד שעשאה בהוראת בית דין.\u0004","מקודם שנינו ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 כאשר \u0003זה יכול\u0004 לעבור עבירה לבדו \u0003וזה אינו יכול,\u0004 אם עשו שניהם יחד — ל\u0003דברי הכל חייב.\u0004 ומבררים: \u0003הי מנייהו מיחייב\u0004 \u0005[איזה,\u0006 מי \u0005מהם חייב]?\u0006 \u0003אמר רב חסדא: זה שיכול\u0004 לעשותה לבדו הוא שחייב, \u0003דאי\u0004 \u0005[שאם]\u0006 הכוונה ל\u0003זה שאינו יכול\u0004 — \u0003מאי קא עביד\u0004 \u0005[מה הוא עושה]\u0006 והרי אין במעשהו כדי לעבור! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב המנונא\u0004 לרב חסדא: הרבה עושה, \u0003דקא\u0004 \u0005[שהוא]\u0006 \u0003מסייע בהדיה\u0004 \u0005[לו]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 כל ה\u0003מסייע\u0004 לדבר שאחר יכול לעשותו לבדו \u0003אין בו\u0004 בסיוע זה \u0003ממש,\u0004 ואינו נחשב לכל ענין.","\u0003אמר רב זביד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא : אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 כשיטה זו בענין משכב הזב ומרכבו, שדין תורה הוא שכל דבר שהזב יושב או רוכב עליו טמא, אף אם אינו נוגע בו במישרין. ואמרו: \u0003היה\u0004 הזב \u0003יושב על גבי המטה וארבע טליות\u0004 (טליתות, בגדים) \u0003תחת רגלי המטה\u0004 — \u0003טמאות\u0004 כולן, שאנו אומרים כי כובד הזב נשען על כולן כאחת, \u0003מפני ש\u0004המיטה \u0003אינה יכולה לעמוד על שלש\u0004 רגלים בלבד. \u0003ור' שמעון מטהר,\u0004 כיון שרק חלק ממשקלו של הזב מונח על טלית אחת. ואולם אם \u0003היה רוכב על גבי בהמה וארבע טליות תחת רגלי הבהמה\u0004 — \u0003טהורות\u0004 כולן, \u0003מפני שיכולה\u0004 בהמה \u0003לעמוד על שלש\u0004 רגלים. \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003הא קמסייע בהדי הדדי\u0004 \u0005[הרי\u0006 כל רגל \u0005מסייעת עם האחרות]!\u0006 אלא \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 ש\u0003מסייע אין בו ממש?\u0004","\u0003אמר רב יהודה מדיסקרתא: לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי \u0003מסייע יש בו ממש, ושאני הכא דעקרה לה\u0004 \u0005[ו\u0006אולם \u0005שונה כאן,\u0006 בבהמה \u0005ש\u0006היא \u0005עוקרת אותה\u0006\u0005,\u0006 את רגלה\u0005]\u0006 \u0003לגמרי,\u0004 שלא רק שהבהמה מסוגלת לעמוד על שלוש רגלים, אלא בפועל מרימה היא את רגלה ואינה נשענת עליה. את דברי רב יהודה מדיסקרתא דוחים: \u0003וכיון דזימנין עקרה הא, וזימנין עקרה הא\u0004 \u0005[שלפעמים עוקרת\u0006 רגל \u0005זו, ולפעמים עוקרת\u0006 את \u0005זו],\u0006 אם כן \u0003ליהוי\u0004 \u0005[שתהיה]\u0006 \u0003כזב המתהפך! מי\u0004 \u0005[האם]\u0006 \u0003לא תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003זב שהיה מוטל על חמשה ספסלין או על חמש פונדאות\u0004 (חגורות חלולות רחבות וארוכות), אם היה מונח עליהן \u0003לאורכן\u0004 — \u0003טמאים,\u0004 כיון שהיה כל גופו מונח על אחד הספסלים או אחת הפונדאות. ואם היה מוטל עליהן \u0003לרחבן\u0004 — \u0003טהורין,\u0004 כיון שאין כל משקלו נשען על אחת מהן. ואולם אם \u0003ישן\u0004 עליהם לרוחבן, \u0003ספק\u0004 היה \u0003מתהפך עליהן\u0004 ושמא הזדמן שבתוך שנתו שכב לאורך אחד הספסלים — \u0003טמאין.\u0004 הרי שזב המעביר את כובד משקלו ממקום אחד למשנהו מטמא כל מקום ומקום, ולכן הנימוק שהבהמה מרימה רגל אחת בכל פעם אינו מספיק להחשיבה כאילו אינה נושאת עליה כלל את הזב.","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 טיהרו בבהמה \u0003משום דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 כי \u0003מסייע אין בו ממש\u0004 וכל רגל אינה אלא בבחינת מסייע. וכן \u0003אמר רב פפי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 סיוע לשיטה זו"],["\u0003ר' יוסי אומר:\u0004 אם היה הזב רוכב על גבי בהמה וטלית מונחת תחתיה, אם היה רוכב על \u0003הסוס\u0004 הרי הוא \u0003מטמא על ידיו\u0004 (רגליו הקדמיות), שאם הטלית מונחת תחת ידי הסוס הריהי טמאה, ואולם אם היתה מונחת תחת רגליו — הריהי טהורה. ואם היה רוכב על \u0003החמור\u0004 — הריהו מטמא \u0003על רגליו\u0004 (האחוריות), שאם הטלית מונחת תחת רגליו הריהי טמאה, ואולם אם היתה מונחת תחת ידיו — הריהי טהורה. וטעם החילוק: משום \u0003שמשענת הסוס\u0004 בעיקרה \u0003על ידיו, ו\u0004של ה\u0003חמור על רגליו. ואמאי\u0004 \u0005[ומדוע]\u0006 במקרה שמונחת הטלית תחת רגלי הסוס או ידי החמור תהא טהורה? \u0003הא קא מסייע בהדי הדדי\u0004 \u0005[\u0006\u0005הלא\u0006 הרגלים \u0005מסייעות אלו לאלו]!\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 כי \u0003מסייע אין בו ממש. אמר רב אשי: אף אנן נמי תנינא\u0004 \u0005[אנחנו גם כן שנינו]\u0006 סיוע לדבר זה ממשנה אחרת. ששנינו, \u0003ר' אליעזר אומר:\u0004 כהן שהיה עומד במקדש באופן ש\u0003רגלו אחת על הכלי ורגלו אחת על הרצפה,\u0004 או \u0003רגלו אחת על האבן ורגלו אחת על הרצפה,\u0004 ועבד אחת מעבודות כהונה. ומאחרר וקיימת כאן שאלה האם נחשיבנו כאילו שלא עמד כלל על הרצפה שעבודתו פסולה, או שמא נחשיבנו כעומד על הרצפה ועבודתו כשרה, על כן הדין הוא ש\u0003רואין כל שאילו ינטל הכלי ו\u0004כן אם \u0003תינטל האבן\u0004 ו\u0003יכול\u0004 עדיין \u0003לעמוד על רגלו אחת\u0004 שהיתה על הרצפה — \u0003עבודתו כשרה, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003עבודתו פסולה.\u0004","ושוב יש לשאול \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 יהא כשר? \u0003הא קא\u0004 \u0005[הרי הוא]\u0006 \u0003מסייע בהדי הדדי\u0004 \u0005[ב\u0006רגל \u0005אחת לאחרת]!\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 כי \u0003מסייע אין בו ממש. אמר רבינא: אף אנן נמי תנינא\u0004 \u0005[אנחנו גם כן שנינו]\u0006 סיוע לדבר זה ממשנה אחרת. ששנינו שכל עבודות המקדש חייבות להיעשות ביד ימין דווקא, אבל אם \u0003קיבל\u0004 את הדם \u0003בימין, ושמאל מסייעתו\u0004 — \u0003עבודתו כשרה. ואמאי\u0004 \u0005[ומדוע]\u0006 תהא עבודתו כשרה, \u0003הא קא\u0004 \u0005[הרי הוא]\u0006 \u0003מסייע\u0004 היד השמאלית \u0003בהדי הדדי\u0004 \u0005[אלו לאלו]!\u0006 אלא \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 ש\u0003מסייע אין בו ממש.\u0004 ומסכמים את הראיות הללו: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה].\u0006","מקודם שנינו ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 שאם \u0003זה יכול\u0004 לעבור את העבירה לבדו \u0003וזה יכול, ר' מאיר מחייב. איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים \u0005]\u0006 שאלה זו: האם \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003שיעור\u0004 מלאכה שלמה \u0003לזה ושיעור\u0004 מלאכה \u0003לזה, או דילמא\u0004 \u0005[שמא]\u0006 די ב\u0003שיעור אחד לכולם. רב חסדא ורב המנונא\u0004 נחלקו בדבר; \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שצריך שיהא במלאכה שעושים כדי \u0003שיעור לזה ושיעור לזה. וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שדי ב\u0003שיעור אחד לכולן. אמר רב פפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא : אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 כשיטה שדי בשיעור אחד לכולם במשנת זבים: \u0003היה\u0004 הזב \u0003יושב על גבי מטה וארבע טליות\u0004 (טליתות) \u0003תחת ארבע רגלי המטה\u0004 — \u0003טמאות, מפני שאין יכולה\u0004 המיטה \u0003לעמוד על שלש\u0004 רגלים. \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 יהא טמא? \u0003ליבעי\u0004 \u0005[שיצטרכו]\u0006 שיהא כדי \u0003שיעור זיבה לזה,\u0004 לרגל זו, \u0003ושיעור זיבה לזה,\u0004 לרגל זו, שכל ארבע הטליות ייטמאו רק אם ישבו ארבע זבים על המיטה! \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 שכדי לטמא את הטליתות די ב\u0003שיעור אחד לכולן,\u0004 ואם מתחייבים שניים בשותפות הרי הם חייבים אפילו על שיעור אחד.","\u0003אמר רב נחמן בר יצחק: אף אנן נמי תנינא\u0004 \u0005[אנחנו גם כן שנינו]\u0006 סיוע נוסף לדבר ממקור אחר: \u0003צבי שנכנס לבית, ונעל אחד בפניו\u0004 את הדלת בשבת — \u0003חייב\u0004 משום צד בשבת. \u0003נעלו שנים\u0004 — \u0003פטורין. לא יכול אחד לנעול\u0004 דלת זו לבדו, \u0003ונעלו שנים\u0004 — \u0003חייבים. ואמאי\u0004 \u0005[ומדוע]\u0006 חייבים? \u0003ליבעי\u0004 \u0005[שיצטרכו]\u0006 שיהא כדי \u0003שיעור צידה לזה ושיעור צידה לזה! לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 הרי זה בודאי משום שאנו סבורים ש\u0003שיעור אחד\u0004 די \u0003לכולם. אמר רבינא: אף אנן נמי תנינא\u0004 \u0005[אנחנו גם כן שנינו]\u0006 סיוע נוסף לדבר ממה ששנינו במקור אחר: \u0003השותפין שגנבו\u0004 בהמה \u0003וטבחו\u0004 אותה — \u0003חייבין\u0004 לשלם פי ארבע או חמש, כאמור בתורה. \u0003ואמאי\u0004 חייבים? \u0003ליבעי\u0004 \u0005[שיצטרכו]\u0006 שיהא כדי \u0003שיעור טביחה לזה ושיעור טביחה לזה! לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 שדי ב\u0003שיעור אחד לכולם?\u0004","\u0003ואמר רב אשי: אף אנן נמי תנינא\u0004 \u0005[אנחנו גם כן שנינו]\u0006 סיוע נוסף לדבר ממה ששנינו מעין זה: \u0003שנים שהוציאו\u0004 בשבת \u0003קנה של גרדי\u0004 (אורג) — \u0003חייבין. ואמאי\u0004 חייבים? \u0003ליבעי\u0004 \u0005[שיצטרכו]\u0006 שיהא כדי \u0003שיעור הוצאה לזה ושיעור הוצאה לזה! לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 \u0003שיעור אחד לכולם? אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי:\u0004 מכאן אין ראייה, \u0003דילמא דאית ביה\u0004 \u0005[שמא שיש בו\u0006 בקנה\u0005]\u0006 \u0003כדי\u0004 שיעור הראוי \u0003לבשל\u0004 בו \u0003ביצה קלה לזה וביצה קלה לזה,\u0004 שהוא השיעור להוצאת עץ בשבת! ענה לו: \u0003אם כן, לישמעינן\u0004 \u0005[שישמיענו]\u0006 ב\u0003קנה דעלמא\u0004 \u0005[סתם],\u0006 \u0003מאי שנא דגרדי\u0004 \u0005[ומה שונה\u0006 זה ששנינו בקנה \u0005של אורג]?\u0006 אלא ודאי נתכוונו לקנה כזה שהוא יחידה לעצמו. ושוב דוחה רב אחא: \u0003ודילמא דאית ביה\u0004 \u0005[ושמא שיש בו\u0006 בקנה זה\u0005]\u0006 גודל מספיק \u0003כדי לארוג מפה לזה וכדי לארוג מפה לזה\u0004 שהוא שיעור חשוב לשניים, \u0003אלא, מהא ליכא למשמע מינה\u0004 \u0005[מ\u0006משנה \u0005זו אין ללמוד ממנה\u0006 דבר לענין זה\u0005].\u0006","\u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רב נחמן: שנים שהוציאו\u0004 בשבת \u0003קנה של גרדי\u0004 — \u0003פטורין, ור' שמעון מחייב.\u0004 ותהה רב נחמן: \u0003כלפי לייא\u0004 \u0005[לאן אתה פונה]?!\u0006 הרי זה ממש היפך סברותיהם! \u0003אלא אימא\u0004 \u0005[אמור,\u0006 תקן את הברייתא]: \u0003חייבין, ור' שמעון פוטר.\u0004","\u0003המוציא\u0004 בשבת \u0003אוכלין פחות מכשיעור בכלי\u0004 — \u0003פטור אף על\u0004 הוצאת \u0003הכלי, שהכלי טפלה\u0004 לאוכל שמוציא בו. וכיון שאינו מתחייב על האוכל אינו מתחייב אף על הכלי. וכן המוציא \u0003את\u0004 האדם \u0003החי במטה\u0004 — \u0003פטור אף על המטה, שהמטה טפלה לו.\u0004 המוציא \u0003את המת במטה\u0004 — \u0003חייב. וכן\u0004 המוציא \u0003כזית מן המת ו\u0004כן \u0003כזית מן הנבלה ו\u0004כן \u0003כעדשה מן השרץ\u0004 שהם השיעורים הקטנים ביותר שחלות עליהם טומאות אלה — \u0003חייב, ור' שמעון פוטר,\u0004 שלשיטתו מלאכה שאינה נעשית לצורך עצמה, אין חייבים עליה, ואין איש מוציא את הנבילה או את המת אלא כדי להיפטר מהם, ולא לצרכו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003המוציא\u0004 בשבת \u0003אוכלין כשיעור, אם\u0004 הוציאם \u0003בכלי\u0004 — \u0003חייב על האוכלין, ופטור על הכלי. ואם היה\u0004 אותו ה\u0003כלי צריך לו\u0004 להשתמש בו למטרה אחרת — \u0003חייב אף על הכלי.\u0004 ותמהים על ההלכה השניה: האם \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 מהלכה זו שה\u0003אוכל שני זיתי חלב בהעלם אחד חייב שתים?\u0004 והרי המוציא כלי ואוכל בתוכו עושה שני פרטים של מלאכה אחת, מלאכת הוצאה, ומדוע יהא חייב שתיים? \u0003אמר רב ששת: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון\u0004"],["\u0003ששגג על האוכלין והזיד על הכלי,\u0004 וחייב קרבן חטאת על האוכלים וכרת על הכלי (רה\"נ). \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב אשי: והא\u0004 \u0005[והרי]\u0006 \u0003\"אף על הכלי\" קתני\u0004 \u0005[שנינו],\u0006 ומכאן שיש בהם חיוב מאותו סוג! \u0003אלא אמר רב אשי:\u0004 יש לומר שמדובר ב\u0003כגון ששגג בזה ובזה,\u0004 בכלי ובאוכל, \u0003ונודע לו\u0004 על אחד מהם, \u0003וחזר ונודע לו\u0004 על האחר, \u0003ובפלוגתא\u0004 \u0005[ובמחלוקת]\u0006 \u0003ר' יוחנן ור' שמעון בן לקיש\u0004 שהובאה קודם בשאלה זו, האם שתי ידיעות מחלקות עבירה אחת עד שיצטרך להקריב שתי חטאות.","שנינו במשנה שהמוציא \u0003את החי במטה פטור אף על המטה.\u0004 ומציעים: \u0003לימא מתניתין\u0004 \u0005[האם נאמר\u0006 כי \u0005משנתנו]\u0006 כשיטת \u0003ר' נתן היא ולא\u0004 כ\u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המוציא\u0004 בשבת \u0003בהמה\u0004 או \u0003חיה ו\u0004כן \u0003עוף לרשות הרבים, בין\u0004 שהיו \u0003חיין ובין\u0004 שהיו \u0003שחוטין\u0004 — \u0003חייב. ר' נתן אומר: על שחוטין\u0004 — \u0003חייב ועל חיין\u0004 — \u0003פטור,\u0004 וטעמו: \u0003שהחי נושא את עצמו,\u0004 שהחי משתדל להקל את עצמו ומשתתף לפיכך בנשיאתו. \u0003אמר רבא: אפילו תימא רבנן\u0004 \u0005[תאמר\u0006 שמשנתנו כדעת \u0005חכמים],\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי רבנן עליה\u0004 \u0005[חלוקים חכמים עליו]\u0006 על \u0003ר' נתן אלא בבהמה, חיה ועוף דמשרבטי נפשייהו\u0004 \u0005[ש\u0006הם \u0005משמיטים\u0006 ומפילים את \u0005עצמם],\u0006 \u0003אבל אדם חי\u0004 ש\u0003נושא את עצמו\u0004 — \u0003אפילו רבנן מודו\u0004 \u0005[חכמים מודים]\u0006 שהמוציאו פטור.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר אהבה לרבא: והא דתנן\u0004 \u0005[ו\u0006הלכה \u0005זו ששנינו\u0006 במשנה\u0005]\u0006 שאסור למכור לגוי בהמות עבודה שמא על ידי כך יגיעו הדברים שבהמת ישראל השייכת עדיין לישראל תעשה עבודה בשבת, ו\u0003בן בתירא מתיר בסוס. ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003בן בתירא מתיר בסוס\u0004 למוכרו לרכיבה \u0003מפני שהוא עושה בו מלאכה שאין חייבין עליו חטאת,\u0004 שאין רכיבה על הסוס נחשבת כמלאכה ממש. \u0003ואמר ר' יוחנן: בן בתירא ור' נתן אמרו דבר אחד,\u0004 ששניהם סבורים שהרכבת חי אינה נחשבת לנשיאת משא. \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003לא פליגי רבנן עליה\u0004 \u0005[נחלקו חכמים עליו]\u0006 על \u0003ר' נתן אלא בבהמה חיה ועוף משום דמשרבטי נפשייהו\u0004 \u0005[ש\u0006הם \u0005משמיטים\u0006 את \u0005עצמם]\u0006 \u0003מאי איריא\u0004 \u0005[מדוע דווקא]\u0006 אמר ר' יוחנן ש\u0003בן בתירא ור' נתן\u0004 הסכימו לכך? \u0003והאמרת\u0004 \u0005[והרי אמרת]\u0006 כי בהם \u0003אפילו רבנן מודו\u0004 \u0005[חכמים מודים]!\u0006 ומשיבים: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר' יוחנן\u0004 דבר זה התכוון ל\u0003סוס המיוחד ל\u0004נשיאת \u0003עופות.\u0004 ושואלים: \u0003ומי איכא\u0004 \u0005[והאם יש]\u0006 \u0003סוס המיוחד לעופות?\u0004 ומשיבים: \u0003אין, איכא דבי וייאדן\u0004 \u0005[כן, יש סוס\u0006 הנושא את \u0005בזי הציד].\u0006","\u0003אמר ר' יוחנן: ומודה ר' נתן ב\u0004אדם \u0003כפות,\u0004 שאינו נחשב כמסוגל להקל ממשא עצמו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר מתנה לאביי: והא הני פרסאי דכמאן דכפיתי דמו\u0004 \u0005[והרי אותם פרסים שכמי ש\u0006הם \u0005כפותים\u0006 הם \u0005נחשבים]\u0006 שהיו עטופים בשריון כבד ורוכבים תמיד על סוסים, \u0003ו\u0004בכל זאת \u0003אמר ר' יוחנן: בן בתירא ור' נתן אמרו דבר אחד,\u0004 והתירו למכור סוסים אפילו לפרסים! ומתרצים: ביסודו של דבר אין לומר שהפרסים אינם מסוגלים לרדת מעל סוסיהם, אלא \u0003התם\u0004 \u0005[שם],\u0006 \u0003רמות רוחא הוא דנקיט להו\u0004 \u0005[גסות הרוח היא המחזיקה בהם]\u0006 ומשום כך אינם יורדים מן הסוסים. וראייה לדבר: \u0003דההוא פרדשכא דרתח מלכא עילויה, ורהיט תלתא פרסי בכרעיה\u0004 \u0005[שאותו פרש שכעס המלך עליו, ורץ שלוש פרסאות ברגליו],\u0006 הרי שאף הפרסיים הרוכבים אינם ככפותים ומסוגלים להלך גם בלא סוסיהם.","שנינו במשנה שלדעת התנא קמא המוציא \u0003את המת במטה חייב, וכן\u0004 המוציא \u0003כזית מן המת\u0004 וכזית מן הנבילה וכעדשה מן השרץ — חייב, ור' שמעון פוטר. \u0003אמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן, ו\u0004כן \u0003אמר רב יוסף\u0004 שכך \u0003אמר ר' שמעון בן לקיש: פוטר היה ר' שמעון\u0004"],["\u0003אף במוציא את המת לקוברו. אמר רבא: ומודה ר' שמעון במר\u0004 (מעדר) שהמוציאו בשבת כדי \u0003לחפור בו, וספר תורה\u0004 כדי \u0003לקרות בו\u0004 — שהוא \u0003חייב.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 \u0003דאי הא נמי\u0004 \u0005[שאם זו,\u0006 ההוצאה עצמה, \u0005גם כן]\u0006 \u0003מלאכה שאינה צריכה לגופה היא,\u0004 שהרי כוונתו לחפירה או לקריאה, \u0003אלא מלאכה שצריכה לגופה לר' שמעון היכי משכחת לה\u0004 \u0005[איך אתה מוצא אותה]\u0006 לענין הוצאה? ומשיבים: בכל זאת יש בכך חידוש, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שר' שמעון מחייב רק באופן מסויים, והוא \u0003עד דאיכא\u0004 \u0005[שיש]\u0006 צורך גם \u0003לגופו\u0004 של המוציא \u0003ו\u0004גם \u0003לגופה\u0004 של ההוצאה, ו\u0003כגון\u0004 שהוציא \u0003מר\u0004 (מעדר) \u0003כדי לעשות לו טס\u0004 (לחדד את להבו) \u0003ו\u0004גם \u0003לחפור\u0004 בו, וב\u0003ספר תורה\u0004 — שהוציאו \u0003כדי להגיה\u0004 אותו \u0003ו\u0004גם \u0003לקרות בו,\u0004 ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שדי בצורך גופו של המוציא כדי לחייבו.","מסופר: \u0003ההוא שכבא דהוה בדרוקרא\u0004 \u0005[מת אחד שהיה בדרוקרת],\u0006 \u0003שרא\u0004 \u0005[\u0006ו\u0005התיר]\u0006 \u0003רב נחמן בר יצחק לאפוקיה\u0004 \u0005[להוציאו]\u0006 בשבת \u0003לכרמלית,\u0004 שמפני סיבה מסוימת לא ניתן להשאירו במקומו, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן אחוה\u0004 \u0005[אחיו]\u0006 של \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבנא לרב נחמן בר יצחק: כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי\u0006 התרת\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון,\u0004 ואולם \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003פטר ר' שמעון\u0004 רק \u0003מחיוב חטאת,\u0004 ואולם \u0003איסורא דרבנן מיהא איכא\u0004 \u0005[איסור מדברי חכמים לפחות ישנו]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן בר יצחק: \u0003האלהים\u0004 (בהדגשה, כקריאה של שבועה), \u0003דעיילת ביה את\u0004 \u0005[\u0006וכי \u0005נכנסת בו\u0006 להבנת הדברים\u0005]?\u0006 שהרי \u0003ואפילו ל\u0004שיטת \u0003ר' יהודה שרי\u0004 \u0005[מותר]\u0006 במקרה זה, \u0003דמי קאמינא\u0004 \u0005[שהאם אמרתי]\u0006 להוציאו \u0003לרשות הרבים?\u0004 והלא \u0003לכרמלית קאמינא\u0004 \u0005[אמרתי],\u0006 וכרמלית כיון שאיסורה רק מדברי חכמים הרי כלל בידינו ש\u0003גדול כבוד הבריות שדוחה את\u0004 מצוות \u0003\"לא תעשה\" שבתורה,\u0004 ובכלל זה גם את \"לא תסור מן הדבר אשר יגידו לך ...\" (דברים יז, יא).","\u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]\u0006 העוסקת בדיני צרעת: \u0003התולש\u0004 שערות לבנות שהן \u0003סימני טומאה, ו\u0004כן אם \u0003הכוה\u0004 (עשה כוויה) את \u0003המחיה\u0004 שבבשר הנגע, ועל ידי כך רצה לטהרו — \u0003עובר ב\"לא תעשה\",\u0004 שנאמר \"השמר בנגע הצרעת\" (דברים כד,ח) לפי הכלל ש\"השמר\" משמעו מצוות \"לא תעשה\". ועל כך \u0003איתמר\u0004 \u0005[נאמר]:\u0006 התולש שערה \u0003אחת משתים\u0004 בלבד — הכל מודים ש\u0003חייב,\u0004 שהרי נשארה רק שערה אחת, ואין הוא טמא בשל שערה בודדת. אבל נחלקו אמוראים בתולש \u0003אחת משלש,\u0004 ש\u0003רב נחמן אמר: חייב,\u0004 ואילו \u0003רב ששת אמר: פטור.\u0004 ומבארים את השיטות: \u0003רב נחמן אמר\u0004 ש\u0003חייב,\u0004 לדעתו משום ש\u0003אהני\u0004 \u0005[הועילו]\u0006 \u0003מעשיו, דאי משתקלא חדא אחריתי\u0004 — \u0003אזלא\u0004 \u0005[הועילו מעשיו שאם תוסר\u0006 שערה \u0005אחת אחרת,\u0006 נוספת \u0005תלך]\u0006 \u0003לה\u0004 ה\u0003טומאה,\u0004 נמצא אם כן שקרב את טהרתו שלא כדין. ו\u0003רב ששת\u0004 ש\u0003אמר\u0004 ש\u0003פטור,\u0004 לדעתו לא הועילו מעשיו ולא כלום, שכן \u0003השתא מיהת\u0004 — \u0003הא איתא\u0004 \u0005[עכשיו לפחות\u0006 — \u0005הרי ישנה]\u0006 \u0003לטומאה\u0004 זו עדיין גם לאחר שהסיר את השיער, וממילא לא הועילו מעשיו כלום שהרי נותר טמא כפי שהיה.","\u0003אמר רב ששת: מנא אמינא לה\u0004 \u0005[מנין אני אומר אותה]\u0006 את דעתי זו — ממה \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנתנו\u0005]:\u0006 \u0003וכן\u0004 המוציא בשבת \u0003כזית מן המת ו\u0004כן \u0003כזית מן הנבילה\u0004 — \u0003חייב,\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי,\u0006 מכאן\u0005]\u0006 שהמוציא \u0003חצי זית\u0004 — \u0003פטור, והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 המוציא \u0003חצי זית\u0004 מן המת — \u0003חייב! מאי לאו\u0004 \u0005[האם אין]\u0006 להסביר כי \u0003הא דתניא\u0004 \u0005[זה ששנינו\u0006 בברייתא\u0005]\u0006 \u0003\"חייב\"\u0004 — מדובר באופן \u0003דאפיק\u0004 \u0005[שהוציא]\u0006 \u0003חצי זית מכזית,\u0004 ובכך עשה מעשה שיש לו ערך, של מניעת טומאה, שחצי זית בלבד אינו מטמא. \u0003והא דתנן\u0004 \u0005[וזה ששנינו\u0006 במשנה\u0005]\u0006 \u0003\"פטור\"\u0004 — מדובר באופן \u0003דאפיק\u0004 \u0005[שהוציא]\u0006 \u0003חצי זית מכזית ומחצה\u0004 והרי עדיין נשארה הטומאה במקומה. \u0003ורב נחמן\u0004 מפרש אחרת: \u0003אידי ואידי\u0004 \u0005[זה וזה],\u0006 גם המוציא חצי כזית מכזית וגם המוציא חצי זית מכזית ומחצה — \u0003חייב, והא דתנן\u0004 \u0005[וזה ששנינו\u0006 במשנה\u0005]\u0006 \u0003\"פטור\",\u0004 מדובר באופן \u0003דאפיק\u0004 \u0005[שהוציא]\u0006 \u0003חצי זית ממת גדול,\u0004 שאף רב נחמן מודה בכגון זה שאין מעשיו מועילים, וכיון שלא הוציא כשיעור הראוי — אין לחייבו.","\u0003הנוטל\u0004 בשבת \u0003צפרניו זו בזו\u0004 ולא במספרים, \u0003או\u0004 שנוטלן \u0003בשיניו, וכן\u0004 הנוטל \u0003שערו\u0004 בידיו, \u0003וכן שפמו, וכן זקנו. וכן הגודלת\u0004 (קולעת את שערה), \u0003וכן הכוחלת\u0004 (שמה כחול סביב עיניה), \u0003וכן הפוקסת\u0004 (מאדימה פניה במשחה אדומה) — \u0003ר' אליעזר מחייב\u0004 בכל אלו כמלאכות האסורות מן התורה, \u0003וחכמים אוסרין משום שבות\u0004 (איסור שבת שמדברי סופרים), שלדעתם אין זו מלאכה ממש אבל אסור לעשות כן כגזירת חכמים.","\u0003אמר ר' אלעזר: מחלוקת\u0004 זו היא דווקא כאשר נוטל את צפרניו \u0003ביד, אבל\u0004 כאשר נוטל אותם \u0003בכלי\u0004 — לדעת הכל \u0003חייב.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שהרי \u0003\"זו בזו\" תנן\u0004 \u0005[שנינו]\u0006 במפורש! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003רבנן\u0004 בנטילתן \u0003בכלי נמי פטרי\u0004 \u0005[גם כן פוטרים],\u0006 שכיון שאין הנוטל צפרניו מעוניין בצפורן החתוכה אין בכך משום מלאכת גזיזה, \u0003והא דקתני\u0004 \u0005[וזה ששנינו]\u0006 בנוסח \u0003\"זו בזו\"\u0004 — \u0003להודיעך כחו\u0004 (תוקף דעתו) של \u0003ר' אליעזר\u0004 שאפילו במקרה זה הוא מחייב, על כן \u0003קא משמע לן\u0004 \u0005[הוא משמיע\u0006 לנו] שאין הדבר כך.","\u0003ואמר ר' אלעזר: מחלוקת\u0004 זו ששנינו הריהי דווקא בשנטל צפרניים \u0003לעצמו, אבל\u0004 בשנטל \u0003לחבירו\u0004 — ל\u0003דברי הכל פטור.\u0004 ושואלים: והרי גם דבר זה הוא \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שהרי בלשון \u0003\"צפרניו\",\u0004 כלומר, שלו, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]!\u0006 ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 ש\u0003ר' אליעזר\u0004 בשנוטל \u0003לחבירו נמי\u0004 \u0005[גם כן]\u0006 \u0003מחייב, והא דקתני\u0004 \u0005[וזה ששנינו]\u0006 לשון \u0003\"צפרניו \"\u0004הרי זה \u0003להודיעך כחן דרבנן\u0004 \u0005[של החכמים]\u0006 שאפילו בצפרניו שלו פטרו, וכל שכן בשל חבירו, על כן \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 ללמדנו שהכל מודים שפטור בכך.","שנינו במשנה: \u0003וכן\u0004 הנוטל \u0003שערו\u0004 שלדעת ר' אליעזר חייב ולדעת חכמים פטור. \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בתוספתא: \u0003הנוטל\u0004 שערו בשבת \u0003מלא פי הזוג\u0004 (המספריים) — \u0003חייב. וכמה\u0004 הוא שיעור \u0003מלא פי הזוג? אמר רב יהודה: שתים,\u0004 שתי שערות. ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו]\u0006 בהמשך אותה ברייתא: \u0003ולקרחה\u0004 כדי להתחייב משום האיסור בתורה שלא לעשות קרחה באבל על המת (\"ולא תשימו קרחה בין עיניכם למת\". דברים יד, א), השיעור הקטן ביותר הוא \u0003שתים,\u0004 ומכאן ש\"מלוא פי הזוג\" הוא שיעור אחר! ומשיבים: \u0003אימא\u0004 \u0005[אמור,\u0006 פרש\u0005]\u0006 שאין כאן שיעורים שונים, אלא: \u0003וכן לקרחה שתים.\u0004","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003הנוטל\u0004 משערו \u0003מלא פי הזוג בשבת\u0004 — \u0003חייב. וכמה\u0004 הוא \u0003מלא פי הזוג\u0004 — \u0003שתים. ר' אליעזר אומר:\u0004 אף בשערה \u0003אחת\u0004 חייב, \u0003ומודים חכמים לר' אליעזר במלקט\u0004 ותולש שערות \u0003לבנות מתוך שחורות, שאפילו\u0004 כאשר ליקט \u0003אחת\u0004 בלבד גם כן \u0003חייב.\u0004 שהרי במעשהו הוא מוכיח כי הוא מקפיד אף בשערה בודדת והוצאתה חשובה בעיניו, \u0003ודבר זה,\u0004 ליקוט שערות לבנות משחורות, \u0003אף ב\u0004ימות \u0003החול אסור\u0004 לגברים, \u0003משום שנאמר: \"\u0004לא יהיה כלי גבר על אשה \u0003ולא ילבש גבר שמלת אשה\"\u0004 (דברים כב, ה), ומכאן למדו חכמים שכל דבר שהוא ממנהגי הייפוי של נשים אסור לגברים.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר: צפורן שפירש רובה\u0004 והיא מחוברת רק בחלקה הקטן באצבע, \u0003ו\u0004כן \u0003ציצין\u0004 (חתיכות קטנות של עור) \u0003שפרשו רובן\u0004 מן הגוף, אם תולשן בשבת \u0003ביד\u0004 — \u0003מותר,\u0004 ואם חותכן \u0003בכלי\u0004 — \u0003חייב חטאת,\u0004 ותוהים על כך: \u0003מי איכא מידי\u0004 \u0005[האם יש דבר,\u0006 מלאכה\u0005]\u0006 שאם עושה אותה \u0003בכלי חייב חטאת, וביד מותר לכתחלה\u0004 לעשותה, ולא גזרו בה חכמים משום סייג?! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבין\u0005]:\u0006 אם \u0003פירשו רובן, ביד\u0004 — \u0003מותר, בכלי,\u0004 אם כבר תלש — \u0003פטור\u0004 ואינו נענש על כך, \u0003אבל\u0004 מלכתחילה ודאי ש\u0003אסור\u0004 לעשות כן. ואם עדיין \u0003לא פירשו רובן, ביד\u0004 — \u0003פטור, אבל אסור,\u0004 ואם עשה כך \u0003בכלי\u0004 — \u0003חייב חטאת. אמר רב יהודה: הלכה כ\u0004שיטת \u0003ר' שמעון בן אלעזר\u0004 בענין זה. \u0003אמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן: והוא שפרשו\u0004 אותם חלקי ציפורן \u0003כלפי מעלה\u0004 אל צד הצפורן \u0003ומצערות אותו,\u0004 ובכגון זה התירו מלכתחילה לתולשן.","שנינו במשנה: \u0003וכן הגודלת\u0004 והכוחלת והפוקסת בשבת שר' אליעזר מחייב בהן מן התורה. ושואלים: ה\u0003גודלת, כוחלת ופוקסת\u0004 בשבת \u0003משום מאי מחייבא\u0004 \u0005[מה,\u0006 איזה אב מלאכה היא \u0005מתחייבת]?\u0006 \u0003אמר ר' אבין\u0004 שכך \u0003אמר ר' יוסי בר' חנינא:\u0004 ה\u0003גודלת\u0004 מתחייבת — \u0003משום אורגת,\u0004 שקליעת השיער דומה במהותה לאריגה, וה\u0003כוחלת\u0004 — \u0003משום כותבת, פוקסת\u0004 — \u0003משום טווה,\u0004 שהיו מורחים את האודם על הפנים בכעין חוט של בצק. \u0003אמרו רבנן קמיה\u0004 \u0005[חכמים לפני]\u0006 \u0003ר' אבהו: וכי דרך אריגה בכך, וכי דרך כתיבה בכך, וכי דרך טויה בכך?!\u0004 ובודאי גם ר' אליעזר מודה שמלאכה שאינה נעשית כדרכה פטורים עליה! \u0003אלא אמר ר' אבהו: לדידי מפרשא לי מיניה\u0004 \u0005[לי נתפרש\u0006 הדבר \u0005ממנו]\u0006 מ\u0003ר' יוסי בר' חנינא\u0004 עצמו"],["\u0003כוחלת\u0004 חייבת — \u0003משום צובעת, גודלת ופוקסת\u0004 — \u0003משום\u0004 מלאכת \u0003בונה,\u0004 ושואלים: \u0003וכי דרך בנין בכך?\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 אף קליעת שיער קרואה בנייה, ו\u0003כ\u0004שם ש\u0003דרש ר' שמעון בן מנסיא:\u0004 מה שנאמר \u0003\"ויבן ה' אלהים את הצלע\u0004 אשר לקח מן האדם לאשה\u0003\"\u0004 (בראשית ב, כב) \u0003מלמד: שקילעה\u0004 (קלע שערותיה) \u0003הקדוש ברוך הוא לחוה והביאה אצל אדם.\u0004 ומנין שזו היא משמעות \"ויבן\"? — \u0003שכן בכרכי הים קורין\u0004 (קוראים) \u0003לקלעיתא\u0004 \u0005[לקליעה]\u0006 \u0003\"בניתא\"\u0004 \u0005[בנייה].\u0006 \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר:\u0004 ה\u0003גודלת\u0004 וה\u0003כוחלת ופוקסת\u0004 בשבת, אם עשתה זאת \u0003לעצמה\u0004 — \u0003פטורה,\u0004 ואם \u0003לחברתה\u0004 — \u0003חייבת,\u0004 שלעצמה אינה יכולה לעשות את המלאכה בשלימות, אבל לחברתה אפשר שתעשה כתיקונה. \u0003וכן היה ר' שמעון בן אלעזר אומר משום\u0004 (בשם) \u0003ר' אליעזר: אשה לא תעביר סרק\u0004 (צבע אדום) \u0003על פניה\u0004 בשבת \u0003מפני שצובעת,\u0004 והיא אחת מן המלאכות האסורות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003החולב והמחבץ\u0004 (המעמיד את החלב) \u0003והמגבן\u0004 (אוסף את הגבינה מן החלב), השיעור להתחייב על עשייתם בשבת — \u0003כגרוגרת. המכבד\u0004 (מטאטא) את הבית, \u0003והמרבץ\u0004 (מתיז) מים על הקרקע, \u0003והרודה חלות דבש,\u0004 בכל אלה אם \u0003שגג בשבת\u0004 — \u0003חייב חטאת,\u0004 ואם \u0003הזיד ביום טוב\u0004 — \u0003לוקה ארבעים\u0004 מלקות\u0003,\u0004 אלו \u0003דברי ר' אליעזר. וחכמים אומרים: אחד זה ואחד זה אינו\u0004 אסור \u0003אלא משום שבות\u0004 (איסור שבת שמדברי סופרים), אבל אינם אסורים מן התורה ואינו מביא קרבן, ואף אינו לוקה עליהם.","מסופר: \u0003רב נחמן בר גוריא איקלע\u0004 \u0005[נזדמן]\u0006 \u0003לנהרדעא. בעו מיניה\u0004 \u0005[שאלו ממנו]\u0006 בני הישיבה: \u0003חולב משום מאי מיחייב\u0004 \u0005[מה\u0006 הוא \u0005מתחייב]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003משום חולב. מחבץ, משום מאי מיחייב\u0004 \u0005[מה\u0006 הוא \u0005מתחייב]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003משום מחבץ. מגבן, משום מאי מיחייב\u0004 \u0005[מה\u0006 הוא \u0005מתחייב]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003משום מגבן. אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003רבך קטיל קני באגמא הוה\u0004 \u0005[קוצץ קנים באגם היה],\u0006 שלא ידע להסביר לתלמידיו פירושה של משנה. \u0003אתא שאיל בי מדרשא\u0004 \u0005[בא\u0006 ו\u0005שאל בבית המדרש]\u0006 שאלות אלה. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003חולב חייב\u0004 — \u0003משום\u0004 מלאכת \u0003מפרק\u0004 שהיא תולדת של מלאכת דש, שמוציא את החלב מתוך הפרה והרי זה דומה לכל מלאכת דש שמוציא את התוכן הרצוי מתוך כיסוי שהיה בו. \u0003מחבץ חייב\u0004 — \u0003משום\u0004 מלאכת \u0003בורר,\u0004 שחלק מן החלב נברר ונעשה חלב קפוי, ו\u0003מגבן חייב\u0004 — \u0003משום\u0004 מלאכת \u0003בונה,\u0004 שהגבינה הנוצרת בתוך החלב נעשית מוצק כעין בניה.","מקודם הובאה ברייתא ששנינו בה: \u0003המכבד, המרבץ, והרודה חלות דבש,\u0004 אם \u0003שגג בשבת\u0004 במלאכות אלה — \u0003חייב חטאת,\u0004 ואם \u0003הזיד ביום טוב\u0004 — \u0003לוקה ארבעים\u0004 מלקות, אלו \u0003דברי ר' אליעזר. אמר ר' אלעזר: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"\u0004וישלח את קצה המטה אשר בידו \u0003ויטבל אותה ביערת הדבש\",\u0004 (שמואל א, יד, כז), והדברים לכאורה תמוהים, שכן \u0003וכי מה ענין יער אצל דבש? אלא לומר לך: מה יער, התולש ממנו בשבת\u0004 — \u0003חייב חטאת, אף חלות דבש, הרודה ממנו בשבת\u0004 — \u0003חייב חטאת.\u0004","מסופר: \u0003אמימר שרא זילחא\u0004 \u0005[התיר ריבוץ מים]\u0006 \u0003ב\u0004עיר \u0003מחוזא. אמר: טעמא מאי אמור רבנן\u0004 \u0005[מה טעם אמרו חכמים]\u0006 שאסור לרבץ — \u0003דילמא אתי לאשויי\u0004 \u0005[שמא יבוא להשוות,\u0006 ליישר\u0005]\u0006 \u0003גומות\u0004 שבקרקע הבית שאינה מרוצפת באבנים, \u0003הכא ליכא\u0004 \u0005[כאן\u0006 בעיר מחוזא \u0005אין]\u0006 \u0003גומות,\u0004 שכל הבתים בה היו מרוצפים באבן. ומסופר עוד: \u0003רבא תוספאה\u0004 \u0005[בעל התוספתא]\u0006 \u0003אשכחיה\u0004 \u0005[מצאו]\u0006 את \u0003רבינא\u0004 בשבת \u0003דקא\u0004 \u0005[שהוא]\u0006 \u0003מצטער,\u0004 סובל, \u0003מהבלא\u0004 \u0005[מן ההבל,\u0006 החום והאבק שבבית\u0005],\u0006 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003מר קשישא בריה\u0004 \u0005[הזקן בנו]\u0006 של \u0003רבא אשכחיה\u0004 \u0005[מצאו]\u0006 \u0003לרב אשי\u0004 וראה \u0003דקא\u0004 \u0005[שהוא]\u0006 \u0003מצטער מהבלא\u0004 \u0005[מן ההבל],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 מר קשישא לרב אשי: וכי \u0003לא סבר לה מר להא דתניא\u0004 \u0005[אין אדוני מקבל את\u0006 הלכה \u0005זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרוצה לרבץ את ביתו בשבת\u0004 במקום שאסור הדבר, \u0003מביא עריבה\u0004 (קערה גדולה) \u0003מלאה מים ורוחץ פניו בזוית זו\u0004 ומזיז את העריבה ורוחץ \u0003ידיו בזוית זו, רגליו בזוית זו, ונמצא הבית מתרבץ מאליו\u0004 מן המים שניתזו כלאחר ידו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003לאו אדעתאי\u0004 \u0005[לא עלה על דעתי]\u0006 להשתמש בעצה זו.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003אשה חכמה מרבצת\u0004 את \u0003ביתה בשבת,\u0004 שרוחצת כלים שונים במקומות שונים בבית. \u0003והאידנא דסבירא לן\u0004 \u0005[ועכשיו שאנו סבורים]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון\u0004 שמלאכה שאינה צריכה לגופה פטור עליה בשבת, \u0003שרי\u0004 \u0005[מותר]\u0006 לכבד ולרבץ את הבית בשבת \u0003אפילו לכתחלה.\u0004","\u0003התולש\u0004 בשבת \u0003מ\u0004צמח הגדל ב\u0003עציץ נקוב\u0004 — \u0003חייב,\u0004 שעציץ נקוב נחשב כמחובר בארץ, והרי זה כקוצר. \u0003ו\u0004התולש מ\u0003שאינו נקוב\u0004 — \u0003פטור,\u0004 אבל אסור הדבר מלכתחילה. \u0003ור' שמעון פוטר בזה ובזה.\u0004","\u0003רמי ליה\u0004 \u0005[השליך\u0006 הראה \u0005לו\u0006 סתירה\u0005]\u0006 \u0003אביי לרבא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהקשה לו \u0003ר' חייא בר רב לרב:\u0004 מצד אחד \u0003תנן\u0004 \u0005[שנינו]\u0006 במשנתנו \u0003ר' שמעון פוטר בזה ובזה. אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003נקוב ל\u0004דעת \u0003ר' שמעון כ\u0004זה \u0003שאינו נקוב משוי ליה\u0004 \u0005[עושה,\u0006 מחשיב \u0005אותו].\u0006 \u0003ורמינהו\u0004 \u0005[משליכים\u0006 על כך, מראים סתירה\u0005]\u0006 \u0003ר' שמעון אומר: אין בין\u0004 עציץ \u0003נקוב לשאינו נקוב\u0004"],["\u0003אלא להכשיר זרעים בלבד,\u0004 שזרעים שבעציץ נקוב נחשבים כמחוברים לקרקע, ואינם מקבלים טומאה, וזרעים שבעציץ שאינו נקוב נחשבים כתלושים ומקבלים טומאה, ומכאן אפשר ללמוד שלגבי שאר כל הדברים סבור ר' שמעון שעציץ נקוב הוא כמחובר (מאירי)! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לכל מילי\u0004 \u0005[דבר]\u0006 \u0003ר' שמעון\u0004 עציץ נקוב \u0003כתלוש משוי ליה\u0004 \u0005[עושה אותו],\u0006 \u0003ושאני\u0004 \u0005[ו\u0006אולם \u0005שונה]\u0006 \u0003לענין טומאה,\u0004 ש\u0003התורה ריבתה טהרה אצל זרעים,\u0004 וכפי \u0003שנאמר\u0004 \"וכי יפול מנבלתם \u0003על כל זרע זרוע אשר יזרע\u0004 טהור הוא\" (ויקרא יא, לז), שריבוי הלשון \"זרע זרוע אשר יזרע\" בא ללמדנו שכל שאפשר לומר בו לשון \"זריעה\", נכנס לגדר טהרה. אבל בשאר דברים אין דין עציץ נקוב שונה מעציץ שאינו נקוב.","\u0003בעא מיניה ההוא סבא\u0004 \u0005[שאל ממנו זקן אחד]\u0006 \u0003מר' זירא:\u0004 כאשר \u0003שורש\u0004 צמח שבתוך עציץ נקוב נמצא ממש \u0003כנגד\u0004 ה\u0003נקב מה לי אמר\u0004 (מה יאמר בענין זה) \u0003ר' שמעון\u0004 הפוטר אף בעציץ נקוב? האם לדעתו ייחשב הדבר כמחובר או לא? \u0003אישתיק\u0004 \u0005[שתק]\u0006 \u0003ולא אמר ליה\u0004 \u0005[לו]\u0006 \u0003ולא מידי\u0004 \u0005[דבר,\u0006 כלום\u0005].\u0006 ומסופר כי \u0003זימנא חדא אשכחיה דיתיב וקאמר\u0004 \u0005[פעם אחת מצאו\u0006 אותו זקן לר' זירא \u0005שיושב ואומר]:\u0006 \u0003ומודה ר' שמעון שאם ניקב\u0004 העציץ נקב גדול \u0003בכדי טהרתו,\u0004 ששוב אינו מקבל זיתים, הריהו כמחובר לענין שבת. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי כאשר ה\u0003שורש\u0004 נמצא \u0003כנגד\u0004 ה\u0003נקב בעאי מינך\u0004 \u0005[שאלתי ממך]\u0006 מה הלכה יפסוק בו ר' שמעון, \u0003ולא אמרת לי ולא מידי\u0004 \u0005[דבר],\u0006 ואם כן ב\u0003ניקב בכדי טהרתו\u0004 שאין השורש ממש כנגד הנקב \u0003מיבעיא\u0004 \u0005[צריך לומר]\u0006 שהוא כתלוש?! וכיצד נפתרת שאלה זו בכך בפשטות? אלא יש כאן בודאי מקום להבין את הדברים בצורה אחרת.","\u0003אמר אביי: ואי איתמר להא\u0004 \u0005[ואם נאמר\u0006 דבר \u0005זה]\u0006 בשם \u0003ר' זירא\u0004 שמחשיב ר' שמעון עציץ נקוב כמחובר, \u0003הכי\u0004 \u0005[כך]\u0006 \u0003הוא דאיתמר\u0004 \u0005[שנאמר]:\u0006 \u0003ומודה ר' שמעון שאם ניקב למטה מרביעית,\u0004 שבעציץ זה אין אפילו כשיעור רביעית בלי נקב, שוב אינו כלי וחייב.","כיוון שהוזכרה טהרת כלי חרס, הביאו את מה ש\u0003אמר רבא: חמש מדות\u0004 נאמרו \u0003ב\u0004נקבי \u0003כלי חרס :\u0004 אם \u0003ניקב\u0004 בו נקב קטן \u0003כמוציא משקה\u0004 — \u0003טהור\u0004 (כלומר, בטל) \u0003מלטמא גיסטרא,\u0004 שאם נשאר רק שבר כלי והוא נקוב, אפילו נקב זעיר כזה שהמשקה יוצא ממנו — שוב אינו מטמא, \u0003ו\u0004אולם \u0003עדיין כלי\u0004 שלם \u0003הוא לקדש בו מי חטאת\u0004 (פרה אדומה) הצריכים כלי שלם. ואם \u0003ניקב\u0004 בחור גדול יותר \u0003ככונס משקה,\u0004 שיכולים מים אף להיכנס לכלי דרך נקב זה — \u0003טהור מלקדש בו מי חטאת, ו\u0004אולם \u0003עדיין כלי הוא להכשיר בו זרעים.\u0004 ואם \u0003ניקב כ\u0004עובי \u0003שורש קטן\u0004 — \u0003טהור מלהכשיר בו זרעים, ו\u0004אולם \u0003עדיין כלי הוא\u0004 לענין שמקבל טומאה כיון שאפשר \u0003לקבל בו זיתים.\u0004 ואם \u0003ניקב כמוציא זיתים\u0004 — \u0003טהור מלקבל\u0004 טומאה ככל כלי הראוי לקבל \u0003בו זיתים, ו\u0004אולם \u0003עדיין כלי הוא לקבל בו רימונים,\u0004 שאם החליט שהוא מייחד את כלי החרס לרימונים — מקבל הכלי עדיין טומאה כיון שראוי לשימוש. \u0003ניקב כמוציא רימונים\u0004 — \u0003טהור מכלום. ואם\u0004 היה זה כלי חרס ש\u0003הוקף\u0004 ב\u0003צמיד פתיל\u0004 והיה מונח באוהל המת, ואמרה תורה שכל כלי חרס מכוסה ומוקף בצמיד פתיל אינו מקבל טומאה באוהל המת, אפילו היה נקוב כמוציא רימון — מציל את המצוי בתוכו מלהיטמא \u0003עד שיפחת\u0004 (ישבר) \u0003רובו.\u0004","\u0003אמר רב אסי: שמעתי\u0004 ש\u0003כלי חרס שיעורו\u0004 כדי להיטהר \u0003כמוציא רימון. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: שמא לא שמעת אלא במוקף צמיד פתיל,\u0004 אבל סתם כלי חרס, שיעור טהרתו כמוציא זית. ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבא\u0004 עצמו \u0003הוא\u0004 ש\u0003אמר\u0004 ש\u0003מוקף צמיד פתיל\u0004 אינו מקבל טומאה \u0003עד שיפחת רובו!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006"],["\u0003הא\u0004 \u0005[זה]\u0006 ששנינו ששיעור הכלי כדי להיטהר הרי זה במוציא רימון — הרי זה \u0003ברברבי\u0004 \u0005[ב\u0006כלים \u0005גדולים],\u0006 \u0003והא\u0004 \u0005[וזה]\u0006 ששנינו שיעורם כדי שייפחתו ברובם — הרי זה \u0003בזוטרי\u0004 \u0005[ב\u0006כלים \u0005קטנים].\u0006 \u0003אמר רב אסי, שונין\u0004 הלכה זו: \u0003כלי חרס שיעורו\u0004 להיטהר מטומאה \u0003ב\u0004נקב ה\u0003כונס משקה. ולא אמרו\u0004 שיעור \u0003מוציא משקה אלא לענין\u0004 טהרת \u0003גיסטרא בלבד.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? ומשיבים: \u0003אמר מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן: לפי\u0004 ששימוש בגיסטרא הוא לשים אותה כעין צלחת מתחת לכלי חרס נקוב, הרי אם גיסטרא אחת ניקבה ומטפטפת אין עושים בה עוד שימוש, ו\u0003אין אומרים \"הבא גיסטרא לגיסטרא\",\u0004 אלא זורקים אותה מיד.","\u0003אמר עולא: פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה\u0004 בהלכה זו \u0003תרי אמוראי במערבא\u0004 \u0005[שני אמוראים במערב,\u0006 בארץ ישראל\u0005],\u0006 \u0003ר' יוסי בר' אבין ור' יוסי בר זבדא. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שטהרת כלי חרס בנקב ששיעורו \u0003כמוציא רמון, וחד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: כשורש קטן. וסימניך\u0004 (וסימן יהא לך בדבר זה) שתזכור שלא נחלקו בנקב כמוציא זית, על פי האימרה \u0003אחד המרבה ואחד הממעיט,\u0004 שהמחלוקת היא קיצונית בין חכם לחכם, ולא הזכירו דעה ממוצעת. ואכן, \u0003אמר רב חיננא בר כהנא משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' אליעזר\u0004 דיעה ממוצעת: \u0003כלי חרס שיעורו\u0004 כדי להיטהר הוא \u0003כמוציא זיתים. ומר קשישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה מסיים בה\u0004 הלכה זו \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' אליעזר: והרי הן,\u0004 אותם כלים שניקבו, \u0003ככלי גללים וכלי אבנים וכלי אדמה\u0004 — \u0003שאין\u0004 הם \u0003מקבלין טומאה לא מדברי תורה ולא מדברי סופרים. ולענין\u0004 טהרה באוהל המת של כלי שיש עליו \u0003צמיד פתיל,\u0004 אין כלי חרס בטל \u0003עד שיפחת רובו.\u0004","","\u0003הזורק\u0004 חפץ בשבת \u0003מרשות היחיד לרשות הרבים\u0004 או \u0003מרשות הרבים לרשות היחיד\u0004 — \u0003חייב.\u0004 ואילו הזורק \u0003מרשות היחיד לרשות היחיד ו\u0004עבר החפץ את \u0003רשות הרבים\u0004 ש\u0003באמצע\u0004 — \u0003ר' עקיבא מחייב\u0004 משום הוצאה לרשות הרבים, \u0003וחכמים פוטרין.\u0004","\u0003כיצד? שתי גזוזטראות\u0004 (שהן רשות היחיד) המצויות \u0003זו כנגד זו ב\u0004שני עברי \u0003רשות הרבים, המושיט והזורק מזו לזו\u0004 — \u0003פטור,\u0004 אבל אם \u0003היו\u0004 הגזוזטראות \u0003שתיהן בדיוטא\u0004 (קומה) \u0003אחת\u0004 ובאותו צד של דרך הרבים והיתה בין גזוזטרה לגזוזטרה רשות הרבים, \u0003המושיט\u0004 מזו לזו — \u0003חייב, והזורק\u0004 — \u0003פטור,\u0004 וטעמו של דבר: \u0003שכך היתה עבודת הלויים\u0004 בנשיאת קרשי המשכן:","\u0003שתי עגלות\u0004 היו עומדות \u0003זו אחר זו ברשות הרבים,\u0004 והיו הלווים \u0003מושיטין הקרשים מזו לזו\u0004 והרי זה ממש כמעביר מדיוטא לדיוטא דרך רשות הרבים ובאותו צד של רשות הרבים, \u0003אבל לא\u0004 היו \u0003זורקין\u0004 מעגלה לעגלה מפני כובד הקרשים, נמצא שהושטה שדוגמתה היתה במשכן נאסרה, וזריקה שלא מצאנו לה דוגמה במשכן — לא נאסרה."],["על עיקר הדבר שואלים: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003זריקה תולדה\u0004 של \u0003הוצאה היא, הוצאה\u0004 שהיא אב המלאכה \u0003גופה היכא כתיבא\u0004 \u0005[עצמה היכן כתובה\u0006 בתורה\u0005],\u0006 והלא צריך לברר תחילה את אב המלאכה, ואחר כך לדון בתולדות. \u0003אמר ר' יוחנן:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ויצו משה ויעבירו קול במחנה\u0004 לאמר איש ואשה אל יעשו עוד מלאכה לתרומת הקודש ויכלא העם מהביא\u0003\"\u0004 (שמות לו, ו), שלדעת ר' יוחנן היה ציווי זה של משה מיועד למנוע את העם מלהביא את התרומות בשבת. והוא מפרש: \u0003משה היכן הוה יתיב\u0004 \u0005[היה יושב]?\u0006 — \u0003במחנה לויה\u0004 (הלויים), \u0003ומחנה לויה רשות הרבים הואי\u0004 \u0005[היה],\u0006 \u0003וקאמר להו\u0004 \u0005[ואמר להם]\u0006 \u0003לישראל: לא תפיקו ותיתו\u0004 \u0005[תוציאו ותביאו]\u0006 \u0003מרשות היחיד דידכו\u0004 \u0005[שלכם]\u0006 \u0003לרשות הרבים.\u0004","ושואלים: \u0003וממאי\u0004 \u0005[וממה,\u0006 מניין\u0005]\u0006 אתה למד ש\u0003בשבת קאי\u0004 \u0005[\u0006היה \u0005עומד]\u0006 ומצווה אותם שיפסיקו להביא? \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003בחול קאי\u0004 \u0005[\u0006היה \u0005עומד]\u0006 \u0003ומשום דשלימא\u0004 \u0005[שנשלמה]\u0006 \u0003לה\u0004 ה\u0003מלאכה,\u0004 מלאכת המשכן משום שכבר תרמו די הצורך?! \u0003כדכתיב\u0004 \u0005[\u0006ו\u0005כפי שנאמר]:\u0006 \u0003\"והמלאכה היתה דים\u0004 לכל המלאכה לעשות אותה והותר\" (שמות לו, פסוק ז). אלא \u0003גמר\u0004 \u0005[למד]\u0006 בדרך גזירה \u0003שווה מהלשון \"העברה\" \"העברה\"\u0004 שנאמרה בענין זה וב\u0003יום הכפורים,\u0004","שכן \u0003כתיב הכא\u0004 \u0005[נאמר כאן\u0006 במשכן\u0005]:\u0006 \u0003\"ויעבירו קול במחנה\" וכתיב התם\u0004 \u0005[ונאמר שם\u0006 ביום הכיפורים\u0005]:\u0006 \u0003\"והעברת שופר תרועה\u0004 בחודש השביעי בעשור לחודש ביום הכפורים תעבירו שופר בכל ארצכם\u0003\"\u0004 (ויקרא כה, ט). \u0003מה להלן\u0004 בתקיעת השופר שביובל העברה זו — \u0003ביום אסור\u0004 לעשותה, \u0003אף כאן\u0004 — \u0003ביום אסור.\u0004","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 לימוד לענין \u0003הוצאה\u0004 מרשות היחיד אל מחנה הלווים שהוא רשות הרבים, ואולם \u0003הכנסה מנלן\u0004 \u0005[מניין לנו],\u0006 שאף היא נחשבת כמלאכה, ואסורה? ומשיבים: \u0003סברא היא, מכדי\u0004 \u0005[הרי]\u0006 העברה \u0003מרשות לרשות הוא,\u0004 ואם כן \u0003מה לי אפוקי\u0004 \u0005[הוצאה]\u0006 \u0003ומה לי עיולי\u0004 \u0005[הכנסה],\u0006 שאם העברת חפץ מרשות לרשות יש בה משום מלאכה — אין מקום להבדיל בין הוצאה והכנסה. \u0003מיהו\u0004 \u0005[אבל]\u0006 \u0003הוצאה\u0004 — \u0003אב\u0004 מלאכה היא, ואילו \u0003הכנסה\u0004 — אינה אלא \u0003תולדה,\u0004 כיון שאינה מפורשת במקרא.","על עצם ההבדל בין אב ותולדה שואלים: \u0003ומכדי אהא מיחייב, ואהא מיחייב\u0004 \u0005[הרי על זו מתחייב, ועל זו מתחייב]\u0006 ואם כן \u0003אמאי קרי\u0004 \u0005[מדוע קורא]\u0006 \u0003לה האי\u0004 \u0005[לזו]\u0006 \u0003\"אב\" ואמאי קרי\u0004 \u0005[ומדוע קורא]\u0006 \u0003לה האי\u0004 \u0005[לזו]\u0006 \u0003\"תולדה\"?\u0004 ומה טעם להבחין ביניהם?","ומשיבים: \u0003נפקא מינה דאי עביד\u0004 \u0005[יוצא מזו\u0006 הבדל למעשה \u0005שאם עושה]\u0006 \u0003שתי אבות\u0004 מלאכה שונים \u0003בהדי הדדי\u0004 \u0005[ביחד],\u0006 \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003שתי תולדות\u0004 של שני אבות \u0003שונים בהדי הדדי\u0004 \u0005[ביחד]\u0006 — \u0003מיחייב תרתי\u0004 \u0005[מתחייב שתי\u0006 חטאות\u0005],\u0006 \u0003ואי עביד\u0004 \u0005[ואם עושה]\u0006 \u0003אב ותולדה דידיה\u0004 \u0005[שלו]\u0006 — הוא \u0003לא מיחייב\u0004 \u0005[מתחייב]\u0006 \u0003אלא חדא\u0004 \u0005[\u0006חטאת \u0005אחת].\u0006","ושואלים עוד: \u0003ול\u0004שיטת \u0003ר' אליעזר\u0004 ה\u0003מחייב\u0004 להביא חטאת נפרדת על \u0003תולדה\u0004 של מלאכה גם אם עשה \u0003במקום\u0004 (באותו זמן) \u0003אב\u0004 המלאכה שלו עצמו ומתחייב עליו — לשיטתו \u0003אמאי קרו\u0004 \u0005[מדוע קוראים]\u0006 \u0003לה\u0004 לזו \u0003\"אב\" ואמאי קרו\u0004 \u0005[ומדוע קוראים]\u0006 \u0003לה\u0004 לזו \u0003\"תולדה \"?\u0004 ומשיבים: לשיטתו \u0003הך דהואי\u0004 \u0005[זו שהיתה]\u0006 \u0003במשכן חשיבא\u0004 \u0005[\u0006מלאכה \u0005חשובה]\u0006 — \u0003קרי\u0004 \u0005[קורא]\u0006 \u0003לה \"אב\",\u0004 ואולם \u0003הך\u0004 \u0005[\u0006ל\u0005זו]\u0006 ש\u0003לא הואי\u0004 \u0005[היתה]\u0006 \u0003במשכן חשיבא\u0004 \u0005[חשובה]\u0006 — הוא \u0003לא קרי\u0004 \u0005[קורא]\u0006 \u0003לה \"אב\". אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לומר: כי \u0003הך דכתיבא\u0004 \u0005[\u0006ל\u0005זו שכתובה]\u0006 במפורש במקרא — \u0003קרי\u0004 \u0005[\u0006הוא \u0005קורא]\u0006 \u0003\"אב\", והאי\u0004 \u0005[ו\u0006ל\u0005זו]\u0006 ש\u0003לא כתיבא\u0004 \u0005[כתובה]\u0006 במפורש במקרא — \u0003קרי\u0004 \u0005[\u0006הוא \u0005קורא]\u0006 \u0003\"תולדה\".\u0004","\u0003והא דתנן\u0004 \u0005[ו\u0006הלכה \u0005זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003הזורק\u0004 חפץ בשבת למרחק \u0003ארבע אמות\u0004 ברשות הרבים ונח החפץ \u0003בכותל,\u0004 אם היה גובהו \u0003למעלה מעשרה טפחים\u0004 — הרי זה \u0003כזורק באויר\u0004 ופטור. ואם היה גובהו \u0003למטה מעשרה טפחים\u0004 — הרי זה \u0003כזורק בארץ, והזורק בארץ\u0004 ברשות הרבים \u0003ארבע אמות\u0004 — \u0003חייב.\u0004","ושואלים: \u0003זרק ארבע אמות ברשות הרבים\u0004 עצמה שלא הוציא ולא הכניס מרשות לרשות, \u0003מנלן דמיחייב\u0004 \u0005[מניין לנו שחייב]?\u0006 ומשיבים, \u0003אמר ר' יאשיה: שכן אורגי\u0004 ה\u0003יריעות\u0004 שבמשכן היו \u0003זורקין מחטיהן זה לזה\u0004 כשנזקק אחד למחט שביד חבירו, וכיון שהיתה זו מלאכה במשכן חייבים עליה. ותוהים: \u0003אורגין, מחטין למה להו\u0004 \u0005[להם]?\u0006 לשם מה דרושה המחט במלאכת \u0003האריגה? אלא\u0004 יש לתקן ולומר כך: \u0003שכן תופרי\u0004 ה\u0003יריעות זורקין מחטיהן זה לזה.\u0004","ושואלים: ומניין שהיו צריכים לזרוק זה לזה \u0003ודילמא גבי הדדי הוו יתבי\u0004 \u0005[שמא זה אצל,\u0006 ליד, \u0005זה היו יושבים]?!\u0006 ומשיבים: ודאי הוצרכו להיות מרוחקים זה מזה, שכן אם היו סמוכים מידי אחד \u0003לשני מטו הדדי\u0004 \u0005[היו מגיעים זה לזה]\u0006 ופוגעים זה את זה \u0003במחטין.\u0004 ושואלים עוד: \u0003דילמא\u0004 \u0005[שמא]\u0006 אף שהיו צריכים להיות מרוחקים זה מזה עדיין \u0003בתוך ארבע\u0004 אמות זה לזה \u0003הוו יתבי\u0004 \u0005[היו יושבים],\u0006 ולא נצרכו לזרוק יותר מתחום זה? וכיון שאין בידינו הוכחה איננו יכולים ללמוד הלכה זו מתופרי יריעות.","\u0003אלא אמר רב חסדא:\u0004 איסור זריקת חפץ ארבע אמות ברשות הרבים נלמד \u0003שכן אורגי\u0004 ה\u0003יריעות\u0004 שבמשכן היו \u0003זורקין בוכיאר\u0004 (הכלי שחוט הערב קשור בו) \u0003ביריעה,\u0004 שלצורך האריגה היה צורך לזרוק אותו בין חוטי השתי. ושואלים: הרי זו אינה זריקה ממש, \u0003והלא אוגדו בידו,\u0004 שהרי קצה החוט נמצא עדיין ביד הזורק, וכל זריקה מעין זו שלא זרק את כל החפץ שבידו — אינה נחשבת! אלא יש לומר שהמדובר \u0003בניסכא בתרא\u0004 \u0005[בזריקה האחרונה]\u0006 שבה נשלם חוט האריגה, ושוב אינו צריך להחזיק בידו את החוט.","ועדיין שואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003במקום פטור קאזלא\u0004 \u0005[היא,\u0006 הבוכיאר \u0005הולכת],\u0006 שהרי בין היריעות אין מקום ארבע אמות והזורק למקום פטור — פטור! \u0003אלא\u0004 יש לומר שהלימוד הוא, \u0003שכן אורגי\u0004 ה\u0003יריעות\u0004 היו \u0003זורקין בוכיאר לשואליהן,\u0004 לחבריהם השואלים מהם בוכיאר. ושואלים: \u0003ודילמא גבי הדדי הוו יתבי\u0004 \u0005[ושמא זה ליד זה היו יושבים]?!\u0006 ומתרצים: הדבר אינו אפשרי, כי \u0003מטו הדדי בחפת\u0004 \u0005[היו מגיעים זה ליד זה\u0006 ומפריעים כשהיו מגיעים \u0005לסיומה של היריעה].\u0006","ושואלים: \u0003ודילמא שלחופי הוו משלחפי\u0004 \u0005[ושמא היו מוסטים]\u0006 במקצת זה מזה ולא ישבו בשורה אחת, ועדיין היו יכולים לשבת סמוכים זה לזה בלא להפריע במלאכה?! \u0003ותו, מי שאילי מהדדי\u0004 \u0005[ועוד, האם היו שואלים זה מזה]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 החכם \u0003לודא:\u0004 מה שנאמר \u0003\"\u0004ויבואו כל החכמים העושים את כל מלאכת הקודש \u0003איש איש ממלאכתו אשר המה עשים\"\u0004 (שמות לו, ד) — יש ללמוד מכאן: כל אחד מהם \u0003ממלאכתו הוא עושה ואינו עושה ממלאכת חבירו,\u0004 שלכל אחד היו חמרים וכלי עבודה במידה מספקת, ולא היה אם כן צורך בשאילה אחד מהשני!","\u0003ותו\u0004 \u0005[ועוד]\u0006 יש להקשות: \u0003אף\u0004 אם נלמד מכאן דין זורק, אבל \u0003מעביר\u0004 בידו \u0003ארבע אמות ברשות הרבים מנלן דמחייב\u0004 \u0005[מניין לנו שחייב]?\u0006 אלא נראה שאין בידינו ללמוד הלכה זו במישרין ממלאכת המשכן \u0003אלא\u0004 יש לומר: \u0003כל\u0004 ההלכות הקשורות בהעברת \u0003ארבע אמות ברשות הרבים גמרא גמירי לה\u0004 \u0005[בלימוד של מסורת למדו אותה]\u0006 ולא ממדרש הכתובים.","\u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: מקושש\u0004 שכתוב בתורה שדנו אותו למיתה על חילול שבת (במדבר טו, לג–לו), \u0003מעביר ארבע אמות ברשות הרבים הוה\u0004 \u0005[היה],\u0006 ומשום עבירה זו הוא שנסקל. \u0003במתניתא תנא\u0004 \u0005[בברייתא שנה\u0006 החכם\u0005]:\u0006 \u0003תולש הוה\u0004 \u0005[היה],\u0006 שמשום תלישת העצים ממקומם התחייב. \u0003רב אחא בר' יעקב אמר: מעמר\u0004 (אוסף עצים ממקום הנחתם לערימה) \u0003הוה\u0004 \u0005[היה].\u0006","ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 להלכה אם נדע מה היתה המלאכה שנתחייב עליה המקושש בשעתו? ומשיבים: יש כאן תוצאה מעשית על פי הדברים שמסר \u0003רב.\u0004 ש\u0003אמר רב: מצאתי מגלת סתרים בי\u0004 (בבית) \u0003ר' חייא וכתוב\u0004 בה, \u0003איסי בן יהודה אומר:\u0004 מספר \u0003אבות\u0004 ה\u0003מלאכות\u0004 האסורות בשבת הוא \u0003ארבעים חסר אחת (ואם עשאן כולם בהעלם אחת) ואינו חייב אלא אחת.\u0004 ומיד תוהים: \u0003אחת ותו לא\u0004 \u0005[ולא עוד]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אבות מלאכות ארבעים חסר אחת, והוינן\u0004 \u0005[והיינו מתעסקים]\u0006 \u0003בה: מניינא\u0004 \u0005[המספר]\u0006 \u0003למה לי?\u0004 והלא די במניית אבות המלאכה בלא לציין את מספרם! \u0003ואמר ר' יוחנן:\u0004 משנה זו באה ללמדנו \u0003שאם עשאן כולם בהעלם אחד\u0004 — \u0003חייב על כל אחת ואחת.\u0004 הרי שאין לפרש שעל כל המלאכות כולן חייב רק חטאת אחת!","אלא \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 \u0003אינו חייב על אחת\u0004 מהן, שיש מלאכה אחת משלושים ותשע המלאכות שעליה אין חייבים מיתה, ויש בה מצות \"לא תעשה בלבד\" ולא נתפרש איזו היא.","ולענין זה, \u0003רב יהודה פשיטא ליה\u0004 \u0005[פשוט לו]\u0006 ש\u0003המעביר חייב, ומתניתא פשיטא ליה\u0004 \u0005[וה\u0006חכם ב\u0005ברייתא פשוט לו]\u0006 שה\u0003תולש חייב, ורב אחא בר יעקב פשיטא ליה\u0004 \u0005[פשוט לו]\u0006 שה\u0003מעמר חייב.\u0004 כלומר, \u0003מר סבר הא מיהת לא מספקא, ומר סבר הא מיהת לא מספקא\u0004 \u0005[חכם זה סבור\u0006 כי \u0005זו לפחות אינה מסופקת, וחכם זה סבור\u0006 כי \u0005זו לפחות אינה מסופקת],\u0006 ובאו להודיענו שעל מלאכות אלה ודאי חייבים מיתה, שהרי נידון מקושש העצים משום שעבר עליהן.","כיון שהוזכר המקושש לענין מלאכתו מביאים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003מקושש זה\u0004 שמזכירתו התורה \u0003צלפחד\u0004 היה, \u0003וכן הוא אומר: \"ויהיו בני ישראל במדבר וימצאו איש\u0004 מקושש עצים ביום השבת\u0003\"\u0004 (במדבר טו, לב), \u0003ולהלן הוא אומר\u0004 בדברי בנות צלפחד: \u0003\"אבינו מת במדבר\u0004 והוא לא היה בתוך העדה הנועדים על ה' בעדת קורח כי בחטאו מת ובנים לא היו לו\u0003\"\u0004 (במדבר כז, ג), \u0003מה להלן\u0004 האיש במדבר הוא \u0003צלפחד, אף כאן\u0004 שלא פורש שמו הוא \u0003צלפחד,\u0004 אלו \u0003דברי ר' עקיבא.\u0004","\u0003אמר לו ר' יהודה בן בתירא: עקיבא, בין כך ובין כך אתה עתיד ליתן את הדין\u0004 על מדרש זה, שכן \u0003אם כדבריך\u0004 שהיה זה צלפחד — \u0003התורה כיסתו,\u0004 ולא פרסמה את שם המקושש, \u0003ואתה מגלה אותו?! ואם לאו\u0004 \u0005[לא],\u0006 שלא היה זה צלפחד — הרי \u0003אתה\u0004 ללא הצדקה \u0003מוציא לעז על אותו צדיק.\u0004"],["\u0003ואלא הא גמר\u0004 \u0005[הרי למד]\u0006 ר' עקיבא דבר זה ב\u0003גזירה שוה!\u0004 ומשיבים: \u0003גזירה שוה לא גמר\u0004 \u0005[למד],\u0006 כלומר, ר' יהודה בן בתירא לא קיבל מרבותיו גזירה שווה זו. ולכן לא קיבל את מסקנת ר' עקיבא. ושואלים: ו\u0003אלא\u0004 לשיטת ר' יהודה בן בתירא \u0003מהיכא הוה\u0004 \u0005[מהיכן היה]\u0006 כלומר, בשל איזה חטא מת? ומשיבים: צלפחד היה \u0003מ\u0004אלה שנאמר בהם \u0003\"ויעפלו\u0004 לעלות אל ראש ההר וארון ברית ה' ומשה לא משו מקרב המחנה\u0003\"\u0004 (במדבר יד, מד).","\u0003כיוצא בדבר\u0004 דרש ר' עקיבא וגילה דבר שלא פורש בתורה, שכן \u0003אתה אומר\u0004 כאשר דברו אהרן ומרים במשה: \u0003\"ויחר אף ה' בם וילך\u0004 והענן סר מעל האוהל והנה מרים מצורעת כשלג. ויפן אהרן אל מרים והנה מצורעת\u0003\"\u0004 (במדבר יב, ט–י), ומהמלים \"ויחר אף ה' בם\", שמשמעו — בשניהם, \u0003מלמד\u0004 הכתוב \u0003שאף אהרן נצטרע,\u0004 אלו \u0003דברי ר' עקיבא. אמר לו ר' יהודה בן בתירא: עקיבא, בין כך ובין כך אתה עתיד ליתן את הדין.\u0004 שכן \u0003אם כדבריך\u0004 — \u0003התורה כסתו\u0004 לאהרן בענין העונש \u0003ואתה מגלה אותו?! ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אתה מוציא לעז על אותו צדיק.\u0004","ושואלים: \u0003ואלא הכתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"בם\"\u0004 בלשון רבים, ומשמע — בשניהם! ומשיבים: הלשון \u0003ההוא\u0004 בא ללמדנו רק שחרה אף ה' באהרן \u0003בנזיפה בעלמא\u0004 \u0005[בלבד].\u0006 \u0003תניא כמאן דאמר\u0004 \u0005[שנויה\u0006 ברייתא \u0005כ\u0006דעת \u0005מי שאומר,\u0006 ר' עקיבא\u0005]\u0006 ש\u0003אף אהרן נצטרע. דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויפן אהרן אל מרים והנה מצרעת\"\u0004 (במדבר יב, ט-י), ועל כך \u0003תנא\u0004 \u0005[שנה]\u0006 החכם: כתוב \u0003זה מלמד שפנה מצרעתו,\u0004 כלומר, התרפא מצרעתו, משמע שאף הוא היה מצורע קודם לכן.","וכיון שהוזכרה צרעת מרים מביאים את מה ש\u0003אמר ריש לקיש: החושד בכשרים\u0004 — \u0003לוקה בגופו, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \"ויען משה ויאמר \u0003והן לא יאמינו לי\u0004 ולא ישמעו בקולי כי יאמרו לא נראה אליך ה'\" (שמות ד, א) \u0003וגליא קמי קודשא בריך הוא דמהימני\u0004 \u0005[וגלוי לפני הקדוש ברוך הוא שמאמינים]\u0006 הם \u0003ישראל. אמר לו\u0004 הקדוש ברוך הוא למשה: \u0003הן\u0004 — \u0003מאמינים בני מאמינים, ו\u0004אילו \u0003אתה אין סופך להאמין.\u0004","\u0003הן מאמינים —\u0004 כפי שמפורש בכתוב: \u0003\"ויאמן העם\u0004 וישמעו כי פקד ה' את בני ישראל וכי ראה את עניים ויקדו וישתחוו\u0003\"\u0004 (שמות ד, לא). \u0003בני מאמינים\u0004 — שנאמר באברהם אבינו: \u0003\"והאמין בה '\u0004 ויחשבה לו צדקה\u0003\"\u0004 (בראשית טו, ו). ואילו \u0003אתה אין סופך להאמין\u0004 בך בני ישראל, וכפי \u0003שנאמר:\u0004 \"ויאמר ה' אל משה ואל אהרן \u0003יען לא האמנתם בי\u0004 להקדישני לעיני בני ישראל\" (במדבר כ, יב). \u0003ממאי\u0004 \u0005[ממה,\u0006 מנין לנו\u0005]\u0006 ש\u0003לקה\u0004 משה? \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויאמר ה' לו עוד הבא נא ידך בחיקך\u0004 ויבא ידו בחיקו ויוציאה והנה ידו מצורעת כשלג\u0003\"\u0004 (שמות ד, ו).","על אותו ענין \u0003אמר רבא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יוסי בר' חנינא: מדה טובה ממהרת לבא ממדת פורענות.\u0004 ומנין? — ש\u0003אילו במדת פורענות כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ויוציאה והנה ידו מצרעת כשלג\"\u0004 (שמות ד, ו), \u0003ואילו במדה טובה כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"\u0004ויאמר השב ידך אל חיקך וישב ידו אל חיקו \u0003ויוציאה מחיקו והנה שבה כבשרו\"\u0004 (שמות ד, ז), ונדייק: \u0003מחיקו הוא\u0004 ש\u0003שבה כבשרו,\u0004 כלומר, מיד, עוד לפני שהוציאה. כיון שהוזכר הענין מעירים בענין נס אחר שאירע שם.","על מה שנאמר \u0003\"\u0004וישליכו איש מטהו ויהיו לתנינים \u0003ויבלע מטה אהרן את מטתם\"\u0004 (שמות ז, יב), \u0003אמר ר' אלעזר:\u0004 היה זה \u0003נס בתוך נס,\u0004 שבלע המטה את התנינים לא בעודו בצורת תנין אלא בצורת מטה.","שנינו במשנה שנחלקו ר' עקיבא וחכמים בזורק \u0003מרשות היחיד לרשות היחיד\u0004 ורשות הרבים באמצע. שר' עקיבא מחייב כזורק מרשות לרשות, וחכמים פוטרים.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבה:\u0004 האם כשזרק \u0003למטה\u0004 (בתוך גובה) \u0003מעשרה\u0004 טפחים מן הקרקע \u0003פליגי\u0004 \u0005[נחלקו],\u0006 \u0003ובהא פליגי\u0004 \u0005[ובזה נחלקו],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' עקיבא \u0005סבור]\u0006 כי \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 ש\u0003קלוטה\u0004 באויר ועוברת דרכו הריהי \u0003כמה\u0004 (כמו) \u0003שהונחה,\u0004 והרי זה אם כן כאילו הונחה ממש ברשות הרבים ונחשבת כעקירה מרשות היחיד והנחה ברשות הרבים, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים \u0005סבור]\u0006 כי \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 ש\u0003קלוטה\u0004 באויר \u0003כמה שהונחה, אבל\u0004 הזורק \u0003למעלה מעשרה\u0004 טפחים — ל\u0003דברי הכל פטור, ולא ילפינן\u0004 \u0005[ואין אנו לומדים]\u0006 דין \u0003זורק מ\u0004דין \u0003מושיט.\u0004 שאף שהמושיט מרשות היחיד לרשות היחיד דרך רשות הרבים לדעת הכל חייב, אפילו למעלה מעשרה טפחים, מכל מקום הזורק בכגון זה פטור.","\u0003או דילמא\u0004 \u0005[שמא]\u0006 ב\u0003למעלה מעשרה\u0004 טפחים \u0003פליגי\u0004 \u0005[נחלקו],\u0006 \u0003ובהא פליגי\u0004 \u0005[וב\u0006דבר \u0005זהב נחלקו],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' עקיבא \u0005סבור]:\u0006 \u0003ילפינן\u0004 \u0005[למדים אנו]\u0006 דין \u0003זורק מ\u0004דין \u0003מושיט,\u0004 ולכן אף הזורק למעלה מעשרה דרך אויר רשות הרבים — חייב, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים \u0005סבור]\u0006 כי \u0003לא ילפינן\u0004 \u0005[אין אנו למדים]\u0006 \u0003זורק ממושיט, אבל למטה מעשרה\u0004 — ל\u0003דברי הכל חייב. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003קלוטה כמה שהונחה דמיא\u0004 \u0005[נחשבת].\u0006","\u0003אמר רב יוסף: הא מילתא איבעיא ליה\u0004 \u0005[דבר זה נסתפק לו]\u0006 \u0003לרב חסדא ופשטה ניהליה\u0004 \u0005[ופתר לו]\u0006 זאת \u0003רב המנונא מהא\u0004 \u0005[מ\u0006מה ששנינו בברייתא \u0005זו],\u0006 ששנינו: \u0003מרשות היחיד לרשות היחיד ועובר ברשות הרבים עצמה, ר' עקיבא מחייב וחכמים פוטרים.\u0004 ומכאן נדייק: \u0003מדקאמר\u0004 \u0005[ממה שאמר]\u0006 \u0003\"ברשות הרבים עצמה\" פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 כי ב\u0003למטה מעשרה\u0004 טפחים \u0003פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006","\u0003ובמאי\u0004 \u0005[ובמה],\u0006 באיזה סוג של העברה מרשות לרשות? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003במעביר\u0004 בידיו ממש, וכי יכול אתה לומר שכאשר העביר \u0003למטה מעשרה\u0004 — \u0003הוא דמחייב\u0004 \u0005[שמתחייב],\u0006 ואילו בשהעביר \u0003למעלה מעשרה\u0004 — \u0003לא מחייב\u0004 \u0005[אינו מתחייב]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אלעזר: המוציא\u0004 בשבת \u0003משוי\u0004 (משא) מרשות היחיד לרשות הרבים \u0003למעלה מעשרה\u0004 טפחים — \u0003חייב, שכן\u0004 היה \u0003משא בני קהת\u0004 במשכן, ומהם למדנו דין הוצאה. \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדברת הברייתא \u0003בזורק, ולמטה מעשרה הוא דמחייב\u0004 \u0005[שמתחייב],\u0006 \u0003למעלה מעשרה\u0004 — \u0003לא מחייב\u0004 \u0005[אינו מתחייב],\u0006 ואם כן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי \u0003ב\u0004שאלה האם \u0003קלוטה\u0004 באויר דינה \u0003כמה שהונחה פליגי\u0004 \u0005[נחלקו].\u0006 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה].\u0006","\u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 מסקנה זו על שיטת \u0003ר' אלעזר,\u0004 ש\u0003אמר ר' אלעזר: מחייב היה ר' עקיבא אפילו\u0004 ב\u0003למעלה מעשרה\u0004 טפחים. \u0003והאי דקתני\u0004 \u0005[וזו ששנינו]\u0006 באותה ברייתא \u0003\"רשות הרבים עצמה\"\u0004 הרי זה \u0003להודיעך כחן\u0004 (תוקף דעתם) \u0003דרבנן\u0004 \u0005[של חכמים]\u0006 שאפילו ברשות הרבים עצמה הריהם פוטרים, וכל שכן למעלה מעשרה טפחים שאינו עוד בתחומה.","\u0003ו\u0004כן \u0003פליגא\u0004 \u0005[חלוקה]\u0006 מסקנה זו שאמר ר' אלעזר על דברי \u0003רב חלקיה בר טובי,\u0004 ש\u0003אמר רב חלקיה בר טובי: תוך שלשה\u0004 טפחים לקרקע — ל\u0003דברי הכל חייב,\u0004 שמאחר וקבעו חכמים כלל שכל דבר שבתוך שלושה טפחים דינו כמחובר לו (\"לבוד\"), הרי זה אם כן כהנחה גמורה. \u0003למעלה מעשרה\u0004 — ל\u0003דברי הכל פטור. משלשה\u0004 טפחים \u0003ועד עשרה\u0004 — \u0003באנו למחלוקת ר' עקיבא ורבנן\u0004 \u0005[וחכמים].\u0006","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 כרב חלקיה: \u0003בתוך שלשה\u0004 — ל\u0003דברי הכל חייב, למעלה מעשרה\u0004 — \u0003אינו אלא משום שבות\u0004 (איסור שמדברי חכמים בהלכות שבת), שאסרו חכמים לזרוק ולהעביר חפץ מרשות היחיד השייכת לאדם אחד לרשות השייכת לאחר, בלא עירוב. \u0003ואם היו\u0004 שתיהן \u0003רשויות שלו\u0004 — \u0003מותר. משלשה\u0004 טפחים \u0003ועד עשרה\u0004 — \u0003ר' עקיבא מחייב וחכמים פוטרין.\u0004","שנינו ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא שהוזכרה ש\u0003אם היו\u0004 שתי \u0003רשויות\u0004 היחיד \u0003שלו\u0004 — \u0003מותר. לימא תהוי תיובתיה\u0004 \u0005[האם נאמר\u0006 ש\u0005תהיה\u0006 זו \u0005קושיה חמורה]\u0006 על שיטת \u0003רב, דאיתמר\u0004 \u0005[שנאמר]\u0006 שהיתה מחלוקת אמוראים בבעיה זו: \u0003שני בתים\u0004 אפילו הם שייכים לאדם אחד והיו \u0003בשני צדי רשות הרבים, רבה בר רב הונא אמר\u0004 בשם \u0003רב: אסור לזרוק\u0004 בשבת חפץ \u0003מזה לזה. ושמואל אמר: מותר לזרוק מזה לזה.\u0004 ודוחים: \u0003ולאו מי אוקימנא\u0004 \u0005[והאם לא העמדנו,\u0006 הסברנו\u0005]\u0006 כבר את ההלכה \u0003ההיא\u0004 של רב ב\u0003כגון דמידלי חד ומתתי חד, דזימנין נפל, ואתי לאתויי\u0004 \u0005[שמוגבה אחד\u0006 הבתים \u0005ונמוך אחד, ש\u0006כיון שאינו זורק למישרין \u0005לפעמים יפול\u0006 החפץ לרשות הרבים, \u0005ויבוא להביאו]\u0006 משם, ויעבור על איסור שמדברי תורה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא לרב המנונא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר \u0003רב המנונא לרב חסדא: מנא הא מילתא דאמור רבנן\u0004 \u0005[מנין דבר זה שאמרו חכמים]\u0006 ככלל: \u0003כל פחות משלושה\u0004 טפחים — \u0003כלבוד\u0004 (צמוד) \u0003דמי\u0004 \u0005[\u0006\u0005נחשב]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לפי שאי אפשר לה לרשות הרבים שתילקט\u0004 \u0005[תוחלק,\u0006 תיושר\u0005]\u0006 \u0003במלקט וברהיטני,\u0004 כיון שאי אפשר שרשות הרבים תהא חלקה לחלוטין, ויש להביא בחשבון שבתוך המציאות קיימים הבדלי גובה קטנים ברשות הרבים.","והקשה לו: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שזהו הטעם, אם כן \u0003שלשה\u0004 טפחים \u0003נמי\u0004 \u0005[גם כן]\u0006 מדוע אינם נחשבים כלבוד אלא רק פחות משלושה? \u0003ותו, הא דתנן\u0004 \u0005[ועוד,\u0006 הלכה \u0005זו ששנינו\u0006 במשנה\u0005]\u0006 בדיני סוכה: \u0003המשלשל דפנות\u0004 של סוכה \u0003מלמעלה למטה, אם הן גבוהין מן הארץ\u0004 למטה \u0003שלשה טפחים\u0004 — \u0003פסולה,\u0004 שנחשבת הסוכה כחסרת דפנות, ומכאן נסיק: \u0003הא\u0004 \u0005[הרי]\u0006 שאם שלשל את הדפנות \u0003פחות משלשה\u0004 טפחים לקרקע — \u0003כשרה,\u0004 וכאן הלא אין מקום לנימוק שאין אפשרות להחליק את קרקע רשות הרבים.","ודחה: \u0003התם היינו טעמא\u0004 \u0005[שם זהו הטעם]\u0006 שחלל שהוא גדול משלושה טפחים אינו נחשב כמחיצה משום שמחיצה כזאת אינה משמשת עוד לתפקידה, \u0003משום דהויא לה\u0004 \u0005[שהרי היא]\u0006 \u0003מחיצה שהגדיים בוקעין\u0004 (עוברים) \u0003בה.\u0004 ורק בפחות משלושה טפחים שוב אינם יכולים לעבור. ועוד הקשה לו קושיה אחרת: \u0003תינח\u0004 \u0005[נניח]\u0006 להסבר זה כשהרווח של שלושה טפחים הוא \u0003למטה\u0004 כלפי הקרקע, שאפשר לומר שביותר מזה שוב אינו מחיצה, אבל דין פחות משלושה טפחים האמור בכמה הלכות כאשר החלל הוא \u0003למעלה,\u0004 וכגון באופן שהסכך מרוחק מן הדפנות, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 להסברתו? \u0003אלא\u0004 יש לסכם כי הלכה זו ש\u0003כל פחות משלשה כלבוד דמי\u0004 \u0005[נחשב]\u0006 — \u0003הלכתא גמירי לה\u0004 \u0005[\u0006כ\u0005הלכה\u0006 למשה מסיני \u0005היא נלמדת].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא מקרה הנידון לאיסור בדומה לזה המובא במשנה: הזורק חפץ \u0003מרשות הרבים לרשות הרבים ורשות היחיד באמצע\u0004 — \u0003רבי מחייב\u0004 משום הוצאה לרשות היחיד, \u0003וחכמים פוטרין.\u0004 ועל כך שנינו כי \u0003רב ושמואל דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003לא חייב רבי אלא ברשות היחיד מקורה\u0004 בגג הנמצאת בין שתי רשויות הרבים, שבמקרה כזה \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 כי \u0003ביתא כמאן דמליא דמי\u0004 \u0005[הבית נחשב כממולא]\u0006 וחפץ העובר בתוך בית נחשב אם כן כאילו נח על גבי דבר ממשי, \u0003אבל\u0004 ברשות היחיד \u0003שאינו מקורה\u0004 הוא \u0003לא\u0004 חייב אפילו לדעת רבי. ובנושא זה \u0003אמר רב חנא\u0004 שכך \u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: מחייב היה רבי\u0004 במקרה זה \u0003שתים,\u0004 שתי חטאות: \u0003אחת משום הוצאה\u0004 מרשות היחיד לרשות הרבים (השניה), \u0003ואחת משום הכנסה,\u0004 כשנכנס החפץ בתחילה לרשות היחיד.","ומסופר כי \u0003יתיב\u0004 \u0005[יושב היה]\u0006 \u0003רב חנא וקא קשיא ליה\u0004 \u0005[והיה מתקשה\u0006 בדבר זה\u0005]:\u0006"],["\u0003למימרא\u0004 \u0005[האם נאמר]\u0006 ש\u0003מחייב רבי\u0004 על \u0003תולדה במקום אב\u0004 מלאכה? שהרי הכנסה והוצאה הם אב מלאכה ותולדתה!","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003רבי אומר,\u0004 מצות שבת נאמרה במלים \"אלה הדברים אשר ציוה ה' לעשות אותם\" (שמות לה, א), ומביטוי זה יכולים אנו ללמוד כמה הלכות, שכן די היה לומר \"דבר\" וכשאומר \u0003\"דברים\"\u0004 — הרי שנים (שמיעוט רבים — שנים), וכשאומר \u0003\"הדברים\"\u0004 מרבה על ידי תוספת ה־ה' הנוספת — שלישי, והמלה \"אלה\" שבכתוב \u0003\"אלה הדברים\"\u0004 עולה בגימטריא שלושים ושש, הרי יחד \u0003אלו שלשים ותשע מלאכות שנאמרו למשה בסיני.\u0004 וכיון שרבי סבור שיש מספר קבוע של אבות מלאכות, בודאי יחייב רק על האבות ולא על התולדות!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף: מר אהא מתני לה, וקשיא ליה\u0004 \u0005[אדוני על זה שונה אותה,\u0006 את דברי רב יהודה, \u0005וקשה לו]\u0006 אם כן מדברי \u0003רבי\u0004 על דברי \u0003רבי,\u0004 ואולם \u0003אנן\u0004 \u0005[אנחנו]\u0006 על דברי \u0003ר' יהודה מתנינן\u0004 \u0005[שונים אנו]\u0006 אותה \u0003ו\u0004לכן \u0003לא קשיא לן\u0004 \u0005[קשה לנו].\u0006","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 זרק חפץ \u0003מרשות היחיד לרשות הרבים ועבר ארבע אמות ברשות הרבים\u0004 — \u0003ר' יהודה מחייב וחכמים פוטרין.\u0004","ועל כך \u0003אמר רב יהודה אמר שמואל: מחייב היה ר' יהודה שתים; אחת משום הוצאה\u0004 מרשות היחיד לרשות הרבים \u0003ואחת משום העברה\u0004 ארבע אמות ברשות הרבים, ואילו חכמים פוטרים בהעברה. ובעל כורחנו עלינו לפרש כך: \u0003דאי סלקא דעתך חדא\u0004 \u0005[שאם יעלה על\u0006 \u0003דעתך\u0004 לומר ש\u0005אחת]\u0006 \u0003הוא\u0004 ש\u0003מחייב\u0004 ר' יהודה, אם כן \u0003מכלל\u0004 הדברים אתה למד \u0003דרבנן פטרי\u0004 \u0005[שחכמים פוטרים]\u0006 \u0003לגמרי,\u0004 וכיצד יתכן הדבר? \u0003הא אפיק לה\u0004 \u0005[הרי הוציא אותה,\u0006 את החפץ\u0005]\u0006 \u0003מרשות היחיד לרשות הרבים.\u0004 את ההוכחה הזאת דוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 מסיק אתה מסקנה זו? \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי \u0003ר' יהודה חדא\u0004 \u0005[אחת]\u0006 \u0003הוא\u0004 ש\u0003מחייב, ורבנן פטרי\u0004 \u0005[וחכמים פוטרים]\u0006 \u0003לגמרי, והיכי משכחת ליה\u0004 \u0005[וכיצד מוצא אתה\u0006 אפשרות \u0005כעין זו?]\u0006 — \u0003כגון\u0004 ש\u0003אמר עד דנפקא לה\u0004 \u0005[שתצא]\u0006 \u0003לרשות הרבים\u0004 רצוני ש\u0003תנוח\u0004 מיד.","\u0003ובהא קמיפלגי\u0004 \u0005[ובזה נחלקו]\u0006 ש\u0003ר' יהודה סבר\u0004 \u0005[סבור]\u0006 כי \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 ומקבלים את הכלל \u0003קלוטה\u0004 באויר \u0003כמה\u0004 (כמו) \u0003שהונחה\u0004 ממש, \u0003ו\u0004ממילא \u0003איתעבידא ליה\u0004 \u0005[נעשתה לו]\u0006 \u0003מחשבתו,\u0004 שכיון שנקלט החפץ באויר רשות הרבים הרי זה כמונח ברשות זו עצמה. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 כי \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003קלוטה כמה שהונחה, ו\u0004ממילא \u0003לא איתעבידא ליה\u0004 \u0005[נעשתה לו]\u0006 \u0003מחשבתו,\u0004 ופטור על מלאכה זו! \u0003אבל\u0004 על \u0003תולדה במקום אב לא מחייב ר' יהודה.\u0004","את ההסבר הזה דוחים: \u0003לא סלקא דעתך\u0004 \u0005[\u0006יכול \u0005לעלות על דעתך]\u0006 לומר כך, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' יהודה מוסיף\u0004 למנין המלאכות \u0003אף\u0004 את \u0003השובט\u0004 (מותח את חוט הערב) \u0003והמדקדק\u0004 (המשווה ומיישר את חוטי האריג). \u0003אמרו לו\u0004 חכמים: \u0003שובט הרי הוא בכלל\u0004 מלאכת \u0003מיסך, מדקדק הרי הוא בכלל\u0004 מלאכת \u0003אורג.\u0004 ומעתה, \u0003מאי לאו דעבדינהו לתרווייהו בהדי הדדי\u0004 \u0005[האם לא\u0006 מדובר באופן \u0005שעשה את שתיהן,\u0006 שובט ומיסך, \u0005יחד],\u0006 \u0003ושמע מינה\u0004 \u0005[ולמד ממנה]\u0006 כי \u0003מחייב היה ר' יהודה\u0004 על \u0003תולדה במקום אב!\u0004","את ההוכחה הזאת דוחים: \u0003ממאי\u0004 \u0005[ממה,\u0006 מנייין\u0005]\u0006 סמך לדבריך אלה? \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003לעולם\u0004 מדובר באופן \u0003דעבדה להא לחודה, והא לחודה\u0004 \u0005[שעשתה את\u0006 זו לחוד, לעצמה, \u0005ואת זו לחוד]\u0006 \u0003ור' יהודה\u0004 על \u0003תולדה במקום אב לא מחייב, ובהא קמיפלגי\u0004 \u0005[\u0006\u0005וב\u0006עקרון \u0005זה נחלקו]\u0006 ר' יהודה וחכמים: ש\u0003ר' יהודה סבר\u0004 \u0005[סבור]\u0006 כי \u0003הני\u0004 \u0005[אלה]\u0006 השובט והמדקדק \u0003אבות\u0004 נוספים \u0003נינהו\u0004 \u0005[הם],\u0006 \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 כי \u0003הני\u0004 \u0005[אלה]\u0006 \u0003תולדות נינהו\u0004 \u0005[הם].\u0006","\u0003תדע\u0004 שכן הוא, \u0003דקתני\u0004 \u0005[ששנינו]\u0006 בלשון \u0003\"ר' יהודה מוסיף\",\u0004 ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי כוונת ר' יהודה שאלו הם \u0003אבות,\u0004 אם כן \u0003מאי\u0004 \u0005[מה\u0006 המשמעות\u0005]\u0006 של הביטוי \u0003\"מוסיף\"\u0004 — \u0003מוסיף אבות. אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי הכוונה ל\u0003תולדות\u0004 — \u0003מאי\u0004 \u0005[מה\u0006 משמעות\u0005]\u0006 הביטוי \u0003\"מוסיף\"? איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 כי \u0003רבה ורב יוסף דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003לא חייב ר' יהודה אלא אחת.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: ולמאי דסליק אדעתין מעיקרא\u0004 \u0005[ולפי מה שעלה על דעתינו מתחילה]\u0006 כי \u0003מחייב היה ר' יהודה שתים\u0004 הרי יש להקשות כיצד יתכן שנתכוון גם להוצאה מרשות היחיד וגם להעברה ברשות הרבים? שכן \u0003אי להכא קבעי לה\u0004 \u0005[אם לכאן\u0006 להוציא לרשות הרבים בלבד \u0005רצה אותה]\u0006 — \u0003להכא\u0004 \u0005[לכאן]\u0006 שתעבור ארבע אמות לרשות הרבים \u0003לא קבעי לה\u0004 \u0005[רצה אותה].\u0006 וכן, \u0003אי להכא קבעי לה\u0004 \u0005[אם לכאן,\u0006 להעברה ברשות הרבים, \u0005רצה אותה]\u0006 — \u0003להכא\u0004 \u0005[לכאן]\u0006 להוצאה מרשות היחיד \u0003לא קבעי לה\u0004 \u0005[רצה אותה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי לרבינא: יש ליישב ולומר כי מדובר כאן \u0003באומר \"כל מקום שתרצה\u0004 — \u0003תנוח\",\u0004 שגילה דעתו מתחילה שהוא מרוצה בכל מלאכה שתיעשה על ידי החפץ שזרק.","כיון שדובר בעניין זריקה של חפץ בשבת בין רשויות שונות ובתוך רשות אחת, מביאים כאן כמה דברים בענין כוונה בזריקה. ואומרים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 כי אם \u0003נתכוון לזרוק\u0004 למרחק \u0003שמנה\u0004 אמות ברשות הרבים, \u0003וזרק\u0004 בפועל רק \u0003ארבע\u0004 — חייב, ש\u0003הרי\u0004 זה דומה למקרה ש\u0003כתב \"שם\" מ\"שמעון\",\u0004 שלא השלים כל כתיבת המלה אבל רשם במקומה מלה קטנה אחרת, שהרי עשה מלאכה בשיעור המינימלי. אלא יש לשאול: אם \u0003נתכוון לזרוק ארבע וזרק שמנה\u0004 — \u0003מהו\u0004 הדין בכגון זה? וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 \u0003הא אפיק ליה\u0004 \u0005[הרי\u0006 מכל מקום \u0005הוציא אותו,\u0006 את החפץ\u0005],\u0006 \u0003או דילמא\u0004 \u0005[שמא]:\u0006 \u0003היכא דבעי, הא\u0004 \u0005[במקום שרצה הזורק\u0006 שינוח החפץ, \u0005הרי]\u0006 בסופו של דבר \u0003הוא לא נח.\u0004 על כך אומרים: \u0003ולאו היינו\u0004 \u0005[ו\u0006האם \u0003אין זה]\u0004 בדיוק מה ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי,\u0004 וכפי שהוזכר מקודם, \u0003ואמר ליה\u0004 \u0005[לו]\u0006 רב אשי כתשובה כי מדובר \u0003באומר \"כל מקום שתרצה תנוח\",\u0004 ורק באופן זה מתחייב אם זרק יותר או פחות מן השיעור שהתכוון לו.","ולהיפך, לנקודה הראשונה שלכאורה היתה מובנת מאליה, היא הצריכה בירור, \u0003ודקאמרת\u0004 \u0005[ומה שאמרת]\u0006 \u0003הרי כתב \"שם\" מ\"שמעון\", מי דמי\u0004 \u0005[האם\u0006 זה \u0005דומה]?\u0006 הלא \u0003התם\u0004 \u0005[שם]\u0006 כל \u0003כמה\u0004 ש\u0003לא כתיב\u0004 \u0005[כתב]\u0006 את האותיות \u0003\"שם\"\u0004 (כלומר, \"שמ\") — \u0003לא מכתיב ליה\u0004 \u0005[תיכתב לו]\u0006 המלה \u0003\"שמעון\",\u0004 ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 בזריקת שמונה \u0003כאשר ברצונו היה לזרוק ארבע בלבד, וכי כל כמה דלא זריק\u0004 \u0005[שאינו זורק]\u0006 \u0003ארבע\u0004 אמות — \u0003לא מיזדרקי ליה תמני\u0004 \u0005[ייזרקו לו שמונה]?!\u0006 שהרי לזריקת שמונה אמות אין צורך בשתי זריקות בודדות של ארבע אמות כל אחת, ושאלה זו עדיין צריכה פתרון.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הזורק\u0004 בשבת חפץ \u0003מרשות הרבים לרשות הרבים ורשות היחיד באמצע,\u0004 בין אותן שתי רשות הרבים, אם בסך הכל זרק \u0003ארבע אמות\u0004 ברשות הרבים משני עברי רשות היחיד — \u0003חייב\u0004 משום העברת ארבע אמות ברשות הרבים"]]};
